(window.GIM_TP=window.GIM_TP||{})["Z.Chukat.0"]={"from":0,"a":[[[],[],[]],[["וַיְדַבֵּר יְיָ אֶל מֹשֶׁה וְאֶל אַהֲרֹן לֵאמֹר (במדבר י״ט:א׳-ב׳) זֹאת חֻקַּת הַתּוֹרָה אֲשֶׁר צִוָּה יְיָ לֵאמֹר וְגוֹ'. רִבִּי יוֹסֵי פָּתַח, (דברים ד׳:מ״ד) וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה לִפְנֵי בְּנֵי יִשְׂרָאֵל. תָּא חֲזֵי, מִלִּין דְּאוֹרַיְיתָא קַדִּישִׁין אִינּוּן, עִלָּאִין אִינּוּן, מְתִיקִין אִינּוּן. כְּמָה דִּכְתִּיב, (תהילים י״ט:י״א) הַנֶּחֱמָדִים מִזָּהָב וּמִפָּז רָב וּמְתוּקִים מִדְּבַשׁ וְגוֹ'. מַאן דְּאִשְׁתְּדַל בְּאוֹרַיְיתָא, כְּאִלּוּ קָאִים כָּל יוֹמָא עַל טוּרָא דְּסִינַי וְקַבִּיל אוֹרַיְיתָא. הֲדָא הוּא דִכְתִיב, (דברים כ״ז:ט׳) הַיּוֹם הַזֶּה נִהְיֵיתָ לְעָם. וְהָא אוּקְמוּהָ חַבְרַיָּיא.","כְּתִיב הָכָא זֹאת חֻקַּת הַתּוֹרָה, וּכְתִיב וְזֹאת הַתּוֹרָה, מַה בֵּין הַאי לְהַאי. אֶלָּא רָזָא עִלָּאָה הוּא, וְהָכִי אוֹלִיפְנָא, וְזֹאת הַתּוֹרָה: לְאַחֲזָאָה כֹּלָּא בְּיִחוּדָא חַד, וּלְאַכְלְלָא כְנֶסֶת יִשְׂרָאֵל בְּקוּדְשָׁא בְּרִיךְ הוּא, לְאִשְׁתַּכְּחָא כֹּלָּא חַד. בְּגִינֵי כַּךְ וְזֹאת הַתּוֹרָה. אֲמַאי תּוֹסֶפֶת וָא\"ו. אֶלָּא הָא אִתְּמַר, לְאַחֲזָאָה דְּכֹלָּא חַד, בְּלָא פִּרוּדָא. וְזֹאת: כְּלַל וּפְרָט כַּחֲדָא, דְּכַר וְנוּקְבָּא. וּבְגִין כָּךְ וְזֹאת הַתּוֹרָה וַדַּאי. אֲבָל זֹאת בְּלָא תּוֹסֶפֶת וָא\"ו, חֻקַּת הַתּוֹרָה וַדַּאי, וְלָא הַתּוֹרָה, דִּינָא דְּאוֹרַיְיתָא, גְּזֵרָה דְּאוֹרַיְיתָא.","תָּא חֲזֵי, (במדבר ח׳:כ״ד) זֹאת אֲשֶׁר לַלְוִיִּם, וְלָא וְזֹאת. דְּהָא מִסִּטְרָא דְּדִינָא (קשיא) קָא אַתְיָין, וְלָא מִסִּטְרָא דְּרַחֲמֵי. אָמַר רִבִּי יְהוּדָה, וְהָא כְּתִיב (במדבר ד׳:י״ט) וְזֹאת עֲשׂוּ לָהֶם וְחָיוּ. וְדָא בְּלֵיוָאֵי אִתְּמַר, וְאַתְּ אַמְרַת זֹאת וְלָא וְזֹאת. אָמַר לֵיהּ, וַדַּאי הָכִי הוּא, וּקְרָא מוֹכַח, מַאן דְּאָחִיד סָמָא דְּמוֹתָא, אִי לָא יְעָרַב בֵּיהּ סָמָא דְּחַיֵּי, הָא וַדַּאי יְמוּת. וְעַל דָּא, וְזֹאת עֲשׂוּ לָהֶם וְחָיוּ, וְלֹא יָמוּתוּ, בְּגִין דְּסָמָא דְּחַיֵּי מְעֻרָב בַּהֲדֵיהּ, וְזֹאת עֲשׂוּ וְחָיוּ וְלֹא יָמוּתוּ, וַדַּאי וְזֹאת אִצְטְרִיךְ לְהוּ, וְלָא זֹאת. בְּגִינֵי כַּךְ וְזֹאת הַתּוֹרָה מַמָּשׁ, בְּיִחוּדָא חַד, בְּיִחוּדָא שְׁלִים, כְּלָלָא דִּדְכַר וְנוּקְבָּא. ו\"ה. זֹאת: ה' בִּלְחוֹדוֹי, וְעַל דָּא זֹאת חוּקַּת הַתּוֹרָה."],[[0,"וידבר וגו' זאת חקת התורה וגו':","ר' יוסי פתח, וזאת התורה אשר שם משה לפני בני ישראל. בוא וראה, דברי תורה, קדושים הם, עליונים הם, מתוקים הם, כמ\"ש הנחמדים מזהב ומפז רב ומתוקים מדבש וגו'. מי שעוסק בתורה, הוא, כאלו עומד כל יום על הר סיני ומקבל התורה. ז\"ש היום הזה נהיית לעם. וכבר העמידו החברים."],[1,"כתיב הכא זאת וכו':","כתוב כאן זאת חקת התורה. וכתוב, וזאת התורה, ולא כתוב חקת. מה בין זה לזה. ומשיב, אלא סוד עליון הוא, וכך למדנו, \u0003וזאת התורה,\u0004 הוא להראות שהכל הוא ביחוד אחד, ולכלול כנסת ישראל, שהיא המלכות, בהקב\"ה, שהוא ז\"א, שימצא הכל אחד, משום זה, \u0003וזאת התורה.\u0004 למה יש תוספת \u0003ו'\u0004 על \u0003זאת,\u0004 אלא הרי למדנו, שהוא להראות, שהכל אחד בלא פרוד. \u0003וזאת,\u0004 הוא כלל ופרט יחד, דהיינו דכר ונוקבא יחד, כי \u0003ו'\u0004 הוא דכר, דהיינו ז\"א, שהוא כלל. \u0003זאת,\u0004 היא נוקבא, דהיינו המלכות שהיא פרט, ומשום זה כתוב ודאי וזאת התורה, שיורה על ז\"א ונוקבא ביחוד אחד. אבל \u0003זאת\u0004 בלא תוספת \u0003ו',\u0004 היא חוקת התורה ודאי, שהיא המלכות הנקראת חוקה, ובאה מז\"א שנקרא תורה, ולא התורה עצמה, שהוא ז\"א, רק דין התורה גזרת התורה שהוא מלכות."],[2,"ת\"ח זאת אשר וכו':","בוא וראה, כתוב, זאת אשר ללוים, ולא כתוב \u0003וזאת\u0004 עם \u0003ו',\u0004 משום שמצד הדין הם באים דהיינו מצד שמאל ומצד המלכות הנבנית משמאל, ולא מצד הרחמים, שהוא ז\"א, ע\"כ כתוב \u0003זאת\u0004 בלא \u0003ו',\u0004 דהיינו מלכות בלא ז\"א. א\"ר יהודה הרי כתוב, \u0003וזאת\u0004 עשו להם וחיו, דהיינו \u0003זאת\u0004 עם \u0003ו',\u0004 וזה נאמר בלוים, ואתה אומר שהלוים הם בחינת זאת, ולא וזאת. א\"ל ודאי כך הוא, שהם בחינת וזאת, והכתוב מוכיח, כי מי שאוחז סם המות אם לא יערב בו סם חיים, הרי ימות ודאי, וע\"כ כתוב, \u0003וזאת\u0004 עשו להם וחיו, דהיינו שתתחבר \u0003זאת\u0004 שה\"ס המלכות הנקראת אילן המות, עם \u0003ו',\u0004 שהוא ז\"א, שהוא עץ החיים, \u0003ולא ימותו.\u0004 משום שסם חיים מעורב עמו, וע\"כ, וזאת עשו וחיו ולא ימותו, כי \u0003וזאת\u0004 צריך להם ולא \u0003זאת.\u0004 משום זה, הכתוב, \u0003וזאת התורה,\u0004 יורה, שהוא ממש ביחוד אחד, ביחוד שלם, דכד ונוקבא בכלל אחד, שה\"ס ו'\"ה. אבל \u0003זאת\u0004 בלבדה בלא \u0003ו',\u0004 הוא \u0003ה'\u0004 לבדה בלי \u0003ו',\u0004 דהיינו מלכות בלא ז\"א, ועל זה כתוב \u0003זאת\u0004 חוקת התורה."]],[[0,"","וַיְדַבֵּר ה' אֶל מֹשֶׁה וְאֶל אַהֲרֹן לֵאמֹר זֹּאת חֻקַּת הַתּוֹרָה אֲשֶׁר צִוָּה ה' לֵאמֹר וְגוֹ'. רַבִּי יוֹסֵי פָּתַח, (דברים ד) וְזֹּאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה לִפְנֵי בְּנֵי יִשְׂרָאֵל. בֹּא וּרְאֵה, דִּבְרֵי הַתּוֹרָה הֵם קְדוֹשִׁים, הֵם עֶלְיוֹנִים, הֵם מְתוּקִים, כְּמוֹ שֶׁכָּתוּב (תהלים יט) הַנֶּחֱמָדִים מִזָּהָב וּמִפָּז רָב וּמְתוּקִים מִדְּבַשׁ וְגוֹ'. מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה כְּאִלּוּ עוֹמֵד כָּל יוֹם עַל הַר סִינַי וּמְקַבֵּל הַתּוֹרָה. זֶהוּ שֶׁכָּתוּב (דברים כז) הַיּוֹם הַזֶּה נִהְיֵיתָ לְעָם. וְכָךְ פֵּרְשׁוּהוּ הַחֲבֵרִים."],[1,"","כָּתוּב כָּאן זֹּאת חֻקַּת הַתּוֹרָה, וְכָתוּב וְזֹּאת הַתּוֹרָה. מַה בֵּין זֶה לָזֶה? אֶלָּא סוֹד עֶלְיוֹן הוּא, וְכָךְ לָמַדְנוּ: וְזֹּאת הַתּוֹרָה, לְהַרְאוֹת הַכֹּל בְּיִחוּד אֶחָד וּלְהַכְלִיל כְּנֶסֶת יִשְׂרָאֵל בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, לְהִמָּצֵא הַכֹּל אֶחָד. בִּגְלַל זֶה וְזֹּאת הַתּוֹרָה. לָמָּה תּוֹסֶפֶת וָא\"ו? אֶלָּא זֶה נֶאֱמַר לְהַרְאוֹת שֶׁהַכֹּל אֶחָד, לְלֹא פֵרוּד. וְזֹּאת - כְּלָל וּפְרָט כְּאֶחָד, זָכָר וּנְקֵבָה. וּמִשּׁוּם זֶה וְזֹּאת הַתּוֹרָה וַדַּאי. אֲבָל זֹּאת בְּלֹא תוֹסֶפֶת וָא\"ו, חֻקַּת הַתּוֹרָה וַדַּאי, וְלֹא הַתּוֹרָה, דִּין הַתּוֹרָה, גְּזֵרַת הַתּוֹרָה."],[2,"","בֹּא וּרְאֵה, (במדבר ח) זֹּאת אֲשֶׁר לַלְוִיִּם, וְלֹא וְזֹּאת. שֶׁהֲרֵי מִצַּד הַדִּין (הקשה) הֵם בָּאִים, וְלֹא מִצַּד הָרַחֲמִים. אָמַר רַבִּי יְהוּדָה, וַהֲרֵי כָּתוּב (במדבר ד) וְזֹּאת עֲשׂוּ לָהֶם וְחָיוּ. וְזֶה בַּלְוִיִּם נֶאֱמַר, וְאַתָּה אָמַרְתָּ זֹּאת, וְלֹא וְזֹּאת. אָמַר לוֹ, וַדַּאי כָּךְ זֶה, וְהַפָּסוּק מוֹכִיחַ. מִי שֶׁאוֹחֵז סַם הַמָּוֶת, אִם לֹא יְעָרֵב בּוֹ סַם הַחַיִּים, הֲרֵי וַדַּאי יָמוּת. וְעַל זֶה, וְזֹּאת עֲשׂוּ לָהֶם וְחָיוּ וְלֹא יָמֻתוּ, מִשּׁוּם שֶׁסַּם הַחַיִּים מְעֹרָב אִתּוֹ. וְזֹּאת עֲשׂוּ וְחָיוּ וְלֹא יָמֻתוּ, וַדַּאי וְזֹּאת צָרִיךְ לָהֶם, וְלֹא זֹּאת. מִשּׁוּם כָּךְ וְזֹּאת הַתּוֹרָה מַמָּשׁ, בְּיִחוּד אֶחָד, בְּיִחוּד שָׁלֵם, כְּלַל שֶׁל זָכָר וּנְקֵבָה. ו\"ה. זֹּאת - ה' בִּלְבַדָּהּ, וְעַל זֶה זֹּאת חֻקַּת הַתּוֹרָה."]]],[["רִבִּי שִׁמְעוֹן וְרִבִּי אַבָּא וְרִבִּי אֶלְעָזָר וְרִבִּי יִצְחָק, הֲווֹ שְׁכִיחֵי בְּבֵי רִבִּי פִּנְחָס בֶּן יָאִיר, אָמַר רִבִּי פִּנְחָס לְרִבִּי שִׁמְעוֹן, בְּמָטוֹתָא מִנָּךְ אַנְתְּ דְּאוּקְמֵי עֲלָךְ לְעֵילָּא, וּמִילָּךְ בְּאִתְגַּלְיָיא, מַה דְּלָא אִתְיְהִיב רְשׁוּתָא לְבַּר נָשׁ אַחֲרָא. בְּפַרְשְׁתָּא דָּא אֵימָא מִלָּה חַדְתָּא, אָמַר לֵיהּ וּמַאי הִיא. אָמַר לֵיהּ זֹאת חֻקַּת הַתּוֹרָה. אָמַר לֵיהּ הָא שְׁאַר חַבְרַיָיא יֹאמְרוּ. אָמַר לְרִבִּי אֶלְעָזָר בְּרֵיהּ, אֶלְעָזָר קוּם בְּקִיּוּמָךְ, וְאֵימָא מִלָּה חַד בְּפַרְשְׁתָּא דָּא, וְחַבְרַיָּיא יֵימְרוּן אֲבַתְרָךְ.","קָם רִבִּי אֶלְעָזָר וְאָמַר, (רות ד׳:ז׳) וְזֹאת לְפָנִים בְּיִשְׂרָאֵל עַל הַגְּאוּלָה וְעַל הַתְּמוּרָה לְקַיֵּים וְגוֹ'. הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, וְאִי אִינּוּן קַדְמָאֵי עַבְדֵּי הַסְכָּמָה דָּא בְּדִינָא דְּאוֹרַיְיתָא, וְאָתוּ בַּתְרָאֵי וּבִטְלוּהָ, אֲמַאי בִּטְלוּהָ. וְהָא מַאן דְּבָטִיל מִלָּה דְּאוֹרַיְיתָא. כְּאִילּוּ חָרִיב עָלְמָא שְׁלִים. וְאִי לָאו אִיהוּ בְּדִינָא דְּאוֹרַיְיתָא, אֶלָּא הַסְכָּמָה בְּעָלְמָא, אֲמַאי נַעַל הָכָא.","אֶלָּא וַדַּאי בְּדִינָא דְּאוֹרַיְיתָא הֲוָה, וּבְרָזָא עִלָּאָה אִתְעָבִידַת מִלָּה, וּבְגִין דַּהֲווֹ קַדְמָאֵי חֲסִידֵי זַכָּאֵי, מִלָּה דָּא אִתְגַּלְיָיא בֵּינַיְיהוּ, וּמִדְּאַסְגִּיאוּ חַיָּיבֵי בְּעָלְמָא, אִתְעָבִידַת (אעברו) הַאי מִלָּה בְּגַוְונָא אַחֲרָא, בְּגִין לְאִתְכַּסָּאָה מִלִּין דְּאִינּוּן בְּרָזָא עִלָּאָה. (והא אוקמוה)","תָּא חֲזֵי, (שמות ג׳:ה׳) וַיֹּאמֶר אַל תִּקְרַב הֲלוֹם שַׁל נְעָלֶיךָ מֵעַל רַגְלֶיךָ וְגוֹ'. וְכִי אֲמַאי נַעַל הָכָא. אֶלָּא אִתְּמַר, דְּפָקִיד לֵיהּ עַל אִתְּתָא, לְאִתְפָּרְשָׁא מִנָּהּ, וּלְאִזְדַּוְּוגָא (ס\"א באתר) בְּאִתְּתָא אַחֲרָא, דִּנְהִירוּ קַדִּישָׁא עִלָּאָה, וְאִיהִי שְׁכִינְתָּא.","וְהַהוּא נַעַל אוֹקִים לֵיהּ בַּאֲתָר אַחֲרָא, (ס\"א ואיהי שכינתא) אַעְבָּר לֵיהּ מֵהַאי עָלְמָא, וְאוֹקִים לֵיהּ בְּעָלְמָא אַחֲרָא. וְעַל דָּא, כָּל מַה דְּיָהִיב מִיתָא לְבַר נָשׁ בְּחֶלְמָא טַב. נָטִיל מָאנֵיהּ מִן בֵּיתָא בִּישׁ, כְּגוֹן סַנְדָלֵיהּ. מַאי טַעְמָא. בְּגִין דְּאַעְבָּר רַגְלֵיהּ, דְּאִינּוּן קִיוּמָא דְּבַר נָשׁ, מֵהַאי עָלְמָא, וְכָנִישׁ לוֹן לְעָלְמָא אַחֲרָא, אֲתָר דְּמוֹתָא שָׁארֵי בֵּיהּ, דִּכְתִּיב, (שיר השירים ז׳:ב׳) מַה יָפוּ פְעָמַיִךְ בַּנְעָלִים בַּת נָדִיב. (מאי היא בת נדיב דא בת אברהם דכתיב, (תהילים מ״ז:י׳) נדיבי עמים נאספו עם אלהי אברהם ולא אלהי יצחק) וְרָזָא דְּמִלָּה בֵּין חַבְרַיָּיא אִיהוּ.","וְדָא כַּד מִיתָא נָטִיל לוֹן, אֲבָל בְּזִמְנָא דְּחַיָּיא שָׁלִיף מָסָאנֵיהּ, וְיָהִיב לְבַר נָשׁ אַחֲרָא, בְּגִין לְקַיְּימָא קְיָּים, קָא עָבִיד בִּגְזֵרָה דִּלְעֵילָּא. נַעַל דַּחֲלִיצָה, כְּגַוְונָא דִּלְעֵילָּא נַעַל אַחֲרָא, וְכֹלָּא אֲתָר חַד (ס\"א כלא אתיחד) (נ\"א רזא חדא).","תָּא חֲזֵי, הַהוּא מִיתָא דְּאִסְתַּלָּק מֵעָלְמָא בְּלָא בְּנִין, הַאי בַּת נָדִיב לָא כְּנִישַׁת לֵיהּ לְהַהוּא בַּר נָשׁ לְגַבָּהּ, וְאָזִיל לְאִתְטָרְדָא בְּעָלְמָא, דְּלָא אַשְׁכַּח אֲתָר, וְקוּדְשָׁא בְּרִיךְ הוּא חָיִיס עָלֵיהּ וּפָקִיד לְאָחוּהִי לְמִפְרַק לֵיהּ, לְאָתָבָא וּלְאִתְתַּקְנָא בְּעַפְרָא אַחֲרָא. כְּמָה דִּכְתִּיב, (איוב ל״ד:ט״ו) וְאָדָם עַל עָפָר יָשׁוּב (קע\"ז ע\"א) וְאוֹקְמוּהָ.","וְאִי הַהוּא פָּרוּקָא לָא בָּעֵי לְקַיְּימָא לְאָחוּהִי בְּהַאי עָלְמָא, בָּעֵי לְמִקְטַר חַד נַעַל בְּרַגְלֵיהּ, וְהַהוּא אִתְּתָא דְּתִשְׁרֵי לֵיהּ וּמְקַבְּלָא לְהַהוּא נַעַל לְגַבָּהּ. אֲמַאי נַעַל. אֶלָּא בְּגִין דְּהַהוּא נַעַל בְּגִין מִיתָא הוּא (ס\"א בגין דההוא נעל קיומא דמיתא הוא בהאי עלמא), וְאִתְיְהִיב בְּרַגְלֵיהּ דְּחַיָּיא אָחוּהִי, וְאִתְּתָא מְקַבְּלָהּ לְהַהוּא נַעַל לְגַבָּהּ, לְאַחֲזָאָה דְּהָא הַהוּא מִיתָא בֵּין חַיָּיא אַהְדָּר בְּעוֹבָדָא דָּא.","וְהוּא בְּהִפּוּכָא מֵהַהוּא נַעַל דְּנָטִיל מִיתָא מֵחַיָּיא, וְהַשְׁתָּא הַאי נַעַל נָטִיל חַיָיא מִמִּיתָא, וּבְהַהוּא נַעַל הַהוּא מִיתָא אָזִיל בֵּין חַיָיא, (נ\"א ובעי נעל דההוא מיתא דא אזיל ביה בחיוהי) וְאִתְּתָא נַטְלָא לֵיהּ לְגַבָּהּ, לְאַחֲזָאָה דְּהַהִיא אִתְּתָא עֲטֶרֶת בַּעְלָהּ, נַטְלָא לֵיהּ וּמְקַבְּלָא לֵיהּ לְגַבָּהּ.","וּבָעֵי לְבַטְּשָׁא לֵיהּ לְהַהוּא נַעַל בְּאַרְעָא, לְאַחֲזָאָה דְּשָׁכִיךְ גּוּפֵיהּ דְּהַהוּא מִיתָא. וְקוּדְשָׁא בְּרִיךְ הוּא לְזִמְנָא דָּא, אוֹ לְבָתַר זִמְנָא, חָיִיס עָלֵיהּ, וִיקַבֵּל לֵיהּ לְעָלְמָא אַחֲרָא. תּוּ בְּטָשׁוּתָא דְּהַהוּא נַעַל בְּיָדָא (ס\"א מידא) דְּאִתְּתָא לְאַרְעָא לְאַחֲזָאָה, דְּהָא יִתְבְּנֵי הַהוּא מִיתָא בְּעַפְרָא אַחֲרָא דְּהַאי עָלְמָא, וְהַשְׁתָּא יְתוּב לְעַפְרֵיהּ דְּהֲוָה מִתַּמָּן בְּקַדְמִיתָא, (אכדין יתוב לעפריה) וּכְדֵין הַהִיא אִתְּתָא תִּשְׁתְּרֵי לְמֶעְבַּד זַרְעָא אַחֲרָא, וְאוּקְמוּהָ.","תָּא חֲזֵי, עַל דָּא מַאן דְּבָעֵי לְקַיְּימָא קְיָּים, נָטִיל נַעֲלֵיהּ, וְיָהַב לְחַבְרֵיהּ, לְקַיְּימָא עָלֵיהּ קַיָּימָא. (דבת נדיב) הֲדָא הוּא דִכְתִיב, וְזֹאת לְפָנִים בְּיִשְׂרָאֵל עַל הַגְּאוּלָה. מַאי וְזֹאת. קַיָּימָא שְׁלִים בְּכֹלָּא. לְפָנִים בְּיִשְׂרָאֵל, כַּד הֲווֹ צְנוּעִין קַדִּישִׁין. לְקַיֵּים כָּל דָּבָר, כָּל דָּבָר מַמָּשׁ, דְּהָא דָּא הוּא קִיּוּמָא. וּכְדֵין וְזֹאת הַתְּעוּדָה בְּיִשְׂרָאֵל, ודַּאי. דְּלָא תֵּימָא דְּהַסְכָּמָה בְּעָלְמָא הִיא, וּמִדַּעֲתַּיְיהוּ עַבְדֵּי לָהּ, אֶלָּא קִיוּמָא עִלָּאָה הֲוָה, לְמֶהֱוֵי עוֹבָדֵיהוֹן בְּרָזָא דִּלְעֵילָּא.","כֵּיוָן דְּאַסְגִּיאוּ חַיָּיבִין בְּעָלְמָא, כָּסִּיאוּ מִלָּה בְּגַוְונָא אַחֲרָא, בְּכַנְפָא דְּמַלְבּוּשָׁא, וְהַאי מַלְבּוּשָׁא הִיא תִּקּוּנָא עִלָּאָה, וְרָזָא דְּמִלָּה, (דברים כ״ג:א׳) וְלֹא יְגַלֶּה כָּנָף אָבִיו כְּתִיב."],[[0,"ר' שמעון ור' אבא וכו':","ר\"ש ור\"א ור' אלעזר ור' יצחק, היו נמצאים בבית ר' פנחס בן יאיר. א\"ר פנחס לר' שמעון בבקשה ממך, אתה שהקימו אותך מלמעלה, ודבריך בגלוי, מה שלא ניתנה רשות לאדם אחר, אמור דבר חדש בפרשה זו. אמר לו, ואיזו היא. א\"ל, זאת חקת התורה. אמר לו, הרי שאר החברים יאמרו. אמר לר\"א בנו, אלעזר, קום על מעמדך, ואמור דבר אחד בפרשה זו, והחברים יאמרו אחריך."],[1,"קם ר' אלעזר וכו':","קם ר\"א ואמר, וזאת לפנים בישראל על הגאולה ועל התמורה לקיים וגו' מקרא זה יש להסתכל בו, אם הראשונים עשו הסכמה זו, לקנות כל דבר ע\"י נעל, בדין התורה, ובאו האחרונים ובטלו אותו, יש לשאול, למה בטלוהו, והרי מי שמבטל דבר של התורה כאלו מחריב עולם שלם. ואם זה לא היה בדין של תורה, אלא הסכמה בלבד, יש לשאול, למה דוקא נעל כאן, ולא דבר אחר."],[2,"אלא ודאי בדינא וכו':","ומשיב, אלא ודאי בדין התורה היה, ובסוד עליון נעשה הדבר, ומשום שהראשונים היו חסידים צדיקים, היה דבר זה מגולה ביניהם, וכשנתרבו הרשעים בעולם נעשה דבר זה באופן אחר, כדי לכסות הדברים שהם בסוד עליון."],[3,"ת\"ח ויאמר אל וכו':","בוא וראה, כתוב, ויאמר אל תקרב הלום של נעליך מעל רגליך וגו' שואל, וכי למה כאן נעל. ומשיב, אלא למדנו שצוהו, לפרוש מן אשתו, ולהתחבר באשה אחרת של אור הקדוש העליון, שהיא השכינה."],[4,"וההוא נעל אוקים וכו':","ונעל ההוא, מעמיד אותו במקום אחר, שמי שלוקח אותו, מעביר את הנותן אותו, מעולם זה, ומעמידו בעולם אחר. וע\"כ כל מה שנותן המת בחלום לאדם, הוא טוב, אבל אם לקח כלי מן הבית הוא רע, כגון שלקח הנעל שלו. מהו הטעם. משום, שזה יורה, שהעביר רגלו שהוא קיום האדם, מעולם הזה, ואסף אותו לעולם אחר, אל המקום שהמת שורה בו. כי הנעל רומז על רגלו, שהוא קיומו, שכתוב, מה יפו פעמיך בנעלים בת נדיב. וסוד הדבר בין החברים."],[5,"ודא כד מיתא וכו':","וזה הוא, כשהמת לוקח אותו, יורה שמעבירו למקום המות, אבל בזמן שהחי שולף נעלו ונותן לאדם אחר, כדי לקיים קנין, הוא עושה בגזירה של מעלה, דהיינו שנגזר שהקנין יעבור מרשותו של זה, לרשותו של זה. נעל של חליצה, היא נעל אחר כעין של מעלה, דהיינו כמו שמפרש לפנינו, והכל סוד אחד."],[6,"ת\"ח ההוא מיתא וכו':","בוא וראה, כשהמת הזה נסתלק מעולם בלי בנים, בת נדיב הזה, שהיא המלכות, אינה אוספת אותו האדם אליה, והולך נע ונד בעולם שאינו מוצא מקום, והקב\"ה מרחם עליו וצוה לאחיו, שיגאל אותו, שישיב ויתתקן בעפר אחר, דהיינו שיתגלגל כמ\"ש ואדם על עפר ישוב. והעמידוהו."],[7,"ואי ההוא פרוקא וכו':","ואם גואל הזה אינו רוצה להחיות את אחיו בעולם הזה, דהיינו ליבם את אשתו כדי שיחזור ויתגלגל בבן הנולד צריכים לקשור לו נעל אחד ברגלו, ואשה ההיא תחלוץ אותו ותקבל אותו הנעל אצלה. ולמה נעל. אלא משום, שנעל ההוא הוא בשביל המת, כלומר שנחשב שהוא של המת, ונותן ברגל אחיו החי, והאשה היבמה, מקבלת אצלה נעל ההוא, להראות שמת ההוא חוזר בין החיים ע\"י מעשה זה. פי' שהנעל רומז על היבמה, דהיינו בחינת היבום הקשורה ברגל אחיו החי, כדי להביא אחיו המת בין החיים, דהיינו שיתגלגל בבן הנולד."],[8,"והוא בהפוכא מההוא וכו':","והוא בהיפך מאותו הנעל שהמת נוטל מן החיים בחלום, שאמרנו לעיל שע\"י לקיחת הנעל מעביר את החי מעולם הזה לעולם האחר של המת (כנ\"ל באות ח') ועתה נעל הזה של חליצה, לוקח החי מן המת, וע\"כ בנעל ההוא הולך המת בין החיים, משום שהאשה החיה היתה מעבירה את המת מעולם האחר אל עולם הזה בין החיים, שהיה מתגלגל בבן הנולד מן היבום, ועתה שאינו רוצה ליבם, והאשה לוקחת אותו אצלה, להראות שהאשה עטרת בעלה ההיא, שהיא השכינה, לוקחת אותו ומקבלת אותו אצלה."],[9,"ובעי לבטשא ליה וכו':","וצריכים להשליך נעל ההוא על הארץ, להראות שנשקט הגוף של אותו המת, והקב\"ה בשעה זו, או לאחר זמן, ירחם עליו ויקבלו לעולם האחר. עוד, הכאת הנעל מיד האשה לארץ, בא להראות, שאותו המת יבנה מעפר אחר של עולם הזה, דהיינו שיתגלגל, ועתה ישוב תחילה לעפר שהיה משם, ואז, אשה ההיא מותרת לעשות זרע אחד. והעמידוהו."],[10,"ת\"ח ע\"ד מאן וכו':","בוא וראה, ע\"כ מי שרוצה לקיים קנין, לוקח נעלו ונותן לחברו, לקיים עליו הקנין. ז\"ש, וזאת לפנים בישראל על הגאולה. מהו \u0003וזאת\u0004 היינו, \u0003וזאת,\u0004 שהיא המלכות, עמדה שלמה בכל. \u0003לפנים בישראל,\u0004 כשהיו צנועים וקדושים. \u0003לקיים כל דבר,\u0004 היינו כל דבר ממש, שרומז על זווג העליון יסוד ומלכות, כי \u0003כל\u0004 הוא יסוד, \u0003דבר\u0004 הוא מלכות. כי זה הוא קיום. וזאת התעודה בישראל, ודאי. שאל תאמר שהיא הסכמה בעלמא, לעשות קנין עם נעל, ומדעתם עשו זה, אלא הוא קיום עליון, שיהיו מעשיהם למטה כעין הסוד של מעלה. כי רומז על זווג יסוד ומלכות כנ\"ל. שה\"ס קיום העליון."],[11,"כיון דאסגיאו חייבין וכו':","כיון שנתרבו הרשעים בעולם, כסו הדבר באפן אחר, דהיינו שעושים קנין, בכנף המלבוש, ומלבוש ההוא, הוא תקון עליון, שהוא ז\"א, וכנף המלבוש הוא המלכות שנקרא כנף. שרומז ג\"כ על זווג ז\"א ומלכות, כמו הנעל. וסוד הדבר, ולא יגלה כנף אביו כתוב, הרי שהאשה נקראת כנף."]],[[0,"","רַבִּי שִׁמְעוֹן וְרַבִּי אַבָּא וְרַבִּי אֶלְעָזָר וְרַבִּי יִצְחָק הָיוּ מְצוּיִים בְּבֵית רַבִּי פִּנְחָס בֶּן יָאִיר. אָמַר רַבִּי פִּנְחָס לְרַבִּי שִׁמְעוֹן, בְּבַקָּשָׁה מִמְּךְ, אַתָּה שֶׁעוֹמְדִים עָלֶיךְ לְמַעְלָה וּדְבָרֶיךְ בְּגָלוּי, מַה שֶּׁלֹּא נִתְּנָה רְשׁוּת לְאָדָם אַחֵר, בְּפָרָשָׁה זוֹ אֱמֹר דָּבָר חָדָשׁ. אָמַר לוֹ, וּמַהוּ? אָמַר לוֹ, זֹּאת חֻקַּת הַתּוֹרָה. אָמַר לוֹ, הִנֵּה שְׁאָר הַחֲבֵרִים יֹאמְרוּ. אָמַר לְרַבִּי אֶלְעָזָר בְּנוֹ, אֶלְעָזָר עֲמֹד בְּעָמְדְּךְ, וֶאֱמֹר דָּבָר אֶחָד בְּפָרָשָׁה זוֹ, וְהַחֲבֵרִים יֹאמְרוּ אַחֲ רֶיךְ."],[1,"","קָם רַבִּי אֶלְעָזָר וְאָמַר, (רות ד) וְזֹּאת לְפָנִים בְּיִשְׂרָאֵל עַל הַגְּאוּלָּה וְעַל הַתְּמוּרָה לְקַיֵּם וְגוֹ'. בְּפָסוּק זֶה יֵשׁ לְהִסְתַּכֵּל, וְאִם רִאשׁוֹנִים אֵלּוּ עָשׂוּ הַסְכָּמָה זוֹ בְּדִין תּוֹרָה וּבָאוּ אַחֲרוֹנִים וּבִטְּלוּהָ, לָמָּה בִּטְּלוּהָ? וַהֲרֵי מִי שֶׁמְּבַטֵּל דְּבַר תּוֹרָה כְּאִלּוּ הֶחֱרִיב עוֹלָם שָׁלֵם? וְאִם זֶה אֵינוֹ בְּדִין תּוֹרָה, אֶלָּא הַסְכָּמָה בְּעָלְמָא, לָמָּה הַנַּעַל כָּאן?"],[2,"","אֶלָּא וַדַּאי בְּדִין הַתּוֹרָה הָיָה, וּבְסוֹד עֶלְיוֹן נַעֲשָׂה הַדָּבָר. וּמִשּׁוּם שֶׁהָיוּ הָרִאשׁוֹנִים חֲסִידִים צַדִּיקִים, הַדָּבָר הַזֶּה הִתְגַּלָּה בֵינֵיהֶם, וּמִשֶּׁהִתְרַבּוּ רְשָׁעִים בָּעוֹלָם, נַעֲשָׂה (העבירו) דָבָר זֶה בְּצוּרָה אַחֶרֶת כְּדֵי לְכַסּוֹת דְּבָרִים שֶׁהֵם בְּסוֹד עֶלְיוֹן. (והרי פרשוה)"],[3,"","בֹּא וּרְאֵה, (שמות ג) וַיֹּאמֶר אַל תִּקְרַב הֲלֹם שַׁל נְעָלֶיךְ מֵעַל רַגְלֶיךְ וְגוֹ'. וְכִי לָמָּה הַנַּעַל כָּאן? אֶלָּא נִתְבָּאֵר שֶׁצִּוָּה לוֹ עַל הָאִשָּׁה לְהִפָּרֵד מִמֶּנָּה, וּלְהִזְדַּוֵּג (במקום) בְּאִשָּׁה אַחֶרֶת שֶׁל אוֹר קָדוֹשׁ עֶלְיוֹן, וְהִיא הַשְּׁכִינָה."],[4,"","וְאוֹתָהּ נַעַל בֵּאֲרוּהָ בְּמָקוֹם אַחֵר, (והיאהשכינה) הֶעֱבִירוּהָ מֵעוֹלָם הַזֶּה, וּבֵאֲרוּהָ בְּעוֹלָם אַחֵר. וְעַל כָּךְ, כָּל מַה שֶּׁנּוֹתֵן הַמֵּת לָאָדָם בַּחֲלוֹם - זֶה טוֹב. לָקַח כֵּלָיו מֵהַבַּיִת - זֶה רָע, כְּמוֹ סַנְדָּלוֹ. מַדּוּעַ? כִּי הֶעֱבִיר רַגְלָיו, שֶׁהֵם עֲמִידַת הָאָדָם, מֵהָעוֹלָם הַזֶּה, וְכָנַס אוֹתָם לְעוֹלָם אַחֵר, מָקוֹם שֶׁהַמָּוֶת שׁוֹרֶה בּוֹ, שֶׁכָּתוּב (שיר ז) מַה יָּפוּ פְעָמַיִךְ בַּנְּעָלִים בַּת נָדִיב. (מהי בת נדיב, ' זו בת אברהם, שכתוב (תהלים מז) נדיבי עמים נאספו עם אלהי אברהם, ולא אלהי יצחק) וְסוֹד הַדָּבָר הוּא בֵּין הַחֲבֵרִים."],[5,"","וְזְהִ כְּשֶׁהַמֵּת לוֹקֵחַ אוֹתָם. אֲבָל בִּזְמַן שֶׁהַחַי שׁוֹלֵף נַעֲלוֹ וְנוֹתֵן לְאִישׁ אַחֵר כְּדֵי לְקַיֵּם בְּרִית, עוֹשֶׂה בִּגְזֵרָה עֶלְיוֹנָה. נַעַל שֶׁל חֲלִיצָה, כְּמוֹ שֶׁלְּמַעְלָה נַעַל אַחֶרֶת, וְהַכֹּל מָקוֹם אֶחָד (הכל מתיחד) (סוד אחד)."],[6,"","בֹּא וּרְאֵה, אוֹתוֹ מֵת שֶׁהִסְתַּלֵּק מֵהָעוֹלָם בְּלֹא בָנִים, בַּת נָדִיב זוֹ לֹא כוֹנֶסֶת אוֹתוֹ אֵלֶיהָ, וְהוֹלֵךְ לִהְיוֹת מֻטְרָד בָּעוֹלָם, שֶׁלֹּא מוֹצֵא מָקוֹם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עָלָיו, וּמְצַוֶּה לְאָחִיו לִגְאֹל אוֹתוֹ, לָשׁוּב וְלִהְיוֹת מְתֻקָּן בְּעָפָר אַחֵר, כְּמוֹ שֶׁכָּתוּב (איובלד) וְאָדָם עַל עָפָר יָשׁוּב, וּפֵרְשׁוּהָ."],[7,"","וְאִם אוֹתוֹ גּוֹאֵל לֹא רוֹצֶה לְהַעֲמִיד אֶת אָחִיו בָּעוֹלָם הַזֶּה, צָרִיךְ לִקְשֹׁר נַעַל אַחַת בְּרַגְלוֹ, וְאוֹתָהּ אִשָּׁה שֶׁתִּשְׁרֶה אִתּוֹ, מְקַבֶּלֶת אֵלֶיהָ אוֹתָהּ נַעַל. וְלָמָּה נַעַל? אֶלָּא מִשּׁוּם שֶׁאוֹתָהּ נַעַל הִיא בִּגְלַל הַמֵּת (משום שאותה נעל היא קיום המת בעולם הזה), וְנִתְּנָה בְּרַגְלֵי אָחִיו הַחַי, וְהָאִשָּׁה מְקַבֶּלֶת אֵלֶיהָ אוֹתָהּ נַעַל, לְהַרְאוֹת שֶׁאוֹתוֹ מֵת חָזַר לְבֵין הַחַיִּים בַּמַּעֲשֶׂה הַזֶּה."],[8,"","וְהוּא בְּהֵפֶךְ מֵאוֹתָהּ נַעַל שֶׁלּוֹקֵחַ הַמֵּת מֵהַחַי, וְכָעֵת נַעַל זוֹ לוֹקֵחַ הַחַי מִן הַמֵּת, וּבְאוֹתָהּ נַעַל אוֹתוֹ הַמֵּת הוֹלֵךְ בֵּין הַחַיִּים, (וצריך נעל של המת הזה הולך בו בחייו) וְהָאִשָּׁה לוֹקַחַת אוֹתָהּ אֵלֶיהָ, לְהַרְאוֹת שֶׁאוֹתָהּ אִשָּׁה (משלי יב) עֲטֶרֶת בַּעְלָהּ, לָקְחָה אוֹתָהּ וּמְקַבֶּלֶת אוֹתָהּ אֵלֶיהָ."],[9,"","וְצָרִיךָ לְהַכּוֹת בְּאוֹתָהּ נַעַל בָּאָרֶץ, לְהַרְאוֹת שֶׁשָּׁכַךְ גּוּף אוֹתוֹ הַמֵּת. וְהַקָּדוֹשׁ בָּרוּךְ הוּא בִּזְמַן זֶה אוֹ לְאַחַר זְמַן יָחוּס עָלָיו וִיקַבֵּל אוֹתוֹ לְעוֹלָם אַחֵר. עוֹד הַכָּאָה שֶׁל אוֹתָהּ הַנַּעַל בַּיָּד (מהיד) שֶׁל הָאִשָּׁה לָאָרֶץ, לְהַרְאוֹת שֶׁיִּבָּנֶה אוֹתוֹ הַמֵּת בְּעָפָר אַחֵר בָּעוֹלָם הַזֶּה, וְכָעֵת יָשׁוּב לַעֲפָרוֹ שֶׁהָיָה מִשָּׁם בַּהַתְחָלָה, (ואז ישוב לעפרו) וְאָז אוֹתָהּ אִשָּׁה תֻּתַּר לַעֲשׂוֹת זֶרַע אַחֵר, וְכָךְ פֵּרְשׁוּהָ."],[10,"","בֹּא וּרְאֵה, עַל כָּךְ מִי שֶׁרוֹצֶה לְהַעֲמִיד בְּרִית, נוֹטֵל נַעֲלוֹ וְנוֹתֵן לַחֲבֵרוֹ לְהַעֲמִיד עָלָיו בְּרִית. (שבת נָדיב) זהו שכתוב וזאת לפנים בישראל על הגאולה. מה זה וְזֹּאת? בְּרִית שְׁלֵמָה בַּכֹּל. לְפָנִים בְּיִשְׂרָאֵל, כְּשֶׁהָיוּ צְנוּעִים קְדוֹשִׁים. לְקַיֵּם כָּל דָּבָר, כָּל דָּבָר מַמָּשׁ, שֶׁהֲרֵי זֶהוּ הַעֲמָדָה. וְאָז - וְזֹּאת הַתְּעוּדָה בְּיִשְׂרָאֵל, וַדַּאי. שֶׁלֹּא תֹאמַר שֶׁהַסְכָּמָה בְּעָלְמָא הִיא, וּמִדַּעְתָּם עָשׂוּ אוֹתָהּ, אֶלָּא הַעֲמָדָה עֶלְיוֹנָה הָיְתָה, לִהְיוֹת מַעֲשֵׂיהֶם בְּסוֹד שֶׁל מַעְלָה."],[11,"","כֵּיוָן שֶׁהִתְרַבּוּ רְשָׁעִים בָּעוֹלָם, כִּסּוּ הַדָּבָר בְּגָוֶן אַחֵר, בִּכְנַף הַמַּלְבּוּשׁ, וְהַמַּלְבּוּשׁ הַזֶּה הוּא תִּקּוּן עֶלְיוֹן. וְסוֹד הַדָּבָר - כָּתוּב (דברים כג) וְלֹא יְגַלֶּה כְּנַף אָבִיו."]]],[["(במדבר י״ט:ב׳) זֹאת חֻקַּת הַתּוֹרָה. זֹאת: דָּא אָת קַיָּימָא, דְּלָא אִתְפְּרַשׁ דָּא מִן דָּא (וכד אתפרע דא כלא) דְּאִקְרֵי זֶה. וּמִנוּקְבָא עָיֵיל לִדְכַר. וְעַל דָּא, שָׁמוֹ\"ר וְזָכוֹ\"ר כַּחֲדָא מִתְחַבְּרָן. חֻקַּת הַתּוֹרָה, חֹק הַתּוֹרָה מִבָּעֵי לֵיהּ, מַאי חֻקַּת.","אֶלָּא חֻקַּת וַדַּאי, (נ\"ח, ס\"א) וְאוֹקִימְנָא, ה' ד' הֲוַת (נ\"א חק) וְהָא אִתְּמַר. אֲבָל תּ', הוּא ד' וְנ' מְחֻבָּר כַּחֲדָא. וְנוּ\"ן הָא אִתְּמַר, נוּ\"ן אֲמַאי אִקְרֵי הָכִי בְּנוּ\"ן. אֶלָּא, כְּמָה דְאַתְּ אָמֵר (ויקרא כ״ה:י״ז) וְלֹא תוֹנוּ אִישׁ אֶת עֲמִיתוֹ. דְּהַשְׁתָא הִיא בְּאַנְפָּהָא נְהִירִין וְעַבְדָא אוֹנָאָה לִבְנֵי נָשָׁא, לְבָתַר מַחְיָא כְּחִוְיָא, וְשָׁצֵי וְקָטִיל (משלי ל׳:כ׳) וְאָמְרָה לֹא פָעַלְתִּי אָוְן. וְעַל דָּא הָכִי אִקְרֵי בְּנוּ\"ן, דְּאִתְּמַר עָלֵיהּ. ת' כֹּלָּא כַּחֲדָא דָּלֶ\"ת נוּ\"ן. ד' נוּ\"ן דָּלֶ\"ת רֵי\"שׁ (ה\"א ה\"א) (נו\"ן רי\"ש), רֵי\"שׁ וְדָלֶ\"ת חַד מִלָּה הוּא. וּבְאַתְוָו\"ן גְּלִיפִין אִינּוּן תָּא חֲזֵי חֹק וֹת (ס\"א אינון חק ות') וְכֹלָּא חַד מִלָּה.","דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְיִקְחוּ אֵלֶיךָ פָרָה, הַאי פָּרָה לְדַכְיוּתָא קָא אַתְיָיא. לְדַכְּאָה לְמִסְאֲבֵי. פָּרָה דְּקַבִּילַת מִן שְׂמָאלָא. וּמַאן הוּא לִשְׂמָאלָא. שׁוֹר. כְּמָה דְאַתְּ אָמֵר, (יחזקאל א׳:י׳) וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל. אֲדוּמָה, סוּמָקָא כְּוַורְדָּא. דִּכְתִּיב, (שיר השירים ב׳:ב׳) כְּשׁוֹשַׁנָּה בֵּין הַחוֹחִים. אֲדוּמָּה: גִּזְרַת דִּינָא.","תְּמִימָה, מַאי תְּמִימָה. כְּמָה דְּתָנֵינָן, שׁוֹר תָּם וְשׁוֹר מוּעָד. (קס\"ג ע\"ב) שׁוֹר תָּם דִּינָא רַפְיָיא. שׁוֹר מוּעָד דִּינָא קַשְׁיָא. אוּף הָכָא תְּמִימָה דִּינָא רַפְיָיא, גְּבוּרָה תַּתָּאָה, דָּא הִיא תְּמִימָה. גְּבוּרָה עִלָּאָה, דָּא הִיא דִּינָא קַשְׁיָא, וְהִיא יַד הַחֲזָקָה תַּקִּיפָא.","אֲשֶׁר אֵין בָּהּ מוּם, כְּמָה דְאַתְּ אָמֵר (שיר השירים ד׳:ז׳) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ. אֲשֶׁר לֹא עָלָה עָלֶיהָ עוֹל. עַל כְּתִיב, כְּמָה דְאַתְּ אָמֵר (שמואל ב כ״ג:א׳) וּנְאֻם הַגֶּבֶר הוּקַם עָל. מַאי טַעְמָא. בְּגִין דְּהִיא שְׁלוּמֵי אֱמוּנֵי יִשְׂרָאֵל, וְעָלֶיהָ לָאו הִיא אֶלָּא עִמָּהּ. אֲשֶׁר לֹא עָלָה עָלֶיהָ עֹל, הַיְינוּ דִּכְתִּיב, (עמוס ה) בְּתוּלַת יִשְׂרָאֵל, (בראשית כ״ד:ט״ז) בְּתוּלָה וְאִישׁ לֹא יְדָעָה.","וּנְתַתֶּם אוֹתָהּ אֶל אֶלְעָזָר, מִצְוָותָהּ בַּסְּגַן, וְאוֹקְמוּהָ. מַאי טַעְמָא לֵיהּ וְלָא לְאַהֲרֹן. אֶלָּא אַהֲרֹן שׁוּשְׁבִינָא דְּמַטְרוֹנִיתָא. וְעוֹד דְּאַהֲרֹן לָא אָתֵי מִסִּטְרָא דְּטָהוֹר, אֶלָּא (קע\"ז ע\"ב) מִסִּטְרָא דְּקָדוֹשׁ, וּבְגִין דְּדָא אַתְיָיא לְטָהֳרָה, לָא אִתְיְיהִיב לֵיהּ.","כָּל מִלָּה דְּהַאי פָּרָה, הִיא בְּשֶׁבַע, ז' כִּבּוּסִים וְכוּ', וְהָא (ע\"ז ע\"ב) אִתְּמַר, מַאי טַעְמָא. בְּגִין דְּהִיא שֶׁבַע שְׁנֵי שְׁמִטָּה, וּבַת שֶׁבַע אִתְקְרֵי, וְעַל דָּא כָּל עוֹבָדוֹי בְּשֶׁבַע. תָּא חֲזֵי, כָּל מַאי דְּאִתְעָבִיד מֵהַאי פָּרָה, בְּגִין לְדַכְּאָה, וְלָא לְקַדְּשָׁא, וְאַף עַל גַּב דְּאִתְיְיהִיב לַסְּגָן, הוּא לָא שָׁחִיט וְלָא שָׂרִיף, בְּגִין דְּלָא יִשְׁתְּכַּח דִּינָא בְּסִטְרוֹי, וְכָּל שֶׁכֵּן אַהֲרֹן דְּאִיהוּ בְּדַרְגָּא שְׁלִים יַתִּיר, דְּלָא בָּעֵי לְאִשְׁתַּכְּחָא תַּמָּן, וּלְאִזְדַּמְּנָא תַּמָּן.","הַאי פָּרָה, כֵּיוָן דְּאִתְעָבִיד אֵפֶר, בָּעֵי לְמִשְׁדֵּי בֵּיהּ עֵץ אֶרֶז, וְאֵזוֹב, וּשְׁנִי תּוֹלַעַת, וְהָא אִלֵּין אִתְּמָרוּ. וְאָסַף אִישׁ טָהוֹר, וְלָא קָדוֹשׁ. וְהִנִּיחַ מִחוּץ לַמַּחֲנֶה בְּמָקוֹם טָהוֹר, דְּהָא טָהוֹר לָא אִקְרֵי, אֶלָּא מִן סִטְרָא דִּמְסָאֵב בְּקַדְמִיתָא.","רָזָא דְּכֹלָּא, הַאי דִּכְתִּיב לְמֵי נִדָּה חַטָּאת הִיא, בְּגִין דְּכָל דִּינִין תַּתָּאִין, וְכָל אִינּוּן דְּאָתוּ מִסִּטְרָא דִּמְסָאֲבָא, כַּד אִיהוּ יַנְקָא מִסִּטְרָא אַחֲרָא, וְיָתִיבַת בְּדִינָא, כְּמָה דְאַתְּ אָמֵר (ישעיהו ל״ד:ו׳) מָלְאָה דָם הוּדַּשְׁנָה מֵחֶלֶב. כְּדֵין כֻּלְּהוּ מִתְעָרֵי וּמִסְתַּלְקֵי וְשָׁרָאן בְּעָלְמָא. כֵּיוָן דְּעַבְדֵי הַאי עוֹבָדָא דִּלְתַּתָּא, וְכָל הַאי דִּינָא בַּאֲתַר דָּא דְּהַאי פָּרָה, וְרָמָאן עָלָהּ עֵץ (דף קפ\"א ע\"א) אֶרֶז וְגוֹ'. כְּדֵין אִתְחֲלָשׁ חֵילָא דִּלְהוֹן, וּבְכָל אֲתָר דְּשָׁרָאן אִתְּבָּרוּ וְאִתְחֲלָשׁוּ וְעַרְקִין מִנֵּיהּ, דְּהַאי חֵילָא דִּלְהוֹן אִתְחֲזֵי כְּגַוְונָא דָּא לְגַבַּיְיהוּ, כְּדֵין לָא שָׁרָאן בְּבַר נָשׁ, וְאִתְדַכֵּי.","וְעַל דָּא אִתְקְרֵי מֵי נִדָּה, מַיָּיא לְדַכְּאָה. כַּד עָלְמָא שָׁארֵי בְּדִינָא, וְסִטְרָא מִסְאֲבָא אִתְפְּשָׁט בְּעָלְמָא, הָכָא אִתְכְּלִילָן כָּל זִינִין מְסָאֲבָא, וְכָל זִינֵי דַּכְיוּ, וּבְגִין כַּךְ טוּמְאָה וְטָהֳרָה, כְּלָלָא עִלָּאָה דְּאוֹרַיְיתָא, וְאוֹקְמוּהָ חַבְרַיָּיא. אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר, עַבְדַּת דְּלָא יֵימְרוּן חַבְרַיָּיא מִלָּה אֲבַּתְרָךְ.","\u0003רעיא מהימנא\u0004 פָּרָה אֲדוּמָּה תְּמִימָה אֲשֶׁר אֵין בָּהּ מוּם וְגוֹ', אָסוּר לַחֲרוֹשׁ בְּשַׁבָּת חֲרִישָׁה דְּשׁוֹר, דְּאִתְּמַר (תהילים קכ״ט:ג׳) עַל גַּבִּי חָרְשׁוּ חוֹרְשִׁים. וּשְׁכִינְתָּא תַּתָּאָה, אִיהִי פָּרָה אֲדוּמָּה, מִסִּטְרָא דִּגְבוּרָה. תְּמִימָה מִסִּטְרָא דְּחֶסֶד, דְּאִיהוּ דַּרְגָּא דְּאַבְרָהָם, דְּאִתְּמַר בֵּיהּ (בראשית י״ז:א׳) הִתְהַלֵּךְ לְפָנַי וְהְיֵה תָּמִים. אֲשֶׁר אֵין בָּהּ מוּם, מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָּעִיתָא. אֲשֶׁר לֹא עָלָה עָלֶיהָ עוֹל, מִסִּטְרָא דִּשְׁכִינְתָּא עִלָּאָה, דְּאִיהִי חֵירוּ. בַּאֲתָר דְּאִיהִי שַׁלְטָא, וְהַזָּר הַקָּרֵב לֵית רְשׁוּ לְסִטְרָא אַחֲרָא לְשַׁלְּטָאָה. לָא שָׂטָן, וְלָא מַשְׁחִית, וְלָא מַלְאָךְ הַמָּוְת, דְּאִינּוּן מִסִּטְרָא דְּגֵיהִנָם. (ע\"כ רעיא מהימנא)."],[[0,"זאת חקת התורה:","זאת, זה אות ברית, כי אות הברית שנקרא \u0003זה,\u0004 לא נפרדו זה מזה. כלומר, שבמלה \u0003זאת\u0004 שהיא מלכות, נכלל המלה \u0003זה,\u0004 הרומז על היסוד, שזה יורה שיסוד ומלכות אינם נפרדים זה מזה. ומן הנוקבא באים לדכר. וע\"כ שמור וזכור שה\"ס דכר ונוקבא, מחוברים יחד. שואל, חקת התורה, חק התורה היה צריך לומר. מהו חקת."],[1,"אלא חקת ודאי וכו':","ומשיב, אלא המלכות היא חקת בודאי, והעמדנו \u0003ה', ד'\u0004 היתה, וכבר למדנו, פירושו של \u0003ד'\u0004, אבל \u0003ת'\u0004 היא \u0003ד'\u0004 ו \u0003נ'\u0004 מתחברים יחד. ו \u0003נ'\u0004 הרי למדנו, \u0003נ'\u0004 למה נקראת כך \u0003נון.\u0004 דהיינו ב \u0003נ' ו' נ'\u0004. ומשיב, אלא, כמש\"א, ולא תונו איש את עמיתו. כי נון, הוא מלשון אונאה. כי עתה היא בפנים מאירות, אבל, ועושית אונאה לבני אדם, כי אח\"כ היא מכה כמו נחש ומכלה והורג. ואמרה לא פעלתי און. וע\"כ נקראת כך ב \u0003נ' ו' ן',\u0004 שהיא לשון אונאה הנאמר עליה על ה \u0003נ'.\u0004 ה \u0003ת',\u0004 הכל ביחד, היא \u0003ד' נ'.\u0004 ד' נ' דומה ל \u0003נ'\u0004 ו \u0003ר'\u0004, כי \u0003ריש ודלת\u0004 דבר אחד הוא, ששתיהן פירושן עניות. ובאותיות חקוקות, חקת הן אותיות \u0003חק ות'.\u0004 והכל דבר אחד."],[1,"","פירוש. כי שואל, כיון שזאת היא המלכות, היה די שיאמר זאת חק התורה ולמה האריך לומר חקת התורה עם \u0003ת'.\u0004 ומשיב שה \u0003ת'\u0004 היא נתינת טעם על מה שנקראת \u0003חק.\u0004 כי ציור אות \u0003ת'\u0004 הוא חיבור ב' אותיות \u0003ד'\u0004 ו \u0003נ',\u0004 אשר ה \u0003ד',\u0004 מורה על דינים דדכורא דהיינו הנמשכים מקו השמאל, להיותו חכמה בלי חסדים. וה \u0003נ',\u0004 מורה על דינין דנוקבא, דהיינו על הדינים דמסך שבה. וז\"ש \u0003חקת,\u0004 דהיינו \u0003חק\u0004 של \u0003ד' נ',\u0004 שנחקקה בב' מיני דינים אלו."],[1,"","וזה אמרו. \u0003ואוקימנא ה' ד' הות, והא אתמר,\u0004 כי סוד ה \u0003ד'\u0004 נתבאר בהמאמר אשר \u0003ה'\u0004 דשם הויה היתה מקודם \u0003ד'.\u0004 שפירושו שהיתה בבחינת שמאל בלי ימין, שאז היתה דלה ועניה, ועל שם זה היא נקראת \u0003דלת.\u0004 ואחר שביאר אות ד' מהו, אומר, \u0003אבל ת', הוא ד' ונ' מחבר כחדא,\u0004 שבצורת ת' יש ב' אותיות אלו ד' נ'. \u0003ונ' הא אתמר\u0004 וכו' \u0003מחיא כחויא ושצי וקטיל ואמרה לא פעלתי און,\u0004 שהיא דינים דנוקבא, שהס\"א נאחזת בהם. ובני העולם מתאנים שפני המלכות מאירים, ואינו כן, אלא מכה כנחש וכו'. \u0003ועל דא הכי אקרי בנון\u0004 שפירושו אונאה, \u0003דאתמר עליה.\u0004 וז\"ש, \u0003ת' כלא כחדא ד' נ',\u0004 שצורת ה \u0003ת'\u0004 ד' נ' יש בה ביחד, דהיינו ב' מיני דינים דדוכרא ודנוקבא. ואם תאמר שצורת \u0003ת'\u0004 היא \u0003ר נ',\u0004 לזה אומר, \u0003ד' נ' נון ריש,\u0004 ש \u0003ד' נ'\u0004 דומות ל \u0003נ' ר',\u0004 כי \u0003ריש ודלת חד מלה הוא\u0004 ששתיהן מורות על דלות ועניות שהוא דינים דדכורא, כי \u0003ריש\u0004 פירושו ג\"כ עניות, מלשון, ריש ועוני, וע\"כ אין נפקא מינה אם צורת ת' היא ד' נ' או ר' נ', ששתיהן משמעות אחד, ומורות על דינים דנוקבא ודינים דדכורא. וזה שאמר, \u0003ובאתוון גליפין אינון חק ות'\u0004 שאותיות \u0003חקת\u0004 הן אותיות \u0003חק\u0004 ו \u0003ת'.\u0004 שפירושו \u0003חק\u0004 של דינין דדכורא ודינין דנוקבא הכלולים ב \u0003ת'. וכלא חד מלה.\u0004 ש \u0003חק\u0004 ו \u0003ת'\u0004 הם מלה אחת, המורים על דיני המלכות."],[2,"דבר","וגו' \u0003ויקחו אליך פרה:\u0004 פרה זו באה לטהרה. לטהר הטמאים. שהיא מלכות המקבלת מן השמאל. ומי הוא לשמאל, הוא שור, דהיינו גבורה דז\"א, כש\"א, ופני שור מהשמאל. \u0003אדומה,\u0004 היינו אדומה כשושנה, שכתוב כשושנה בין החוחים. אדומה פירושו גזרת דין. כי הדינים דקו שמאל נקראים אדום."],[3,"תמימה, מאי תמימה וכו':","שואל, כתוב, תמימה, מהו תמימה. ומשיב, הוא כמו שלמדנו, שור תם שור מועד, (שלח אות קי\"ח) שור תם פירושו דין רפה, שור מועד, דין קשה. אף כאן \u0003תמימה,\u0004 פירושו, דין רפה, שהוא גבורה תחתונה, דהיינו מלכות, זו היא תמימה. גבורה עליונה, דהיינו גבורה דז\"א, זו היא יד החזקה והקשה."],[3,"","פירוש. צד השמאל נקרא שור, ונודע שהארת החכמה נמשכת משמאל, אמנם רק ממטה למעלה שהוא אור נקבה דהיינו המלכות, וזה נקרא שור תם, שהוא דין רפה, להיותו ממטה למעלה. אבל מבחינת אור זכר, המאיר ממעלה למטה, שהוא קו שמאל דז\"א דהיינו גבורה דז\"א, אסור להמשיך, וע\"כ הוא נקרא דין קשה. ונקרא שור מועד. כמ\"ש ענינם באורך לעיל (שלח אות קי\"ח ע\"ש)."],[4,"אשר אין בה מום:","הוא כש\"א, כלך יפה רעיתי ומום אין בך. כי להיותה מאירה בהארת החכמה, נקראת יפה. שכל המומים מתרפאים ע\"י הארת החכמה. אשר לא עלה עליה עול. \u0003על\u0004 כתוב, בלא \u0003ו'\u0004 הוא כש\"א, ונאם הגבר הוקם על. מהו הטעם. הוא, משום שהיא שלומי אמוני ישראל. והוא אינו עליה אלא עמה. אשר לא עלה עליה על, היינו שכתוב, בתולת ישראל. בתולה ואיש לא ידעה."],[4,"","פירוש. כבר ידעת שיש ב' מצבים במלכות. א) כמו שהיתה ביום ד' דמעשה בראשית בסו\"ה ב' מאורות הגדולים, שהיו ז\"א ומלכות מלבישים ב' קוי הבינה, ז\"א הלביש קו הימין דבינה, והמלכות קו שמאל דבינה. ואז היתה המלכות גדולה כמו ז\"א, כי לא היתה מקבלת מז\"א אלא מבינה. מאותו מקום שז\"א היה מקבל. ומצד ב' לאחר מיעוט הירח, שאז נתמעטה והיתה למטה מז\"א, ומקבלת ממנו (כמ\"ש בארך לעיל ב\"א מאות ק\"י עד אות קט\"ו ע\"ש) ויש מעלה במצב הא' יותר ממצב הב', כי במצב א' היא בשלמות המדרגה כמו ז\"א, אמנם יש חסרון גדול, כי אז היא בבחינת חכמה בלי חסדים, ואין החכמה שבה יכולה להאיר מבלי חסדים, והיא חשך וע\"כ קטרגה וכו' (כמ\"ש שם) ויש מעלה במצב הב', שאז יש לה חסד מז\"א שהארת חכמה שבה מתלבשה בו ומאירה בשפע. אמנם יש חסרון מה שנתמעטה ונעשית מדרגה תחתונה לז\"א, ואין לה מעצמה כלום אלא מה שמקבלת מז\"א."],[4,"","והנה, פרה אדומה ה\"ס המלכות מבחינת מצב הא', וז\"ש, \u0003אשר אין בה מום, כד\"א כלך יפה רעיתי ומום אין בך,\u0004 כי אז במצב הא' שהיא מלבישה את קו השמאל דבינה, ומקבלת ממנה חכמה, אע\"פ שהחכמה אינה יכולה להאיר בה, מ\"מ מבחינת עצמה היא בתכלית השלמות ואין בה מום, וכולה יפה, מהארת החכמה שיונקת מקו שמאל דבינה."],[4,"","וז\"ש, \u0003אשר לא עלה עליה עול, על כתיב, כד\"א ונאם הגבר הוקם על,\u0004 כי הוקם על פירושו \u0003חסד,\u0004 הנקרא \u0003על,\u0004 כמ\"ש בתקוני זהר (תקון ל\"ט דף ע\"ט ע\"א), \u0003וצונו על, מסטרא דימינא, דאתמר ביה, הוקם על, דתמן כל ברכאן לימינא,\u0004 ע\"ש. כי במצב הא', עוד לא קבלה המלכות עליה אור החסד מז\"א, הנקרא על, אלא שהיתה אז בחכמה בלא חסד כנ\"ל. וז\"ש \u0003מ\"ט, בגין דהיא שלומי אמוני ישראל,\u0004 כלומר, מפני שהיא נמצאת במצב הא', שהמלכות שנקרא אמונה, וז\"א שנקרא ישראל, הם בשלמות אחד, שזה יורה השם, \u0003שלומי, אמוני ישראל.\u0004 כי במצב הא' המלכות גדולה ושלמה כמו ז\"א. וע\"כ אינה צריכה להזדווג עם ז\"א, אלא מקבלת מבינה, וז\"ס, אשר לא עלה עליה על, שהוא ז\"א. וז\"ש, \u0003ועליה לאו הוא, אלא עמה,\u0004 כי ז\"א אינו אז למעלה מן המלכות אלא במדרגה שוה \u0003עם\u0004 המלכות. וז\"ש \u0003אשר לא עלה עליה עול, היינו דכתיב, בתולת ישראל\u0004 וכן \u0003בתולה ואיש לא ידעה.\u0004 כי במצב הא' המלכות ה\"ס \u0003בתולה\u0004 שאינה מזדווגת עם ז\"א, אלא מקבלת שפעה מן הבינה. וע\"כ המלכות היא בתולה, כי לא עלה עליה עול, שהוא ז\"א. וסוד שריפת הפרה עד לאפר, ה\"ס שמצב הא' אינו יכול להתקיים, והיא מתמעטת עד לנקודה, וחוזרת ונבנית למצב הב', שבמצב הזה כל קיומה."],[5,"ונתתם אותה אל אלעזר:","הוא משום שמצותה בסגן, ולא בכהן גדול. והעמידוהו, מהו הטעם, לאלעזר ולא לאהרן. ומשיב, אלא אהרן הוא שושבין של המלכה. וע\"כ אינו ראוי למעשה הפרה שהוא דין. ועוד שאהרן אינו בא מצד טהור, אלא מצד קדוש (ההפרש מטהור לקדוש נתבאר לעיל תזריע דף מ\"ה ד\"ה אמנם ע\"ש כל ההמשך) ומשום שפרה אדומה באה לטהרה, ע\"כ לא ניתנה לו."],[6,"כל מלה דהאי וכו':","כל דבר שבפרה הזו שהיא המלכות, היא בשבע, ז' כבוסים וכו' וכבר למדנו (לעיל פרשת אחרי אות שנ\"ה) מהו הטעם. הוא משום שהמלכות היא שבע שני השמיטה, שכוללת ז' ספירות חג\"ת נהי\"מ, ונקראת \u0003בת שבע,\u0004 וע\"כ כל מעשיה בשבע. בוא וראה, כל מה שנעשה מפרה הזו הוא כדי לטהר, ולא לקדש. ואע\"פ שניתנה לסגן הכהנים שהוא אלעזר, הוא אינו שוחט ואינו שורף, כדי שלא ימצא דין מצדו. וכל שכן אהרן שהוא במדרגה השלמה יותר מאלעזר, שאינו צריך להמצא שם ולהזדמן שם."],[7,"האי פרה כיון וכו':","פרה זו כיון שנעשית אפר, צריכים להשליך בה, עץ ארז ואזוב ושני תולעת. ואלו כבר למדנו (לעיל מצורע אות י\"ט ע\"ש) ואסף איש טהור. ולא קדוש. והניח מחוץ למחנה במקום טהור. כי אינו נקרא טהור אלא מצד שהיה תחילה טמא."],[8,"רזא דכלא האי וכו':","סוד הכל. זה שכתוב, למי נדה חטאת היא. הוא משום שכל דינים התחתונים וכל אלו הבאים מצד הטומאה, מקבלים כחם מן המלכות, בעת שיונקת מצד האחר, דהיינו מצד השמאל כמו שהיתה במצב הא' כנ\"ל. ויושבת בדין. כש\"א, מלאה דם הודשנה מחלב. אז כל הדינים של צד הטומאה, מתעוררים ומתעלים ושורים בעולם. כיון שעושים מעשה ההיא, של שרפת הפרה, למטה, וכל הדין הזה נעשה במקום הזה, בפרה הזו, ומשליכים עליה עץ ארז וגו', אז נחלש הכח שלהם, של צד הטומאה, ובכל מקום ששורים המה נשברים ונחלשים, ובורחים משם, כי כח הזה שלהם נראה להם נשבר ומדוכה כמו שנעשה בשרפת הפרה, ואז אינם שורים באדם, והוא נטהר."],[9,"וע\"ד אתקרי מי נדה וכו':","וע\"כ נקראים מי נדה, שפירושו, מים לטהר כשהעולם שורה בדין וצד הטומאה נתפשט בעולם, כמו בטומאת נדה. כאן נכללו כל מיני טומאה וכל מיני טהרה. ומשום זה טומאה וטהרה הן כלל עליון של התורה. והעמידוהו החברים. א\"ר שמעון, אלעזר, עשית, שלא יאמרו החברים דבר אחריך. כי מרוב החכמה והשלמות שבדבריך, יתביישו לומר דבריהם."],[10,"פרה אדומה תמימה וכו':","אסור לחרוש בשבת חרישה של שור (כמ\"ש להלן פרשת פנחס אות תקצ\"ב דף רמ\"ג ע\"ב דפו\"י) שנאמר, על גבי חרשו חורשים. ושכינה תחתונה, דהיינו מלכות, היא פרה אדומה, מצד הגבורה. והיא תמימה מצד החסד, שהוא מדרגת אברהם, שנאמר בו, התהלך לפני והיה תמים. אשר אין בה מום, היא מצד עמוד האמצעי, שהוא ז\"א המיחד שמאל וימין שלה. אשר לא עלה עליה עול, היא מצד שכינה עליונה, שהיא חירות, דהיינו בינה. במקום שהיא שולטת, דהיינו המלכות הכלולה מכל הנ\"ל, והזר הקרב יומת, אין רשות לסטרא אחרא לשלוט, לא שטן, ולא משחית, ולא מלאך המות, שהם מצד הגיהנם. ע\"כ ר\"מ (וזהו דרך אחר ממה שפירש הזהר לעיל באות י\"ח י\"ט כ')."]],[[0,"","זֹאת חֻקַּת הַתּוֹרָה. זֹּאת - זוֹ אוֹת הַבְּרִית, שֶׁלֹּא יִפָּרְדוּ זֶה מִזֶּה (וכאשר נפרע זה הכל) שֶׁנִּקְרָא זֶה, וּמֵהַנְּקֵבָה עוֹלָה לַזָּכָר. וְעַל זֶה שָׁמוֹ\"ר וְזָכוֹ\"ר מִתְחַבְּרִים כְּאֶחָד. חֻקַּת הַתּוֹרָה?! חֹק הַתּוֹרָה צָרִיךְ לִהְיוֹת! מַה זֶּה חֻקַּת?"],[1,"","אֶלָּא חֻקַּת בְּוַדַּאי, וּבֵאַרְנוּ, ה' הָיְתָה ד' (חק), וַהֲרֵי נִתְבָּאֵר. אֲבָל ת' הוּא ד' וְנ' מְחֻבָּרִים כְּאֶחָד. וְנוּ\"ן הֲרֵי נִתְבָּאֵר, נוּ\"ן לָמָּה נִקְרֵאת כָּךְ בְּנוּ\"ן? אֶלָּא כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כה) וְלֹא תוֹנוּ אִישׁ אֶת עֲמִיתוֹ. שֶׁכָּעֵת הִיא בְּפָנִים מְאִירוֹת וְעוֹשָׂה אוֹנָאָה לִבְנֵי אָדָם, וְאַחַר כָּךְ מַכָּה כְּמוֹ נָחָשׁ, וּמַשְׁמִידָה וְהוֹרֶגֶת, (משליל) וְאָמְרָה לֹא פָעַלְתִּי אָוֶן. וְעַל זֶה כָּךְ נִקְרֵאת בְּנוּ\"ן שֶׁנֶּאֱמַר עָלֶיהָ. ת' הַכֹּל כְּאֶחָד - דָּלֶ\"ת נוּ\"ן. ד' נוּ\"ן דָּלֶ\"ת רֵי\"שׁ (ה\"א ה\"א) (נו\"ן רי\"ש), רֵי\"שׁ וְדָלֶ\"ת דָּבָר אֶחָד הוּא. וּבְאוֹתִיּוֹת חֲקוּקוֹת הֵם חֹק וְת', וְהַכֹּל דָּבָר אֶחָד."],[2,"","דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל וְיִקְחוּ אֵלֶיךְ פָרָה. פָּרָה זוֹ בָּאָה לְטַהֵר. לְטַהֵר לַטְּמֵאִים. פָּרָה שֶׁמְּקַבֶּלֶת מֵהַשְּׂמֹאל. וּמִי הוּא לַשְּׂמֹאל? שׁוֹר, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל א) וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל. אֲדֻמָּה - סְמוּקָה כַּשּׁוֹשַׁנָּה, שֶׁכָּתוּב (שיר ב) כְּשׁוֹשַׁנָּה בֵּין הַחוֹחִים. אֲדֻמָּה - גְּזֵרַת הַדִּין."],[3,"","תְּמִימָה, מַה זֶּה תְּמִימָה? כְּמוֹ שֶׁשָּׁנִינוּ, שׁוֹר תָּם וְשׁוֹר מוּעָד. שׁוֹר תָּם דִּין רָפֶה. שׁוֹר מוּעָד דִּין קָשֶׁה. גַּם כָּךְ תְּמִימָה דִּין רָפֶה, גְּבוּרָה תַחְתּוֹנָה, זוֹהִי תְמִימָה. גְּבוּרָה עֶלְיוֹנָה, זֶהוּ דִּין קָשֶׁה, וְהִיא יָד הַחֲזָקָה תַּקִּיפָה."],[4,"","אֲשֶׁר אֵין בָּהּ מוּם, כְּמוֹ שֶׁנֶּאֱמַר (שיר השירים ד) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ. אֲשֶׁר לֹא עָלָה עָלֶיהָ עֹל, עַל כָּתוּב, כְּמוֹ שֶׁנֶּאֱמַר (שמואל ב כג) וּנְאֻם הַגֶּבֶר הוּקַם עָל. מָה הַטַּעַם? מִשּׁוּם שֶׁהִיא (שם כ) שְׁלֻמֵי אֱמוּנֵי יִשְׂרָאֵל, וְעָלֶיהָ לֹא הִיא, אֶלָּא עִמָּהּ. אֲשֶׁר לֹא עָלָה עָלֶיהָ עֹל, הַיְנוּ שֶׁכָּתוּב (עמוס ה) בְּתוּלַת יִשְׂרָאֵל, (בראשית כד) בְּתוּלָה וְאִישׁ לֹא יְדָעָהּ."],[5,"","וּנְתַתֶּם אֹתָהּ אֶל אֶלְעָזָר, מִצְוָתָהּ בַּסְּגָן, וּפֵרְשׁוּהָ. מָה הַטַּעַם לוֹ וְלֹא לְאַהֲרֹן? אֶלָּא אַהֲרֹן שׁוֹשְׁבִין הַמַּלְכָּה. וְעוֹד, שֶׁאַהֲרֹן לֹא בָא מִצַּד שֶׁל טָהוֹר, אֶלָּא מִצַּד שֶׁל קָדוֹשׁ, וּמִשּׁוּם שֶׁזֶּה בָּא לְטָהֳרָה, לֹא נִתַּן לוֹ."],[6,"","כָּל דָּבָר בְּפָרָה זוֹ הִיא בְּשֶׁבַע, שִׁבְעָה כִבּוּסִים וְכוּ', וַהֲרֵי נִתְבָּאֵר. מָה הַטַּעַם? מִשּׁוּם שֶׁהִיא שֶׁבַע שְׁנֵי שְׁמִטָּה, וּבַת שֶׁבַע נִקְרֵאת, וְעַל כָּךְ כָּל מַעֲשֶׂיהָ בְּשֶׁבַע. בֹּא וּרְאֵה, כָּל מַה שֶּׁנַּעֲשָׂה מִפָּרָה זוֹ - בִּשְׁבִיל לְטַהֵר, וְלֹא לְקַדֵּשׁ. וְאַף עַל גַּב שֶׁנִּתְּנָה לַסְּגָן, הוּא לֹא שׁוֹחֵט וְלֹא שׂוֹרֵף, בִּשְׁבִיל שֶׁלֹּא יִמָּצֵא דִין בְּצִדּוֹ, וְכָל שֶׁכֵּן אַהֲרֹן, שֶׁהוּא בְּדַרְגָּה יוֹתֵר מֻשְׁלֶמֶת, וְלֹא צָרִיךְ לְהִמָּצֵא שָׁם וּלְהִזְדַּמֵּן לְשָׁם."],[7,"","פָּרָה זוֹ, כֵּיוָן שֶׁנֶּעֶשְׂתָה אֵפֶר, צָרִיךְ לִזְרֹק בָּהּ עֵץ אֶרֶז וְאֵזוֹב וּשְׁנִי תוֹלַעַת, וַהֲרֵי אֵלֶּה נֶאֶמְרוּ. וְאָסַף אִישׁ טָהוֹר, וְלֹא קָדוֹשׁ. וְהִנִּיחַ מִחוּץ לַמַּחֲנֶה בְּמָקוֹם טָהוֹר, שֶׁהֲרֵי טָהוֹר לֹא נִקְרָא אֶלָּא מִצַּד שֶׁמְּטַמֵּא בַּהַתְחָלָה."],[8,"","סוֹד הַכֹּל, זֶה שֶׁכָּתוּב לְמֵי נִדָּה חַטָּאת הִיא. מִשּׁוּם שֶׁכָּל דִּינִים הַתַּחְתּוֹנִים וְכָל אֵלּוּ שֶׁבָּאִים מִצַּד הַטֻּמְאָה, כְּשֶׁיּוֹנְקִים מִצַּד אַחֵר וְיוֹשְׁבִים בְּדִין, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה לד) מָלְאָה דָם הֻדַּשְׁנָה מֵחֵלֶב, אָז כֻּלָּם מִתְעוֹרְרִים וּמִסְתַּלְּקִים וְשׁוֹרִים בָּעוֹלָם. כֵּיוָן שֶׁעוֹשִׂים מַעֲשֶׂה זֶה שֶׁלְּמַטָּה, וְכָל הַדִּין הַזֶּה בְּמָקוֹם זֶה שֶׁל פָּרָה זוֹ, וְזוֹרְקִים עָלֶיהָ עֵץ אֶרֶז וְגוֹ', אָז נֶחֱלָשׁ כֹּחָם, וּבְכָל מָקוֹם שֶׁשּׁוֹרִים נִשְׁבָּרִים וְנֶחֱלָשִׁים וּבוֹרְחִים מִשָּׁם, שֶׁהֲרֵי כֹּחָם נִרְאֶה כְּמוֹ זֶה לְגַבֵּיהֶם, וְאָז לֹא שׁוֹרִים בָּאָדָם, וְהוּא נִטְהָר."],[9,"","וְעַל זֶה נִקְרָאִים מֵי נִדָּה, מַיִם לְטַהֵר. כְּשֶׁהָעוֹלָם שָׁרוּי בְּדִין וְצַד הַטֻּמְאָה מִתְפַּשֵּׁט בָּעוֹלָם, כָּאן נִכְלָלִים כָּל מִינִים שֶׁל טֻמְאָה וְכָל מִינֵי טָהֳרָה, וּמִשּׁוּם זֶה טֻמְאָה וְטָהֳרָה כְּלָל עֶלְיוֹן בַּתּוֹרָה, וּבֵאֲרוּהָ הַחֲבֵרִים. אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר, עָשִׂיתָ שֶׁלֹּא יאמְרוּ הַחֲבֵרִים דָּבָר אַחֲרֶיךְ."],[10,"","פָרָה אֲדֻמָּה תְּמִימָה אֲשֶׁר אֵין בָּהּ מוּם וְגוֹ'. אָסוּר לַחֲרשׁ בְּשַׁבָּת חֲרִישָׁה שֶׁל שׁוֹר, שֶׁנֶּאֱמַר (תהלים קכט) עַל גַּבִּי חָרְשׁוּ חֹרְשִׁים. וּשְׁכִינָה תַחְתּוֹנָה הִיא פָּרָה אֲדֻמָּה - מִצַּד הַגְּבוּרָה. תְּמִימָה - מִצַּד הַחֶסֶד, שֶׁהוּא דַּרְגַּת אַבְרָהָם, שֶׁנֶּאֱמַר בּוֹ (בראשית יז) הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים. אֲשֶׁר אֵין בָּהּ מוּם - מִצַּד הָעַמּוּד הָאֶמְצָעִי. אֲשֶׁר לֹא עָלָה עָלֶיהָ עֹל - מִצַּד שְׁכִינָה עֶלְיוֹנָה שֶׁהִיא חֵרוּת. בְּמָקוֹם שֶׁהִיא שׁוֹלֶטֶת, וְהַזָּר הַקָּרֵב אֵין לוֹ רְשׁוּת לַצַּד הָאַחֵר לִשְׁלֹט, לֹא שָׂטָן וְלֹא מַשְׁחִית וְלֹא מַלְאַךְ הַמָּוֶת, שֶׁהֵם מִצַּד הַגֵּיהִנֹּם."]]],[["פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהילים ק״ד:י׳) הַמְשַׁלֵּחַ מַעְיָנִים בַּנְּחָלִים וְגוֹ'. יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי וְגוֹ'. הָנֵי קְרָאֵי דָּוִד מַלְכָּא בְּרוּחָא קַדִּישָׁא אַמָרָן, וְאִית לְאִסְתַּכְּלָא בְּהוּ. תָּא חֲזֵי, בְּשַׁעֲתָא דְּחָכְמְתָא עִלָּאָה בָּטַשׁ בִּגְלִיפוֹי, אַף עַל גַּב דְּהִיא טְמִירָא בְּכָל סִטְרִין, פָּתַח וְאִתְנְגִיד מִנֵּיהּ חַד נַהֲרָא, מַלְיָא (נ\"א ומלייא לתרעין) בְּתַרְעִין עִלָּאִין.","כְּמַבּוּעָא וּמְקוֹרָא דְּמַיָא דְּמָלֵּי קוּזְפָא רַבָּא מִנֵּיהּ, וּמִתַּמָּן אִתְמַשְּׁכָן מַבּוּעִין דְּנַחֲלִין וְנַהֲרִין בְּכָל סְטָר, כַּךְ הַאי, בְּחַד שְׁבִיל דָּקִיק דְּלָא אִתְיְידַע, מָשִׁיךְ וְנָגִיד הַהוּא נָהָר דְּנָגִיד וְנָפִיק, וּמְמַלֵּי לְהַהוּא נַחֲלָא עֲמִיקָא, וּמִתַּמָּן אִתְמַשְּׁכָאן מַבּוּעִין וּנְחָלִין, וְאִתְמַלְּיָין מִנֵּיהּ. הֲדָא הוּא דִכְתִיב, הַמְשַׁלֵּחַ מַעְיָנִים בַּנְּחָלִים וְגוֹ'. אִלֵּין נַהֲרֵי עִלָּאֵי קַדִּישָׁא דְּאֲפַרְסְמוֹנָא דַּכְיָיא, וְכֻלְּהוּ אִתְשַׁקְיָין כְּחַד מֵהַהוּא נְבִיעָא דְּנַחֲלָא עִלָּאָה קַדִּישָׁא דְּנָפִיק וְנָגִיד.","לְבָתַר, יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי, הַיְינוּ דִּכְתִּיב, (בראשית ב׳:י׳) וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים. הָנֵי ד' רָאשִׁין, אִלֵּין אִינּוּן חַיְתוֹ שָׂדָי, כְּלָלָא דְּכָל אִינּוּן מַשִׁרְיָין, וְכָל אִינּוּן חַיָּילִין, דַּאֲחִידָן בְּהוּ שָׂדַי, אַל תִּקְרֵי שָׂדָי, אֶלָּא שַׁדָּי. דְּהוּא נָטִיל, וְאַשְׁלִים שְׁמָא מִיְּסוֹדָא דְּעָלְמָא.","יִשְׁבְּרוּ פְרָאִים צְמָאָם, אִלֵּין אִינּוּן דִּכְתִּיב בְּהוּ, (יחזקאל א׳:כ׳) וְהָאוֹפַנִּים יִנָּשְׂאוּ לְעֻמָּתָם כִּי רוּחַ הַחַיָּה בָּאוֹפַנִּים, מַאן חַיָּה. אֶלָּא אִלֵּין חַיְתוֹ שָׂדָי, אַרְבַּע אִינּוּן, וְכָל חַד וְחַד לְחַד סִטְרָא דְּעָלְמָא. וְהַהוּא אִקְרֵי חַיָּה, וְאוֹפַנִּים לָקֳבֵיל כָּל חַד וְחַד. וְלָא אַזְלִין אֶלָּא מֵרוּחַ דְּהַהִיא חַיָּה דְּאָזִיל עָלַיְיהוּ וְכַד אִלֵּין מִתְשַׁקְיָין מֵהַהוּא שַׁקְיוּ עִלָּאָה, כָּל שְׁאַר חַיָּילִין אַחֲרָנִין אִשְׁתַּקְיָין, וְאִתְרַוָון, וּמִשְׁתָּרְשָׁן בְּשָׁרְשַׁיְיהוּ, וְאִתְאַחֲדָן אִלֵּין בְּאִלֵּין, בְּדַרְגִּין יְדִיעָן. הֲדָא הוּא דִכְתִיב, עֲלֵיהֶם עוֹף הַשָּׁמַיִם יִשְׁכּוֹן וְגוֹ'. מַשְׁקֶה הָרִים מֵעֲלִיּוֹתָיו וְגוֹ'. אִלֵּין שְׁאַר דַּרְגִּין עִלָּאִין.","לְבָתַר כָּל דָּא, מִפְּרִי מַעֲשֶׂיךָ תִּשְׂבַּע הָאָרֶץ, (ס\"א לתתא וכל עלמין וכו') אַרְעָא עִלָּאָה קַדִּישָׁא. וְכַד אִיהִי מִתְבָּרְכָא, כָּל עָלְמִין כֻּלְּהוּ חַדָּאן, וּמִתְבָּרְכָאן. דָּא בְּשַׁעֲתָא דְּבִרְכָּאן מִשְׁתַּכְּחֵי, מִשַּׁקְיוּ דְּנַחֲלָא (בראשית רכ\"א ע\"א) עֲמִיקָא דְּכֹלָּא.","וּבְשַׁעֲתָא דְּעָלְמָא יְתִיב בְּדִינָא דְּבִרְכָאן לָא מִשְׁתַּכְּחֵי לְנַחְתָּא בְּעָלְמָא, כְּדֵין אִסְתְּאַב מִקְדָּשׁ (ס\"א ובשעתא דברכאן לא משתכחי לנחתא בעלמא, כדין עלמא יתיב בדינא, ומסטרא דשמאלא רוחא אתער ואתפשט בעלמא) וְכַמָּה חֲבִילֵי טְרִיקִין מִשְׁתַּכְּחֵי בְּעָלְמָא, וְשָׁרָאן (בכמה אתרי) עַל בְּנֵי נָשָׁא, וּמְסָאַב הַהוּא רוּחָא לְהוּ, כְּבַר נָשׁ דְּגָוַע (ס\"א כבר האי רוח) וְרוּחַ מִסְאֲבָא שַׁרְיָא עָלֵיהּ. הָכִי נָמֵי שַׁרְיָא, לְמַעַן דְּיִקְרַב בַּהֲדֵיהּ.","הֲדָא הוּא דִכְתִיב, תַּסְתִּיר פָּנֶיךָ יִבָּהֵלוּן וְגוֹ'. הַאי קְרָא מַאי קָא מַיְירֵי. אֶלָּא תַּסְתִּיר פָּנֶיךָ יִבָּהֵלוּן, דְּהָא לָא אִתְשַׁקְיָין לְאִשְׁתַּכְּחָא בִּרְכָאן לְעָלְמִין. תּוֹסֵף רוּחָם יִגְוָעוּן, (נ\"א לאתערא) וְאִתְּעַר רוּחָא אַחֲרָא מִסִּטְרָא שְׂמָאלָא, וְרוּחַ מִסְאֲבָא שַׁרְיָא עַל בְּנֵי נָשָׁא, עַל אִינּוּן דְּמֵיתִין, וּמַאן דְּקָאִים בַּהֲדַיְיהוּ, וְעַל שְׁאַר בְּנֵי נָשָׁא, מַאי אַסְוָותָא דִּלְהוֹן. הָא דִּכְתִּיב וְאֶל עֲפָרָם יְשׁוּבוּן. דָּא עֲפַר שְׂרֵיפַת הַחַטָּאת, (ס\"א דא עפר מקדשא דלעילא) בְּגִין לְאִתְדַכְּאָה בֵּיהּ. וְהַיְינוּ רָזָא (קהלת ג׳:כ׳) הַכֹּל הָיָה מִן הֶעָפָר, ואֲפִילּוּ גַּלְגַּל חַמָּה.","לְבָתַר דִּמְהַדְרִן לְהַאי עָפָר, בְּגִין לְאִתְדַכְּאָה בֵּיהּ, מִתְעַבָר רוּחָא מִסְאֲבָא, וְאִתְּעַר רוּחָא אַחֲרָא קַדִּישָׁא, וְשָׁארִי בְּעָלְמָא. הֲדָא הוּא דִכְתִיב, תְּשַׁלַּח רוּחֲךָ יִבָּרֵאוּן, יִבָּרֵאוּן, וְיִתְּסוּן בְּאַסְוָותָא עִלָּאָה, דְּרוּחָא אַחֲרָא. וּתְחַדֵּשׁ פְּנֵי אֲדָמָה, דְּהָא אִתְדַכִּיאַת, (אתתא לבעלה) וְחַדְתּוּתֵי דְּסִיהֲרָא אִשְׁתְּכַח, וְעָלְמִין כֻּלְּהוּ מִתְבָּרְכָאן. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְקוּדְשָׁא בְּרִיךְ הוּא יָהִיב לוֹן עֵיטָא, דְּכֹלָּא אַסְוָותָא, בְּגִין דְּיִזְכּוּן לְחַיֵּי עָלְמָא דְּאָתֵי, וְיִשְׁתְּכָחוּ דַּכְיָין בְּהַאי עָלְמָא, קַדִּישִׁין לְעָלְמָא דְּאָתֵי, עָלַיְיהוּ כְּתִיב (יחזקאל ל״ו:כ״ה) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם."],[[0,"פתח ר\"ש ואמר וכו':","פר\"ש ואמר, המשלח מעינים בנחלים וגו'. ישקו כל חיתו שדי וגו'. מקראות אלו אמר דוד המלך ברוח הקדש, ויש להסתכל בהם. בוא וראה, בשעה שחכמה עליונה בטש בחקיקותיו, דהיינו בעת שהחכמה ובינה עליונים נזדווגו, אע\"פ שחכמה עליונה היא נסתר שבכל הנסתרות, כי בחו\"ב עליונים שהם או\"א עלאין, אין ה \u0003י'\u0004 יוצא מאויר (כנ\"ל ב\"א דף רנ\"א ד\"ה נחית) הוא פתח ונמשך ממנו נהר אחד מלא בשערים עליונים, שהוא בינה, דהיינו ישסו\"ת, שבהם יוצא ה \u0003י'\u0004 מאויר ומושפע מהם חכמה וחסדים."],[1,"כמבועא ומקורא דמיא וכו':","והמשיל ענין זה של או\"א עלאין וישסו\"ת, כמו מבוע ומקור המים, הממלא אגם גדול, ומשם, מן האגם, נמשכים מבועים ונחלים ונהרות לכל צד, לימין ולשמאל, כך זה, או\"א וישסו\"ת, בשביל דק אחד שלא נודע, דהיינו בזווג היסודות דאו\"א עלאין שהם בלתי נודעים, שבהם אין ה \u0003י'\u0004 יוצא מאויר, נמשך ויוצא אותו הנהר הנמשך ויוצא מן העדן, דהיינו הבינה שיצאה מראש א\"א, בעת קטנות וחזרה לראש א\"א, בעת גדלות (עי' ויקהל ק\"ד [ש\"י] ד\"ה פירוש) שע\"י יציאה וביאה זו, הוא ממלא אותו הנחל העמוק, דהיינו ישסו\"ת, בדומה לאגם המים הגדול המתמלא מן המבוע והמקור שהם או\"א עלאין, ומשם נמשכים מבועים ונחלים לז\"א ומלכות, ומתמלאים ממנו, בחכמה וחסדים. ז\"ש, המשלח מעינים בנחלים. אלו הם הנהרות העליונים הקדושים של ז\"א, של אפרסמון הטהור, כי ה\"ס אוירא דכיא, שחג\"ת של ז\"א מקבלים מאו\"א עלאין, שה\"ס אפרסמון הטהור. והיינו, בין הרים יהלכון, שהם חג\"ת דז\"א הנקראים הרים. וממנו מקבלת המלכות. וכולם, ז\"א ומלכות, שותים כאחד מאותו הנביע של נחל העליון הקדוש הנמשך ויוצא, שהוא ישסו\"ת."],[2,"לבתר ישקו כל וכו':","אח\"כ, אחר ששתו ז\"א ומלכות, ישקו כל חיתו שדי. היינו שכתוב, ומשם יפרד והיה לארבעה ראשים, אלו ד' ראשים, הם כל חיתו שדי, שהם ד' חיות אריה שור נשר אדם, שהם המרכבה של המלכות, והם כלל של כל המחנות וכל הצבאות שבבי\"ע, שאחוז בהם שדי, דהיינו מטטרון שנקרא שדי, שהוא העליון על כולם, אל תקרא \u0003שדי\u0004 עם שין שמאלית קמוצה, אלא שדי, עם שין ימנית פתוחה, שהוא, מטטרון, נוטל ומשלים בעצמו השם, מיסוד העולם, כי השם שדי הוא ביסוד דז\"א, ומטטרון להיותו מרכבה ליסוד דז\"א, נוטל שם הזה."],[3,"ישברו פראים צמאם:","הם אלו שכתוב בהם והאופנים ינשאו לעומתם, כי רוח ה \u0003חיה\u0004 באופנים. מי הוא חיה. אלא אלו הן \u0003חיתו שדי,\u0004 שהן ארבע, וכל אחת מהן לרוח אחד מד' רוחות שבעולם, וההיא, נקראת חיה, והאופנים הם ארבע, לכל אחת ואחת מן ארבע החיות, וכל אחד שבאופנים. אינו הולך אלא מרוח אותו החיה ההולכת עליו. דהיינו כל אחד מאופנים מרוח הבחינה שכנגדו בחיות. וכאשר אלו, החיות והאופנים, נשקים משקוי העליון ההוא, כל שאר צבאות אחרים נשקים ומתרוים ומשתרשים בשרשיהם. ומתאחדים אלו באלו במדרגות ידועות. ז\"ש, עליהם עוף השמים ישכון וגו' משקה הרים מעליותיו וגו', אלו שאר המדרגות העליונות."],[4,"לבתר כל דא וכו':","לאחר כל זה, שכל העליונים ותחחונים נתמלאו שפע מאו\"א, נאמר, מפרי מעשיך תשבע הארץ, שהיא ארץ עליונה הקדושה, דהיינו המלכות, וכשהיא מתברכת, כל העולמות כולם שמחים ומתברכים, וזה בשעה שהברכות נמצאות משקוי הנחל, שהוא המבוע הנ\"ל, שהם או\"א, העמוק מכל. פירוש, כי אין הארת החכמה שמשמאל, מתגלה במלכות, שהיא השפע המיוחד לה, אלא אחר שהעליונים וכל התחתונים מתמלאים בשפע חסדים המרובים מאו\"א עלאין. וז\"ש, \u0003לבתר כל דא\u0004 וכו'."],[5,"ובשעתא דברכאן לא וכו':","ובשעה שברכות אינן נמצאות לרדת בעולם שהם החסדים והמלכות מקבלת חכמה משמאל בלא חסדים, אז העולם, שהוא המלכות, יושבת בדין, ומצד השמאל נתעורר רוח ומתפשט בעולם, וכמה גדודי מלאכי חבלה נמצאים בעולם, ושורים על בני אדם, כי בעת שהחכמה היא בלי חסדים, כל דינים הקשים נמשכים ממנה, ואותו הרוח מטמא אותם, כמו אדם שמת ורוח הטומאה שורה עליו, כך הוא שורה למי שיקרב אל אותו הרוח דשמאל."],[6,"הה\"ד תסתיר פניך וגו':","ז\"ש תסתיר פניך יבהלון. מקרא זה מה הוא אומר, אלא תסתיר פניך יבהלון, הוא מפני שלא נשקו המדרגות, שתמצאנה ברכות בעולם, כי \u0003פניך,\u0004 פירושו חסדים וברכות, אז, תוסף רוחם יגועון, שנתעורר רוח אחר מצד שמאל בלי ימין, ורוח הטומאה שורה על בני אדם, על אלו שמתו, ואותם שנמצאו עמהם, ועל שאר בני אדם. כלומר שרוח הטומאה מתפשט על כל העולם, ומהו הרפואה שלהם. הוא שכתוב, ואל עפרם ישובון. שזהו שריפת החטאת, כדי להטהר בו. והיינו סוד, הכל היה מן העפר ואפילו גלגל חמה."],[6,"","פירוש. בעת שעונות התחתונים גורמים שיסתלקו החסדים מן המלכות, ונעשה פרוד בין ז\"א למלכות, אז נמצאת המלכות יונקת משמאל בלי ימין כמו במצב הא', ואז מאיר השמאל ממעלה למטה, שה\"ס רוח הטומאה, המטמא את העולם. וכל אדם הקרב אל רוח ההוא, הוא כמו מת. ויש ג' בחינות. א', הממשיך את רוח ההוא דהיינו שממשיכו ממעלה למטה. ב' המקבלו אחר שנמשך. ג' שאינו מקבלו אלא הוא מושפע ממנו בלי כוונה. וז\"ש \u0003תוסף רוחם יגועון, ואתער רוח אחרא מסטרא שמאלא\u0004 שהוא מאיר ממעלה למטה, וע\"כ, \u0003ורוח מסאבא שרייא על בני נשא,\u0004 שיש בו ג' בחינות, א', \u0003על אינון דמיתון,\u0004 דהיינו אותם שממשיכים אותו. ב', \u0003ומאן דקאים בהדייהו,\u0004 דהיינו הנמצאים עם הממשיכים את הרוח, וגם הם מקבלים אותו. ג', \u0003ועל שאר בני נשא,\u0004 שלא המשיכו אותו גם לא קבלו אותו אלא שמושפעים בלי כוונה לכך, מחמת שליטתו על העולם."],[6,"","וז\"ש, \u0003מאי אסוותא דלהון, הא דכתיב, ואל עפרם ישובון, דא עפר שריפת החטאת,\u0004 פירוש. כי נתבאר סוד פרה אדומה, שהיא המשכת מצב הא' של המלכות עם כל דינים הקשים שעברו אז על המלכות, עד שנתמעטה ממצב הא', שחזרה לנקודה, שה\"ס שריפת הפרה עד שנעשית לאפר, ואז קבלה מצב הב', ובאה עם ז\"א פנים בפנים (כנ\"ל אות כ' ע\"ש). והמיעוט הזה שחזרה לנקודה, נבחנת כמו עפר, הנשאר אחר העלמת הבנין. וז\"ס \u0003עפר שריפת החטאת,\u0004 דהיינו מה שנשאר אחר כל הדינין שעברו על מצב הא'. ולפיכך בעת שרוח הטומאה מתפשט בעולם מחמת חטאי התחתונים, כנ\"ל, שהוא בחינת שמאל בלי ימין כמו שהמלכות היתה במצב הא', הנה כשמתעוררים עפר שריפת החטאת הוא מבריח תיכף רוח הטומאה הזה ושובר אותו ושורף אותו עד שבורח מן העולם. (כנ\"ל באות כ\"ד) שאומר, \u0003כדין אתחלש חילא דלהון ובכל אתר דשראן אתברו ואתחלשו וערקין מניה\u0004 וכו'. הרי שכל הרפואה היא \u0003ואל עפרם ישובון,\u0004 דהיינו להזות עליו \u0003מעפר שרפת החטאת.\u0004 ונודע שלולא נתמעטה המלכות ממצב הא' וחזרה עד לנקודה, לא היה העולם יכול להתקיים, מחמת רוב הדינים שהיה במצב הא' של המלכות. והמיעוט עד לנקודה נקרא עפר, וז\"ש. \u0003והיינו רזא, הכל היה מן העפר ואפילו גלגל חמה\u0004. כי לולא מיעוט הזה, לא היה קיום לכל מעשה בראשית."],[7,"לבתר דמהדרן וכו':","לאחר שחוזרים לעפר הזה, כדי להטהר בו, כנ\"ל בדבור הסמוך, נעבר רוח הטומאה ונתעורר רוח אחר קדוש, ושורה בעולם. ז\"ש, \u0003תשלח רוחך יבראון\u0004 יבראו וירפאו ברפואה עליונה של רוח אחר. \u0003ותחדש פני האדמה,\u0004 כי נטהרה, וחדוש הלבנה נמצא, וכל העולמות מתברכים. שכל זה ה\"ס מצב הב', כנ\"ל בדבור הסמוך. אשרי חלקם של ישראל, שהקב\"ה נתן להם עצה, שכולה היא רפואה כדי לזכות לחיי עולם הבא, וימצאו טהורים בעולם הזה, וקדושים לעולם הבא. עליהם כתוב, וזרקתי עליכם מים טהורים וטהרתם."]],[[0,"","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים קד) הַמְשַׁלֵּחַ מַעְיָנִים בַּנְּחָלִים וְגוֹ'. יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי וְגוֹ'. פְּסוּקִים אֵלּוּ אֲמָרָם דָּוִד הַמֶּלֶךְ בְּרוּחַ הַקֹּדֶשׁ, וְיֵשׁ לְהִסְתַּכֵּל בָּהֶם. בֹּא וּרְאֵה, בְּשָׁעָה שֶׁחָכְמָה עֶלְיוֹנָה מַכָּה בַחֲקִיקוֹת, אַף עַל גַּב שֶׁהִיא נִסְתֶּרֶת בְּכָל הַצְּדָדִים, נִפְתָּח וְשׁוֹפֵעַ מִמֶּנָּה נָהָר אֶחָד מָלֵא (וממלא לשערים) בִשְׁעָרִים עֶלְיוֹנִים."],[1,"","כְּמַבּוּעַ וּמָקוֹר שֶׁל מַיִם שֶׁמְּמַלֵּא כְּלִי גָּדוֹל מִמֶּנּוּ, וּמִשָּׁם נִמְשָׁכִים מַבּוּעִים שֶׁל נְחָלִים וּנְהָרוֹת בְּכָל צַד - כָּךְ זֶה, בִּשְׁבִיל דַּקִּיק אֶחָד שֶׁלֹּא נוֹדָע, מוֹשֵׁךְ וְשׁוֹפֵעַ אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא וּמְמַלֵּא לְאוֹתוֹ נַחַל עָמֹק, וּמִשָּׁם נִמְשָׁכִים מַבּוּעִים וּנְחָלִים וּמִתְמַלְּאִים מִמֶּנּוּ. זֶהוּ שֶׁכָּתוּב הַמְשַׁלֵּחַ מַעְיָנִים בַּנְּחָלִים וְגוֹ'. אֵלֶּה נְהָרוֹת עֶלְיוֹנֵי קֹדֶשׁ שֶׁל אֲפַרְסְמוֹן זַךְ, וְכֻלָּם מֻשְׁקִים כְּאֶחָד מֵאוֹתָהּ נְבִיעַת הַנַּחַל הָעֶלְיוֹן הַקָּדוֹשׁ שֶׁיּוֹצֵא וְשׁוֹפֵעַ."],[2,"","אַחַר כָּךְ, יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי, הַיְנוּ שֶׁכָּתוּב (בראשיתב) וּמִשָּׁם יִפָּרֵד וְהָיָה לְאַרְבָּעָה רָאשִׁים. אַרְבָּעָה רָאשִׁים אֵלֶּה הֵם חַיְתוֹ שָׂדָי, כְּלַל כָּל אוֹתָן מֶרְכָּבוֹת וְכָל אוֹתָם חֲיָלוֹת שֶׁשָּׂדַי אֲחוּזָה בָהֶם. אַל תִּקְרֵי שָׂדַי אֶלָּא שַׁדַּי, שֶׁהוּא נוֹטֵל וּמַשְׁלִים אֶת הַשֵּׁם מִיסוֹד הָעוֹלָם."],[3,"","יִשְׁבְּרוּ פְרָאִים צְמָאָם - אֵלֶּה אוֹתָם שֶׁכָּתוּב בָּהֶם (יחזקאל א) וְהָאוֹפַנִּים יִנָּשְׂאוּ לְעֻמָּתָם כִּי רוּחַ הַחַיָּה בָּאוֹפַנִּים. מִי הַחַיָּה? אֶלָּא אֵלּוּ חַיְתוֹ שָׂדָי, אַרְבַּע הֵן, וְכָל אַחַת וְאַחַת לְצַד אֶחָד שֶׁל הָעוֹלָם. וְאוֹתוֹ שֶׁנִּקְרָא חַיָּה, וְאוֹפַנִּים מוּל כָּל אֶחָד וְאֶחָד. וְלֹא הוֹלְכִים אֶלָּא מֵרוּחַ אוֹתָהּ חַיָּה שֶׁהוֹלֶכֶת עֲלֵיהֶם, וְכַאֲשֶׁר אֵלֶּה מֻשְׁקִים מֵאוֹתָהּ הַשְׁקָאָה עֶלְיוֹנָה, כָּל שְׁאָר הַחֲיָלוֹת הָאֲחֵרִים מֻשְׁקִים וּמֻרְוִים וּמִשְׁתָּרְשִׁים בְּשָׁרְשֵׁיהֶם, וְנֶאֱחָזִים אֵלֶּה בְאֵלֶּה בִּדְרָגוֹת יְדוּעוֹת. זֶהוּ שֶׁכָּתוּב עֲלֵיהֶם עוֹף הַשָּׁמַיִם יִשְׁכּוֹן וְגוֹ'. מַשְׁקֶה הָרִים מֵעֲלִיּוֹתָיו וְגוֹ' - אֵלּוּ שְׁאָר דְּרָגוֹת עֶלְיוֹנוֹת."],[4,"","אַחַר כָּל זֶה - מִפְּרִי מַעֲשֶׂיךְ תִּשְׂבַּע הָאָרֶץ, (למטה, וכל העולמות וכו') אֶרֶץ עֶלְיוֹנָה קְדוֹשָׁה. וּכְשֶׁהִיא מִתְבָּרֶכֶת, כָּל הָעוֹלָמוֹת בְּשִׂמְחָה, וּמִתְבָּרְכִים. וְזֶה בְּשָׁעָה שֶׁנִּמְצָאוֹת בְּרָכוֹת מֵהַשְׁקָאַת הַנַּחַל הֶעָמֹק שֶׁל הַכֹּל."],[5,"","וּבְשָׁעָה שֶׁהָעוֹלָם יוֹשֵׁב בְּדִין, שֶׁבְּרָכוֹת לֹא נִמְצָאוֹת לָרֶדֶת בָּעוֹלָם, אָז נִטְמָא הַמִּקְדָּשׁ. (ובשעה שאין נמצאות ברכות לרדת למטה, אז העולם יושב בדין. ומצד שמאל מתעוררת רוח ומתפשטת בעולם) וְכַמָּה חֲבִילוֹת שֶׁל מַזִּיקִים נִמְצָאִים בָּעוֹלָם וְשׁוֹרִים (בכמה מקומות) עַל בְּנֵי אָדָם, וּמְטַמֵּאת אוֹתָם אוֹתָהּ הָרוּחַ, כְּמוֹ בֶּן אָדָם שֶׁגָּוַע (כבר הרוח הזו) וְרוּחַ הַטֻּמְאָה שׁוֹרָה עָלָיו. כָּךְ גַּם שׁוֹרָה, לְמִי שֶׁיִּקְרַב אֵלָיו."],[6,"","זֶהוּ שֶׁכָּתוּב תַּסְתִּיר פָּנֶיךְ יִבָּהֵלוּן וְגוֹ'. פָּסוּק זֶה מַהוּ אוֹמֵר? אֶלָּא תַּסְתִּיר פָּנֶיךְ יִבָּהֵלוּן, שֶׁהֲרֵי לֹא הֻשְׁקוּ לְהִמָּצֵא בְרָכוֹת לָעוֹלָמוֹת. תּוֹסֵף רוּחָם יִגְוָעוּן, (לעורר) וּמִתְעוֹרֵר רוּחַ אַחֵר מִצַּד שְׂמֹאל, וְרוּחַ טֻמְאָה שׁוֹרָה עַל בְּנֵי אָדָם, עַל אוֹתָם שֶׁמֵּתוּ וּמִי שֶׁעוֹמֵד עֲלֵיהֶם וְעַל שְׁאָר בְּנֵי אָדָם, מָה רְפוּאָתָם? זֶה שֶׁכָּתוּב וְאֶל עֲפָרָם יְשׁוּבוּן. זֶה עֲפַר שְׂרֵפַת הַחַטָּאת (זהעפר המקדש שלמעלה) בִּשְׁבִיל לִטַּהֵר בּוֹ, וְהַיְנוּ סוֹד (קהלת ג) הַכֹּל הָיָה מִן הֶעָפָר, וַאֲפִלּוּ גַּלְגַּל חַמָּה."],[7,"","לְאַחַר שֶׁחוֹזְרִים לֶעָפָר זֶה בִּשְׁבִיל לִטַּהֵר בּוֹ, נֶעֱבֶרֶת רוּחַ הַטֻּמְאָה, וּמִתְעוֹרֶרֶת רוּחַ אַחֶרֶת קְדוֹשָׁה וְשׁוֹרָה בָעוֹלָם. זֶהוּ שֶׁכָּתוּב תְּשַׁלַּח רוּחֲךְ יִבָּרֵאוּן, יִבָּרֵאוּן וְיֵרָפְאוּ בִּרְפוּאָה עֶלְיוֹנָה שֶׁל רוּחַ אַחֶרֶת. וּתְחַדֵּשׁ פְּנֵי אֲדָמָה, שֶׁהֲרֵי נִטְהֲרָה (אשה לבעלה), וְחִדּוּשׁ הַלְּבָנָה נִמְצָא, וְכָל הָעוֹלָמוֹת מִתְבָּרְכִים. אַשְׁרֵי חֵלֶק יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם עֵצָה שֶׁכֻּלָּהּ רְפוּאָה כְּדֵי שֶׁיִּזְכּוּ לְחַיֵּי הָעוֹלָם הַבָּא, וְיִמָּצְאוּ טְהוֹרִים בָּעוֹלָם הַזֶּה, קְדוֹשִׁים לָעוֹלָם הַבָּא, עֲלֵיהֶם כָּתוּב (יחזקאל לו) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם."]]],[["(במדבר כ׳:א׳) וַיָבֹאוּ בְנֵי יִשְׂרָאֵל כָּל הָעֵדָה מִדְבַּר צִין וְגוֹ'. רִבִּי יְהוּדָה אָמַר, אֲמַאי פַּרְשְׁתָּא דְּפָרָה, סְמִיכָה לְמִיתַת מִרְיָם. הָא אוּקְמוּהָ. אֶלָּא כֵּיוָן (ס\"א כמה) דְּאִתְעָבִיד דִּינָא בְּהַאי פָּרָה, לְדַכְּאָה לְמִסְאֲבֵי, אִתְעָבִיד דִּינָא בְּמִרְיָם, לְדַכְּאָה עָלְמָא, וְאִסְתְּלָּקַת מִן עָלְמָא. כֵּיוָן דְּאִסְתַּלָּקַת מִרְיָם, אִסְתַּלָּק הַהוּא בְּאֵר, דְּהֲוָה אָזִיל עִמְּהוֹן דְּיִשְׂרָאֵל בְּמַדְבְּרָא וְאִסְתַּלָּק בֵּירָא בְּכֹלָּא.","אָמַר רִבִּי אַבָּא, כְּתִיב וְאַתָּה בֶּן אָדָם שָׂא קִינָא עַל בְּתוּלַת יִשְׂרָאֵל, וְכִי עָלָה בִּלְחוֹדָהָא, לָא. אֶלָּא בְּגִין דְּכֹלָּא אִתְּבַּר בְּגִינָהּ. בְּגִינָהּ אִתְּבַּר יְמִינָא אֲבַּתְרָהּ, דְּהֲוָה מְקָרֵב לָהּ גַּבֵּי גּוּפָא. וְגוּפָא דְּאִיהוּ שִׁמְשָׁא, אִתְחֲשָׁךְ בְּגִינָהּ. וְדָא הוּא רָזָא דִּכְתִּיב, (תהילים ס׳:ז׳) הוֹשִׁיעָה יְמִינְךָ וַעֲנֵנִי. גּוּפָא (ס\"א בגינה דכתיב, (ישעיהו י״ג:י׳) חשך השמש בצאתו וכתיב) דִּכְתִּיב, (ישעיהו נ׳:ג׳) אַלְבִּישׁ שָׁמַיִם קַדְרוּת, דְּהָא שִׁמְשָׁא אִתְחֲשָׁךְ בְּגִינָהּ. כְּגַוְונָא דָּא וַתָּמָת שָׁם מִרְיָם וְגוֹ'.","(במדבר כ׳:ב׳) וְלֹא הָיָה מַיִם לָעֵדָה, דְּהָא אִסְתַּלָּק בֵּירָא דְּעֵילָּא וְתַתָּא לְבָתַר אִתְּבַּר יְמִינָא, דִּכְתִּיב יֵאָסֵף אַהֲרֹן אֶל עַמָּיו. וּלְבָתַר אִתְחֲשָׁךְ שִׁמְשָׁא, דִּכְתִּיב, (דברים ל״ב:נ׳) וּמֻת בָּהָר וְגוֹ'. וְהֵאָסֵף אֶל עַמֶּךָ וְגוֹ'. הָא (תצוה קפ\"א ע\"א) דְּרוֹעָא יְמִינָא אִתְּבַּר, וְגוּפָא דְּאִיהוּ שִׁמְשָׁא אִתְחֲשָׁךְ.","וְתָּא חֲזֵי, לָא אִשְׁתְּכַח דָּרָא בְּעָלְמָא, כְּדָרָא דְּמֹשֶׁה קַיְּימָא בְּעָלְמָא, וְאַהֲרֹן וּמִרְיָם. וְאִי תֵּימָא בְּיוֹמוֹי דִּשְׁלֹמֹה הָכִי נַמֵּי, לָאו. דְּהָא בְּיוֹמוֹי דִּשְׁלֹמֹה שַׁלִּיט סִיהֲרָא, וְשִׁמְּשָׁא אִתְכְּנִישׁ. וּבְיוֹמוֹי דְּמֹשֶׁה, אִתְכְּנִישׁ סִיהֲרָא, וְשִׁמְּשָׁא שַׁלְטָא.","תְּלַת אַחִין הֲווֹ: מֹשֶׁה, אַהֲרֹן, וּמִרְיָם. כְּמָה דְאַתְּ אָמֵר (מיכה ו׳:ד׳) וָאֶשְׁלַח לְפָנֶיךָ אֶת מֹשֶׁה אַהֲרֹן וּמִרְיָם. מִרְיָם, סִיהֲרָא. מֹשֶׁה, שִׁמְשָׁא. אַהֲרֹן, דְּרוֹעָא יְמִינָא. (שמות ס\"ו ע\"א) חוּר, דְּרוֹעָא שְׂמָאלָא. וְאַמְרֵי לָהּ, נַחְשׁוֹן בֶּן עֲמִינָדָב. בְּקַדְמִיתָא מִיתַת מִרְיָם, אִסְתָּלָקַת סִיהֲרָא, אִסְתַּלָּק בְּאֵר. לְבָתַר אִתְּבַּר דְּרוֹעָא יְמִינָא, דִּמְקָרֵב תָּדִיר סִיהֲרָא, בְּאֲחְוָא, בְּחֵידוּ. וְעַל דָּא כְּתִיב, (שמות ט״ו:כ׳) וַתִּקַּח מִרְיָם הַנְּבִיאָה אֲחוֹת אַהֲרֹן. אֲחוֹת אַהֲרֹן וַדַּאי, דְּאִיהוּ דְּרוֹעָא, דִּמְקָרֵב לָהּ בְּאַחֲדוּתָא, בְּאֲחְוָה עִם גּוּפָא.","לְבָתַר אִתְכְּנִישׁ שִׁמְשָׁא וְאִתְחֲשָׁךְ, כְּמָה דְּאוֹקִימְנָא דִּכְתִּיב וְהֵאָסֵף אֶל עַמֶּךָ גַּם אַתָּה וְגוֹ'. זַכָּאָה חוּלָקֵיהוֹן דְּמֹשֶׁה אַהֲרֹן וּמִרְיָם, דְּאִשְׁתְּכָחוּ בְּעָלְמָא. בְּיוֹמוֹי דִּשְׁלֹמֹה, שַׁלְטָא סִיהֲרָא, בְּתִקּוּנָהָא, וְאִתְחַזֵּי בְּעָלְמָא. וְאִתְקְיָים שְׁלֹמֹה בְּחָכְמְתָא דִּנְהִירוּ דִּילָהּ, וְשָׁלִיט בְּעָלְמָא. כֵּיוָן דְּסִיהֲרָא נַחְתָּא בְּחוֹבוֹי, אִתְפְּגִים יוֹמָא בָּתַר יוֹמָא, עַד דְּאִשְׁתְּכַח בְּקֶרֶן מַעֲרָבִית, וְלָא יַתִּיר, וְאִתְיְהִיב שִׁבְטָא חַד לִבְרֵיהּ. זַכָּאָה חוּלָקָא דְּמֹשֶׁה נְבִיאָה מְהֵימָנָא.","כְּתִיב (קהלת א׳:ה׳) וְזָרַח הַשֶּׁמֶשׁ וּבָא הַשָּׁמֶשׁ וְגוֹ'. הַאי קְרָא אוֹקִימְנָא. אֲבָל וְזָרַח הַשֶּׁמֶשׁ, כַּד נַפְקוּ יִשְׂרָאֵל מִמִּצְרָיִם, דְּנָהִיר שִׁמְשָׁא וְלָא סִיהֲרָא. וְאֶל מְקוֹמוֹ שׁוֹאֵף וְגוֹ', הָא כְּתִיב וּבָא הַשֶּׁמֶשׁ, בְּמַדְבְּרָא, עִם שְׁאַר מֵתֵי מַדְבְּרָא. כֵּיוָן דְּעָאל שִׁמְשָׁא, לְאָן אֲתָר אִתְכְּנִישׁ. אֶל מְקוֹמוֹ, בְּגִין לְאַנְהָרָא לְסִיהֲרָא. הֲדָא הוּא דִכְתִיב שׁוֹאֵף זוֹרֵחַ הוּא שָׁם. דְּאַף עַל גַּב דְּאִתְכְּנִישׁ, זוֹרֵחַ הוּא שָׁם וַדַּאי. דְּהָא לָא אַנְהִיר סִיהֲרָא, אֶלָּא מִנְּהוֹרָא דְּשִׁמְשָׁא. וְדָא הוּא רָזָא דִּכְתִּיב, (דברים ל״א:ט״ז) הִנְּךָ שׁוֹכֵב עִם אֲבוֹתֶיךָ וְקָם. אַף עַל גַּב דְּתִּתְכָּנֵשׁ, הִנְּךָ קַיָּים לְאַנְהָרָא לְסִיהֲרָא. דָּא הוּא יְהוֹשֻׁעַ.","וְעָלֵיה כָּךְ הוּא מֹשֶׁה וְעָלֵיה כְּתִיב הַאי קְרָא, (קהלת א׳:ג׳) מַה יִּתְרוֹן לָאָדָם בְּכָל עֲמָלוֹ וְגוֹ'. מַה יִּתְרוֹן לָאָדָם בְּכָל עֲמָלוֹ, דָּא יְהוֹשֻׁעַ, דְּאִשְׁתְּדַל לְאַחְסְנָא אַרְעָא דְּיִשְׂרָאֵל, וְלָא זָכָה לְאַשְׁלְמָא לְסִיהֲרָא כַּדְּקָא יָאוּת, דְּהָא אִיהוּ אַעְמַל בְּהוּ בְּיִשְׂרָאֵל, תַּחַת הַשָּׁמֶשׁ תְּחוֹתֵיהּ דְּמֹשֶׁה. תָּא חֲזֵי, וַוי לְהַהוּא כִּסּוּפָא, וַוי לְהַהוּא כְּלִימָה, בְּגִין דְּפָלַח, וְלָא נָטַל אַתְרֵיהּ מַמָּשׁ, אֶלָּא תְּחוֹת שִׁמְשָׁא, וְלָא הֲוָה לֵיהּ נְהִירוּ מִדִילֵיהּ, אֶלָּא נְהִירוּ דְּנָהִיר לֵיהּ. וְאִי הָכִי, מַאי תּוּשְׁבַּחְתָּא הֲוָה לֵיהּ, הוֹאִיל וְלָא אַשְׁלִים לְהָכָא וּלְהָכָא.","וּבְכֹל אֲתָר דְּאָמַר שְׁלֹמֹה תַּחַת הַשָּׁמֶשׁ, עַל דַּרְגָּא דִּילֵיהּ קָאָמַר. (קהלת ה׳:י״ב) רָאִיתִי תַּחַת הַשָּׁמֶשׁ. (קהלת ג׳:ט״ז) וְעוֹד רָאִיתִי תַּחַת הַשָּׁמֶשׁ. (קהלת ט׳:י״א) שַׁבְתִּי וְרָאֹה תַּחַת הַשָּׁמֶשׁ. וְכֵן כֻּלְּהוּ. וּבְגִין דַּרְגָּא דִּילֵיהּ קָאָמַר. וְדָא הוּא רָזָא דְּמִלָּה וַדַּאי."],[[0,"ויבאו","וגו' \u0003מדבר צין וגו':\u0004 ר' יהודה אמר, למה פרשת פרה סמוכה למיתת מרים, וכבר העמידוהו. ומשיב, אלא כיון שנעשה דין בפרה זו כדי לטהר הטמאים, נעשה דין במרים, כדי לטהר את העולם, כי מיתת צדיקים מכפרים על העולם, ונסתלקה מן העולם. כיון שנסתלקה מרים, נסתלקה הבאר שהיתה הולכת עם ישראל במדבר. ונסתלקה באר של הכל. שה\"ס המלכות."],[1,"א\"ר אבא כתיב וכו':","אר\"א, כתוב, ואתה בן אדם שא קינה על בתולת ישראל. שהיא המלכות. שואל וכי עליה בלבד. ומשיב, לא. אלא משום שהכל נשבר בשבילה, כי בשבילה נשבר אחריה הימין של ז\"א, שה\"ס הסתלקות החסד מחמת פרוד המלכות, שהחסד היה מקרבה אל הגוף, שהוא ז\"א. והגוף, שהוא השמש, דהיינו ז\"א המשפיע למלכות, נחשך בשבילה, כי אין לו למי להשפיע. וזהו סוד שכתוב הושיעה ימינך וענני. דהיינו שיושיע את יד הימין, שנשבר מחמת פרוד המלכות, וכן הגוף, שכתוב, אלביש שמים קדרות, כי השמש שהוא ז\"א, נחשך בשבילה. כעין זה ותמת שם מרים. שזה יורה הסתלקות המלכות. ונעשה ג\"כ כנ\"ל, שנחלש הימין ונחשך ז\"א."],[2,"ולא היה מים לעדה:","כי נסתלק הבאר של מעלה, שהיא מלכות ושלמטה, שהיא מרים. ואח\"כ נשבר הימין, שכתוב, יאסף אהרן אל עמיו, שה\"ס החסד שהוא ימין. ואח\"כ נחשך השמש, שכתוב ומות בהר וגו', והאסף אל עמך וגו', ומשה היה מרכבה לז\"א הנקרא שמש. הרי שזרוע הימין נשבר, והגוף, שהוא השמש, נחשך."],[3,"ות\"ח לא אשתכח וכו':","בוא וראה לא נמצא דור בעולם כמו הדור שמשה חי בעולם, ואהרן ומרים. ואם תאמר, בימי שלמה היה ג\"כ כזה, לא. כי בימי שלמה היה שולט הלבנה, כי אותו הדור היה מקבל מלבנה, שהיא המלכות. והשמש היה נאסף, שלא היו מקבלים מז\"א, שנקרא שמש. ובימיו של משה, היתה נאספת הלבנה, שלא היו מקבלים מן המלכות, והשמש שלט. שהיו מקבלים מז\"א, שנקרא שמש."],[3,"","פירוש, כמו שהשמש והלבנה אינם שולטים בזמן אחד, כי ביום לא תראה הלבנה, ובלילה לא יראה השמש. ועל כן גם בעת שז\"א ומלכות שה\"ס שמש ולבנה, הם מחוברים, מ\"מ יש הפרש בשליטתם, וכששולט ז\"א אינה ניכרת שליטת הנוקבא, וכששולטת הנוקבא אינו ניכר שליטת ז\"א, וע\"כ כיון שמשה היה בחינת ז\"א, בני דורו היו מקבלים מז\"א. ושלמה היה בחינת הלבנה שהיא המלכות, היו בני דורו מקבלים מן הלבנה. אמנם ודאי, שהן בזה והן בזה, היה זווג ז\"א ומלכות, אלא המדובר היא רק בשליטה."],[4,"תלת אחין הוו וכו':","ג' אחים היו משה אהרן ומרים, כש\"א, ואשלח לפניך את משה אהרן ומרים. \u0003מרים\u0004 היא הלבנה, מלכות, \u0003משה\u0004 הוא שמש, ז\"א, \u0003אהרן\u0004 הוא זרוע הימין. חסד. \u0003חור\u0004 זרוע שמאל, גבורה. ויש אומרים, נחשון בן עמינדב, היה זרוע שמאל. בתחילה מתה מרים, ונסתלקה הלבנה, ונסתלקה הבאר. אח\"כ נשבר זרוע הימין המקרב תמיד את הלבנה, שהיא המלכות, באחוה בשמחה. וע\"כ כתוב, ותקח מרים הנביאה אחות אהרן, אחות אהרן ודאי, שהוא הזרוע המקרבה באחדות באחוה עם הגוף, שהוא ז\"א."],[5,"לבתר אתכניש שמשא וכו':","אח\"כ נאסף השמש ונחשך, כמו שהעמדנו, שכתוב, והאסף אל עמך גם אתה וגו'. אשרי הדור שמשה אהרן ומרים נמצאו בעולם. בימיו של שלמה שלטה הלבנה שהיא המלכות, בתקוניה, במילואה, ונראית בעולם, ונתקיים שלמה בחכמה של האור שלה, כי גילוי אור החכמה הוא רק במלכות (כנ\"ל ב\"א דף רע\"ו ד\"ה ועוד כמה) ושלט בעולם. כיון שהלבנה ירדה בעונותיו, נפגמה יום אחר יום, עד שהיתה נמצאת בקרן מערבית, שהוא מקומה של המלכות עצמה, ולא יותר ואז ניתן רק שבט אחד לבנו של שלמה. והשאר לירבעם. אשרי חלקו של משה נביא הנאמן."],[6,"כתיב וזרח השמש וגו':","כתוב, וזרח השמש ובא השמש וגו'. מקרא זה העמדנו. אבל \u0003וזרח השמש,\u0004 היינו כשיצאו ישראל ממצרים שהשמש האיר, שהוא משה, ולא הלבנה, שהיא מלכות. \u0003ואל מקומו שואף\u0004 וגו'. כי כתוב, \u0003ובא השמש,\u0004 כי משה נאסף במדבר, עם שאר מתי המדבר. כיון שבא השמש, לאיזה מקום נאסף. \u0003אל מקומו,\u0004 דהיינו כדי להאיר אל הלבנה. ז\"ש, \u0003שואף זורח הוא שם,\u0004 שאע\"פ שנאסף, \u0003זורח הוא שם\u0004 ודאי, כי אין הלבנה מאירה אלא מאור השמש. וזהו סוד שכתוב, הנך שוכב עם אבותיך וקם. אע\"פ שתאסף הנך \u0003קם\u0004 להאיר אל הלבנה. שזה הוא יהושע, כי יהושע היה מרכבה אל המלכות."],[7,"ועליה כתיב האי וכו':","ועליו על יהושע כתוב מקרא הזה, מה יתרון לאדם בכל עמלו וגו'. \u0003מה יתרון לאדם בכל עמלו,\u0004 זה יהושע, שהשתדל להנחיל את ארץ ישראל, שהיא המלכות, ולא זכה להשלים את הלבנה, שהיא המלכות, כראוי, כי הוא עמל בישראל תחת השמש, דהיינו תחת משה, שהוא סוד ז\"א הנקרא שמש. בוא וראה, אוי לאותה בושה, אוי לאותה כלימה, כיון שעבד תחת משה ולא לקח מקומו ממש שהוא שמש, אלא תחת השמש, שלא היה לו אור משלו, אלא מאורו של השמש שהאיר לו. אם כן איזה שבח היה לו, כיון שלא השלים לכאן ולכאן. לשמש ולבנה, דכיון שלא השלים עצמו במדרגת השמש, ע\"כ לא היה יכול להשלים את הלבנה."],[8,"ובכל אתר דאמר וכו':","ובכל מקום שאמר שלמה, \u0003תחת השמש,\u0004 על מדרגת עצמו אומר, שהיא מלכות, דהיינו, ראיתי תחת השמש. ועוד ראיתי תחת השמש, שבתי וראה תחת השמש. וכן כלהו. שמשום מדרגת עצמו אמר. וזה הוא סוד הדבר ודאי."]],[[0,"","וַיָּבֹאוּ בְנֵי יִשְׂרָאֵל כָּל הָעֵדָה מִדְבַּר צִין וְגוֹ'. רַבִּי יְהוּדָה אָמַר, לָמָּה פָּרָשַׁת פָּרָה סְמוּכָה לְמִיתַת מִרְיָם, הֲרֵי פֵּרְשׁוּהָ. אֶלָּא כֵּיוָן (כמו) שֶׁנַּעֲשָׂה הַדִּין בְּפָרָה זוֹ לְטַהֵר הַטְּמֵאִים, נַעֲשָׂה דִין בְּמִרְיָם לְטַהֵר הָעוֹלָם, וְהִסְתַּלְּקָה מֵהָעוֹלָם. כֵּיוָן שֶׁהִסְתַּלְּקָה מִרְיָם, הִסְתַּלְּקָה אוֹתָהּ בְּאֵר שֶׁהָיְתָה הוֹלֶכֶת עִם יִשְׂרָאֵל בַּמִּדְבָּר, וְהִסְתַּלְּקָה הַבְּאֵר בַּכֹּל."],[1,"","אָמַר רַבִּי אַבָּא, כָּתוּב וְאַתָּה בֶּן אָדָם שָׂא קִינָה עַל בְּתוּלַת יִשְׂרָאֵל. וְכִי עָלֶיהָ לְבַדָּהּ? לֹא. אֶלָּא מִשּׁוּם שֶׁהַכֹּל נִשְׁבַּר בִּגְלָלָהּ. בִּגְלָלָהּ נִשְׁבַּר הַיָּמִין אַחֲרֶיהָ, שֶׁהָיָה מְקָרְבָהּ לַגּוּף. וְהַגּוּף, שֶׁהוּא שֶׁמֶשׁ, נֶחְשַׁךְ בִּגְלָלָהּ, וְזֶהוּ שֶׁכָּתוּב (תהלים ס) הוֹשִׁיעָה יְמִינְךְ וַעֲנֵנִי. גּוּף, (בגללה, שכתוב (ישעיה יג) חשך השמשבצאתו, וכתוב) שֶׁכָּתוּב (ישעיה נ) אַלְבִּישׁ שָׁמַיִם קַדְרוּת, שֶׁהֲרֵי הַשֶּׁמֶשׁ נֶחְשַׁךְ בִּגְלָלָהּ. כְּמוֹ זֶה, וַתָּמָת שָׁם מִרְיָם וְגוֹ'."],[2,"","וְלֹא הָיָה מַיִם לָעֵדָה, שֶׁהֲרֵי הִסְתַּלְּקָה הַבְּאֵר שֶׁלְּמַעְלָה וְשֶׁלְּמַטָּה, אַחַר כָּךְ נִשְׁבַּר הַיָּמִין, שֶׁכָּתוּב יֵאָסֵף אַהֲרֹן אֶל עַמָּיו. וְאַחַר כָּךְ נֶחְשַׁךְ הַשֶּׁמֶשׁ, שֶׁכָּתוּב (דברים לב) וּמֻת בָּהָר וְגוֹ', וְהֵאָסֵף אֶל עַמֶּיךְ וְגוֹ'. הֲרֵי זְרוֹעַ יָמִין נִשְׁבְּרָה, וְהַגּוּף, שֶׁהוּא שֶׁמֶשׁ, נֶחְשַׁךְ."],[3,"","וּבֹא וּרְאֵה, לֹא נִמְצָא דוֹר בָּעוֹלָם כְּמוֹ הַדּוֹר שֶׁעָמַד מֹשֶׁה בָּעוֹלָם, וְאַהֲרֹן וּמִרְיָם. וְאִם תֹּאמַר בִּימֵי שְׁלֹמֹה גַּם כָּךְ - לֹא! שֶׁהֲרֵי בִּימֵי שְׁלֹמֹה שָׁלְטָה הַלְּבָנָה, וְהַשֶּׁמֶשׁ הִתְכַּנְּסָה. וּבִימֵי מֹשֶׁה הִתְכַּנְּסָה הַלְּבָנָה וְשָׁלַט הַשֶּׁמֶשׁ."],[4,"","שְׁלֹשָה אַחִים הָיוּ: מֹשֶׁה, אַהֲרֹן וּמִרְיָם, כְּמוֹ שֶׁנֶּאֱמַר (מיכה ו) וָאֶשְׁלַח לְפָנֶיךְ אֶת מֹשֶׁה אַהֲרֹן וּמִרְיָם. מִרְיָם - לְבָנָה. מֹשֶׁה - שֶׁמֶשׁ. אַהֲרֹן - זְרוֹעַ יָמִין. חוּר - זְרוֹעַ שְׂמֹאל. וְיֵשׁ אוֹמְרִים נַחְשׁוֹן בֶּן עַמִּינָדָב. בַּהַתְחָלָה מֵתָה מִרְיָם - הִסְתַּלְּקָה הַלְּבָנָה וְהִסְתַּלְּקָה הַבְּאֵר. אַחַר כָּךְ נִשְׁבְּרָה זְרוֹעַ יָמִין שֶׁמְּקָרֶבֶת תָּמִיד אֶת הַלְּבָנָה בְּאַחֲוָה וּבְשִׂמְחָה, וְעַל זֶה כָּתוּב (שמות טו) וַתִּקַּח מִרְיָם הַנְּבִיאָה אֲחוֹת אַהֲרֹן. אֲחוֹת אַהֲרֹן בְּוַדַּאי, שֶׁהִיא זְרוֹעַ שֶׁמְּקָרְבָהּ בְּאַחְדוּת וּבְאַחֲוָה עִם הַגּוּף."],[5,"","אַחַר כָּךְ הִתְכַּנֵּס הַשֶּׁמֶשׁ וְנֶחְשַׁךְ, כְּמוֹ שֶׁאָמַרְנוּ שֶׁכָּתוּב (במדבר כז) וְנֶאֱסַפְתָּ (והאסף) אֶל עַמֶּיךְ גַּם אָתָּה וְגוֹ'. אַשְׁרֵי חֶלְקָם שֶׁל מֹשֶׁה, אַהֲרֹן וּמִרְיָם שֶׁנִּמְצְאוּ בָעוֹלָם. בִּימֵי שְׁלֹמֹה שָׁלְטָה הַלְּבָנָה בְתִקּוּנֶיהָ וְנִרְאֲתָה בָעוֹלָם, וְהִתְקַיֵּם שְׁלֹמֹה בְּחָכְמַת הָאוֹר שֶׁלָּהּ וְשָׁלַט בָּעוֹלָם. כֵּיוָן שֶׁהַלְּבָנָה יָרְדָה בַּעֲונוֹתָיו, נִפְגַּם יוֹם אַחַר יוֹם, עַד שֶׁנִּמְצָא בְקֶרֶן מַעֲרָבִית וְלֹא יוֹתֵר, וְנִתַּן שֵׁבֶט אֶחָד לִבְנוֹ. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה נָבִיא הַנֶּאֱמָן."],[6,"","כָּתוּב (קהלת א) וְזָרַח הַשֶּׁמֶשׁ וּבָא הַשָּׁמֶשׁ וְגוֹ'. פָּסוּק זֶה בֵּאַרְנוּ. אֲבָל וְזָרַח הַשֶּׁמֶשׁ, כְּשֶׁיָּצְאוּ יִשְׂרָאֵל מִמִּצְרַיִם, שֶׁהֵאִיר הַשֶּׁמֶשׁ וְלֹא הַלְּבָנָה. וְאֶל מְקוֹמוֹ שׁוֹאֵף וְגוֹ'. הֲרֵי כָּתוּב וּבָא הַשָּׁמֶשׁ, בַּמִּדְבָּר, עִם שְׁאָר מֵתֵי מִדְבָּר. כֵּיוָן שֶׁנִּכְנַס הַשֶּׁמֶשׁ, לְאֵיזֶה מָקוֹם הִתְכַּנֵּס? אֶל מְקוֹמוֹ, בִּשְׁבִיל לְהָאִיר לַלְּבָנָה. זֶהוּ שֶׁכָּתוּב שׁוֹאֵף זוֹרֵחַ הוּא שָׁם. שֶׁאַף עַל גַּב שֶׁהִתְכַּנֵּס, זוֹרֵחַ הוּא שָׁם וַדַּאי. שֶׁהֲרֵי לֹא מוּאֶרֶת הַלְּבָנָה אֶלָּא מֵאוֹר הַשֶּׁמֶשׁ. וְזֶהוּ סוֹד הַכָּתוּב (דברים לא) הִנְּךְ שֹׁכֵב עִם אֲבֹתֶיךְ וְקָם. אַף עַל גַּב שֶׁתִּתְכַּנֵּס, הִנְּךְ קַיָּם לְהָאִיר לַלְּבָנָה (ועליה זה הוא יהושע)."],[7,"","כָּךָ הוּא מֹשֶׁה, וְעָלָיו כָּתוּב פָּסוּק זֶה, מַה יִּתְרוֹן לָאָדָם בְּכָל עֲמָלוֹ וְגוֹ'. מַה יִּתְרוֹן לָאָדָם בְּכָל עֲמָלוֹ - זֶה יְהוֹשֻׁעַ שֶׁהִשְׁתַּדֵּל לְהוֹרִישׁ אֶרֶץ יִשְׂרָאֵל, וְלֹא זָכָה לְהַשְׁלִים לַלְּבָנָה כָּרָאוּי, שֶׁהֲרֵי הוּא עָמַל בְּיִשְׂרָאֵל תַּחַת הַשָּׁמֶשׁ, תַּחַת מֹשֶׁה. בּא וּרְאֵה, אוֹי לְאוֹתָהּ בּוּשָׁה, אוֹי לְאוֹתָהּ כְּלִמָּה, מִשּׁוּם שֶׁעָבַד וְלֹא לָקַח מְקוֹמוֹ מַמָּשׁ, אֶלָּא תַּחַת הַשֶּׁמֶשׁ, וְלֹא הָיָה לוֹ אוֹר מִשֶּׁלּוֹ, אֶלָּא אוֹר שֶׁהֵאִיר לוֹ. וְאִם כָּךְ מַהוּ שִׁבְחוֹ, הוֹאִיל וְלֹא הִשְׁלִים לְכָאן וּלְכָאן?"],[8,"","וּבְכָל מָקוֹם שֶׁאָמַר שְׁלֹמֹה תַּחַת הַשָּׁמֶשׁ, עַל דַּרְגָּתוֹ אָמַר. (קהלת ה) רָאִיתִי תַּחַת הַשָּׁמֶשׁ. (שם ג) וְעוֹד רָאִיתִי תַּחַת הַשָּׁמֶשׁ. (שם ט) שַׁבְתִּי וְרָאֹה תַחַת הַשֶּׁמֶשׁ. וְכֵן כֻּלָּם. וּמִשּׁוּם דַּרְגָּתוֹ אָמַר, וְזֶהוּ סוֹד הַדָּבָר בְּוַדַּאי."]]],[["רַבִּי שִׁמְעוֹן אָמַר, וַדַּאי מַאן דְּנָטִיל סָמָא דְּמוֹתָא בִּלְחוֹדוֹי, עָלֵיהּ כְּתִיב בְּכָל עֲמָלוֹ שֶׁיַּעֲמוֹל תַּחַת הַשָּׁמֶשׁ וַדַּאי. וּמַאן הוּא תַּחַת הַשָּׁמֶשׁ. הֲוִי אֵימָא דָּא סִיהֲרָא. וּמַאן דְּאָחִיד סִיהֲרָא בְּלָא שִׁמְשָׁא, עֲמָלוֹ תַּחַת הַשָּׁמֶשׁ וַדַּאי. וְדָא הוּא חוֹבָא קַדְמָאָה דְּעָלְמָא. וְעַל דָּא מַה יִּתְרוֹן לָאָדָם בְּכָל עֲמָלוֹ, לָאָדָם קַדְמָאָה, וְכֵן לְכֻלְּהוּ דְּאַתְיָין בַּתְרֵיהּ, דְּחָבוּ בַּאֲתָר דָּא.","הוֹלֵךְ אֶל דָּרוֹם וְסוֹבֵב אֶל צָפוֹן, הַיְינוּ דִּכְתִּיב, (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ. יְמִינוֹ, זֶה דָּרוֹם. אֵשׁ דָּת, דָּא צָפוֹן. וְדָא כָּלִיל בְּדָא.","סוֹבֵב סוֹבֵב הוֹלֵךְ הָרוּחַ, הַאי קְרָא קַשְׁיָא, סוֹבֵב סוֹבֵב הוֹלֵךְ הַשֶּׁמֶשׁ מִבָּעֵי לֵיהּ, מַאי הוֹלֵךְ הָרוּחַ. מַאן רוּחָא דָּא, דָּא הוּא תַּחַת הַשֶּׁמֶשׁ, דְּאִקְרֵי רוּחַ הַקֹּדֶשׁ. וְדָא (הוא) רוּחַ הוֹלֵךְ וְסוֹבֵב לְאִלֵּין תְּרֵין סִטְרִין לְאִתְחַבְּרָא בְּגוּפָא. וְעַל דָּא כְּתִיב הָרוּחַ, הַהוּא דְּאִשְׁתְּמוֹדַע הַשֶּׁמֶשׁ סְתָם, דְּאִשְׁתְּמוֹדַע (ס\"א לאתחברא בגופא דאיהו שמשא ההוא דאשתמודע) חוּלָקָא דְּיִשְׂרָאֵל.","וְעַל סְבִיבוֹתָיו שָׁב הָרוּחַ, מַאן סְבִיבוֹתָיו. אִלֵּין אֲבָהָן, דְּאִינּוּן רְתִיכָא קַדִּישָׁא, וְאִינּוּן תְּלַת, וְדָוִד וְד' רוּחֵי דְּאִתְחַבְּרָן בְּהוּ (ס\"י ודא רוחא דאתחברא בהו) (ס\"א ודוד דא הוא רוחא רביעאה, דאתחבר בהו) הָא אִינּוּן רְתִיכָא קַדִּישָׁא שְׁלֵימָתָא, וְעַל דָּא כְּתִיב, (תהילים קי״ח:כ״ב) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה.","בְּגִין דְּכָל מִלּוֹי דִּשְׁלֹמֹה מַלְכָּא סְתִימִין כֻּלְּהוּ בְּחָכְמְתָא, וְכֻלְּהוּ לְגוֹ בְּגוֹ דְּהֵיכָלָא קַדִּישָׁא, וּבְנֵי נָשָׁא לָא מִסְתַּכְּלֵי בְּהוּ, וְחָמָאן מִלּוֹי כְּמִלִּין דְּבַּר נָשׁ אַחֲרָא. אִי הָכִי, מַה שְׁבָחָא הוּא לִשְׁלֹמֹה מַלְכָּא בְּחָכְמָתֵיהּ, מִשְּׁאַר בְּנֵי נָשָׁא. אֶלָּא וַדַּאי כָּל מִלָּה וּמִלָּה דִּשְׁלֹמֹה מַלְכָּא סָתִים בְּחָכְמְתָא.","פָּתַח וְאָמַר, (קהלת ז׳:י״א) טוֹבָה חָכְמָה עִם נַחֲלָה וְיוֹתֵר לְרוֹאֵי הַשָּׁמֶשׁ, אִי לָאו דְּהָא אִתְגַּלְיָיא מִלָּה דָּא, לָא (שמענא ולא) יְדַעְנָא מַאי קָאָמַר. טוֹבָה חָכְמָה, דָּא הִיא חָכְמָה, דְּהִיא תַּחַת הַשָּׁמֶשׁ, (ס\"א לכורסייא) כּוּרְסְיָיא מִתְתַּקְנָא לֵיהּ. טוֹבָה חָכְמָה עִם נַחֲלָה, יָאָה וְשַׁפִּירָא כַּד אִיהִי שַׁרְיָיא עִמְּהוֹן דְּיִשְׂרָאֵל, דְּאִינּוּן נַחֲלָה וְעַדְבָא דִּילָהּ, לְאִתְקַשְּׁרָא בָּהּ.","אֲבָל תּוּשְׁבַּחְתָּא יַתִּיר לְרוֹאֵי הַשָּׁמֶשׁ, לְאִינּוּן דְּזָכוּ לְאִתְחַבְּרָא בְּשִׁמְשָׁא, וּלְאִתְקַשְּׁרָא בֵּיהּ, דְּהָא אָחִיד בְּאִילָנָא דְּחַיֵּי, וּמַאן דְּאָחִיד בֵּיהּ, בְּכֹלָּא אָחִיד, בַּחַיִּין דְּהַאי עָלְמָא, וּבְחַיֵּי דְּעָלְמָא דְּאָתֵי, וְדָא הוּא דִּכְתִּיב, (קהלת ז׳:י״ב) וְיִתְרוֹן דַּעַת הַחָכְמָה תְּחַיֶּה בְעָלֶיהָ. מַאי וְיִתְרוֹן דַּעַת. דָּא אִילָנָא דְּחַיֵּי. יִּתְרוֹן דִּילֵיהּ מַהוּ, הַחָכְמָה וַדַּאי, דְּהָא תּוֹרָה, (שמות ס\"ב ע\"א) מֵחָכְמָה עִלָּאָה נָפְקָא.","תּוּ טוֹבָה חָכְמָה עִם נַחֲלָה, טוֹבָה חָכְמָה, וַדַּאי עִם נַחֲלָה, דָּא צַדִּיקָא דְּעָלְמָא, דְּאִיהוּ נְהוֹרָא דְּשִׁמְשָׁא, דְּהָא תְּרֵין דַּרְגִּין אִלֵּין כַּחֲדָא יַתְבֵי, וְדָא הוּא שְׁפִּירוּ דִּלְהוֹן, אֲבָל וְיוֹתֵר לְרוֹאֵי הַשָּׁמֶשׁ, לְאִינּוּן דְּמִתְאַחֲדִין בְּשִׁמְשָׁא, תּוּקְפָּא דְּכֹלָּא, שְׁבָחָא דְּכֹלָּא.","וְדָא הוּא דַּעַת, אִילָנָא דְּחַיֵּיא, וְהָא אוּקְמוּהָ (משלי י״ט:ב׳) גַּם בְּלֹא דַעַת נֶפֶשׁ לֹא טוֹב. מַאן נֶפֶשׁ. דָּא נֶפֶשׁ טוֹב דְּדָוִד מַלְכָּא. וְדָא חָכְמָה דְּקָאַמְרָן. וּבְגִינֵי כַּךְ יִּתְרוֹן דַּעַת הַחָכְמָה, דְּמִתַּמָּן אִשְׁתָּרְשָׁא אִילָנָא וְאִתְנְטָע לְכָל סִטְרִין, וְכֵן לְכָל אִינּוּן דַּאֲחִידָן בֵּיהּ בְּהַאי אִילָנָא, וְעַל דָּא שְׁלֹמֹה מַלְכָּא לָא אִשְׁתְּכַח אֶלָּא בְּהַהוּא דַּרְגָּא דִּילֵיהּ, וּמִתַּמָּן יָדַע כֹּלָּא, וַהֲוָה אָמַר עוֹד רָאִיתִי תַּחַת הַשָּׁמֶשׁ, וְשַׁבְתִּי וְרָאִיתִי וְגוֹ'. וְכֵן כֻּלְּהוּ. זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, וְיַדְעִין אוֹרְחוֹי דְּמַלְכָּא קַדִּישָׁא, וּסְתִימִין עִלָּאִין דִּגְנִיזִין בְּאוֹרַיְיתָא, דִּכְתִּיב, (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי יְיָ וְגוֹ'. (חסר)","(במדבר כ׳:כ״ד) יֵאָסֵף אַהֲרֹן אֶל עַמָּיו וְגוֹ'. רִבִּי חִיָּיא פָּתַח, (קהלת ד׳:ב׳) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ וְגו'. הַאי קְרָא אִתְּמַר וְאוּקְמוּהָ. תָּא חֲזֵי, כָּל עוֹבָדוֹי דְקוּדְשָׁא בְּרִיךְ הוּא, בְּדִינָא וּקְשׁוֹט, וְלֵית מַאן דְּאַקְשֵׁי לָקֳבְלֵיהּ, וְיִמְחֵי בִּידֵיהּ, וְיֵימַר לֵיהּ מַה עַבְדַת, וְכִרְעוּתֵיהּ עָבֵד בְּכֹלָּא."],[[0,"רש\"א ודאי מאן וכו':","ר' שמעון אומר הוא חולק על הנ\"ל, ודאי מי שלוקח סם המות בלבדו, דהיינו מלכות בלבד בלי ז\"א, עליו כתוב, בכל עמלו שיעמול \u0003תחת השמש,\u0004 ודאי. ומי הוא תחת השמש. הוי אומר, זו הלבנה, שהיא מלכות. ומי שאחוז בלבנה בלי השמש, נמצא עמלו ודאי \u0003תחת השמש.\u0004 וזה הוא חטא הראשון שבעולם, דהיינו חטא עץ הדעת, שהמשיך אור החכמה שבמלכות ממעלה למטה, שבזה הפרידה מז\"א בעלה, ולקח המלכות לבדה ועל זה אוה\"כ, מה יתרון \u0003לאדם\u0004 בכל עמלו, שהוא נאמר על אדם הראשון, וכן לכולם הבאים אחריו, החוטאים במקום הזה."],[1,"הולך אל דרום וסובב אל צפון:","היינו שכתוב, מימינו אש דת למו. \u0003ימינו\u0004 זה דרום, חסד. \u0003אש דת,\u0004 זה צפון גבורה, וזה כלול בזה. וע\"כ כתוב הולך אל דרום וסובב אל צפון."],[2,"סובב סובב הולך הרוח:","מקרא זה קשה, סובב סובב הולך השמש היה צריך לומר, מהו הולך הרוח. ומשיב, מי הוא רוח הזה, הוא \u0003תחת השמש,\u0004 הנקרא רוח הקדש, דהיינו מלכות. ורוח הזה, מלכות, הולך וסובב לאלו ב' צדדים דרום וצפון, שהם קו ימין וקו שמאל, להתחבר בגוף, שהוא ז\"א, הנקרא שמש. וע\"כ כתוב \u0003הרוח\u0004 עם ה' הידיעה, יורה אותו הנודע. שהוא חלק ישראל, דהיינו המלכות שהיא חלקו של ז\"א הנקרא ישראל. וכן ישראל של מטה מונין ללבנה, שהיא חלקם. אלא שהיא ביחד עם ז\"א."],[3,"ועל סביבותיו שב הרוח:","שואל, מהו סביבותיו. ומשיב, אלו הם האבות, שהם המרכבה הקדושה, והם שלשה, ודוד הוא רוח, שהוא הרביעי שנתחבר בהם. הרי הם מרכבה קדושה שלמה. ועל זה על דוד שעלה ונכלל במרכבה עליונה, כתוב, אבן מאסו הבונים היתה לראש פנה."],[3,"","פירוש. הרוח הוא מלכות כנ\"ל בדבור הסמוך, וכשהרוח הזה עולה לחג\"ת דז\"א ונתחבר עמהם להיות ד' רגלין למרכבה עליונה, אל הבינה, נאמר עליו ועל סביבותיו שב הרוח. וז\"ש \u0003מאן סביבותיו, אלין אבהן, דאינון רתיכא קדישא, ואינון תלת,\u0004 דהיינו חג\"ת הנקראים אבות, והם ג' רגלי הכסא. ועליהם אוה\"כ \u0003סביבותיו,\u0004 שהרוח, שב, ומתחבר עמהם להיות רגל רביעי, וז\"ש, \u0003ודוד דא הוא רוחא,\u0004 דוד שה\"ס מלכות הוא \u0003הרוח\u0004 שבכתוב, \u0003רביעאה דאתחבר בהון,\u0004 שהוא רגל רביעי אל המרכבה. שנתחבר בחג\"ת הנקראים סביבותיו. וז\"ש ועל סביבותיו שב הרוח."],[4,"בגין דכל מלוי וכו':","כי כל דבריו של שלמה המלך סתומים כולם בחכמה, וכולם נאמרים לפני ולפנים בהיכל הקדש. ובני אדם אינם מסתכלים בהם, ורואים דבריו כדברי אדם אחר. ואם כן מהו השבח לשלמה המלך בחכמתו יותר משאר בני אדם. אלא ודאי כל דבר ודבר של שלמה המלך סתום בחכמה."],[5,"פתח ואמר טובה וגו':","פו\"א, טובה חכמה עם נחלה ויותר לרואי השמש. אם לא שנתגלה לי דבר זה, לא הייתי יודע מה שאומר. \u0003טובה חכמה,\u0004 היינו חכמה שהוא תחת השמש שהיא כסא מתתקנת לשמש שהוא ז\"א, שהיא חכמה שבמלכות, דהיינו חכמה תתאה, הנקראת תחת השמש, ונקראת כסא. \u0003טובה חכמה עם נחלה,\u0004 פירושו, שנאה ויפה כשהחכמה, שהיא המלכות, שורה עם ישראל להתקשר בה. שהם \u0003נחלה\u0004 וגורל של המלכות."],[6,"אבל תושבחתא יתיר וכו':","אבל \u0003יותר\u0004 שבח הוא \u0003לרואי השמש,\u0004 כי הם זכו להתחבר בשמש, שהוא ז\"א, ולהתקשר בו. שהרי אחוז בעץ החיים, ומי שאחוז בעץ החיים הוא אחוז בכל, אחוז בחיי עולם הזה, שהוא מלכות, ובחיי עולם הבא, שהוא בינה, כי ז\"א אחוז במלכות ובבינה. וז\"ש, \u0003ויתרון דעת החכמה תחיה בעליה.\u0004 מהו ויתרון דעת, זהו עץ החיים, שה\"ס דעת וז\"א, היתרון שלו מהו. ודאי הוא \u0003החכמה,\u0004 כי התורה שהוא ז\"א, ודאי יצאה מחכמה עליונה. שהיא או\"א."],[7,"תו טובה חכמה וגו':","עוד פירוש, על טובה חכמה עם נחלה. \u0003טובה חכמה\u0004 שהיא חכמה תתאה, ודאי \u0003עם נחלה,\u0004 שהוא צדיק העולם, דהיינו יסוד דז\"א, שהוא אור השמש, שהיסוד דז\"א הוא אור הז\"א שנקרא שמש. כי שתי מדרגות אלו, יסוד ומלכות, יושבות ביחד, תהו היופי שלהן, אבל, \u0003ויותר לרואי השמש,\u0004 דהיינו לאלו המתאחדים עם השמש עצמו, שהוא ז\"א, שהוא התוקף של כולם, והשבח של כולם."],[8,"ודא הוא דעת וכו':","וזה, השמש, הוא דעת דז\"א, שהיא עץ החיים, והרי העמידוהו, גם בלא דעת נפש לא טוב, מי הוא הנפש. זו היא נפש טוב של דוד המלך, שהוא מלכות. וזו היא החכמה שאמרנו, שבעת שהנפש שהיא המלכות מחוברת עם דעת דז\"א, אז נקראת חכמה תתאה. ומשום זה, \u0003יתרון דעת החכמה,\u0004 כי משם, מן הדעת, נשרש האילן, שהוא המלכות, ונטע לכל הצדדים לימין ולשמאל, וכן לכל אלו הנאחזים באילן הזה. וע\"כ שלמה המלך לא נמצא אלא במדרגתו, שהיא מלכות, ומשם ידע הכל, והיה אומר, עוד ראיתי תחת השמש. שהוא מלכות הנקראת תחת השמש (כנ\"ל אות מ\"ג) וכן ושבתי וראיתי וגו'. וכן כולם. אשרי הם הצדיקים העוסקים בתורה ויודעים דרכיו של המלך הקדוש, וסתומים עליונים הגנוזים בתורה. שכתוב כי ישרים דרכי ה'."],[9,"יאסף אהרן אל עמיו וגו':","רבי חייא פתח ושבח אני את המתים שכבר מתו וגו' מקרא זה למדנו והעמידוהו. בוא וראה, כל מעשיו של הקב\"ה הם בדין ובאמת, ואין מי שיקשה כנגדו קושיות, וימחה בידו, ויאמר לו מה אתה עושה. וכרצונו עשה הכל."]],[[0,"","רַבִּי שִׁמְעוֹן אָמַר, וַדַּאי מִי שֶׁנּוֹטֵל סַם הַמָּוֶת לְבַדּוֹ, עָלָיו כָּתוּב (שם א) בְּכָל עֲמָלוֹ שֶׁיַּעֲמֹל תַּחַת הַשָּׁמֶשׁ וַדַּאי. וּמִי הוּא תַּחַת הַשָּׁמֶשׁ? הֱוֵי אוֹמֵר זוֹ הַלְּבָנָה. וּמִי שֶׁאוֹחֵז הַלְּבָנָה בְּלִי הַשֶּׁמֶשׁ, עֲמָלוֹ תַּחַת הַשָּׁמֶשׁ וַדַּאי. וְזֶהוּ הַחֵטְא הַקַּדְמוֹן שֶׁל הָעוֹלָם. וְעַל זֶה מַה יִּתְרוֹן לָאָדָם בְּכָל עֲמָלוֹ, לְאָדָם הָרִאשׁוֹן, וְכֵן לְכָל מִי שֶׁבָּא אַחֲרָיו שֶׁחָטְאוּ בְּמָקוֹם זֶה."],[1,"","הוֹלֵךָ אֶל דָּרוֹם וְסוֹבֵב אֶל צָפוֹן, הַיְנוּ שֶׁכָּתוּב (דברים לג) מִימִינוֹ אֵשׁ דָּת לָמוֹ. יְמִינוֹ - זֶה דָרוֹם. אֵשׁ דָּת - זֶה צָפוֹן. וְזֶה כָּלוּל בָּזֶה."],[2,"","סוֹבֵב סבֵב הוֹלֵךְ הָרוּחַ. פָּסוּק זֶה קָשֶׁה. סוֹבֵב סוֹבֵב הַשֶּׁמֶשׁ הָיָה לוֹ לִכְתֹּב, מַה זֶּה הוֹלֵךְ הָרוּחַ? מִי רוּחַ זוֹ? זֶהוּ תַּחַת הַשֶּׁמֶשׁ, שֶׁנִּקְרָא רוּחַ הַקֹּדֶשׁ. וְזֶה (הוא) רוּחַ שֶׁהוֹלֵךְ וְסוֹבֵב לְאוֹתָם שְׁנֵי צְדָדִים לְהִתְחַבֵּר בְּגוּף, וְעַל זֶה כָּתוּב הָרוּחַ, אותו שִּנּודָע הַשִּמִשּ סתָם, שִּנּודָע (להתחבר בגוף שהוא השמש, אותו שנודע) חֵלֶק יִשְׂרָאֵל."],[3,"","וְעַל סְבִיבתָיו שָׁב הָרוּחַ. מִי זֶה סְבִיבתָיו? אֵלּוּ הָאָבוֹת, שֶׁהֵם מֶרְכָּבָה קְדוֹשָׁה, וְהֵם שְׁלֹשָׁה, וְדָוִד וְאַרְבָּעָה רוּחוֹת שֶׁהִתְחַבְּרוּ בָהֶם (ס\"י וזהו רוח שהתחבר בהם) (ודוד הוא רוח רביעי שהתחבר בהם), הֲרֵי הֵם מֶרְכָּבָה קְדוֹשָׁה שְׁלֵמָה. וְעַל זֶה כָּתוּב (תהלים קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה."],[4,"","מִשּׁוּם שֶׁכָּל דִּבְרֵי שְׁלֹמֹה הַמֶּלֶךְ נִסְתָּרִים כֻּלָּם בְּחָכְמָה, וְכֻלָּם פְּנִים פְּנִימָה שֶׁל הֵיכַל הַקָּדוֹשׁ, וּבְנֵי אָדָם לֹא מִסְתַּכְּלִים בָּהֶם, וְרוֹאִים דְּבָרָיו כְּדִבְרֵי אָדָם אַחֵר. אִם כָּךְ, מַהוּ הַשֶּׁבַח לִשְׁלֹמֹה הַמֶּלֶךְ בְּחָכְמָתוֹ מִשְּׁאָר בְּנֵי אָדָם? אֶלָּא וַדַּאי כָּל דָּבָר וְדָבָר שֶׁל שְׁלֹמֹה הַמֶּלֶךְ נִסְתָּר בְּחָכְמָה."],[5,"","פָּתַח וְאָמַר, (קהלת ז) טוֹבָה חָכְמָה עִם נַחֲלָה וְיֹתֵר לְרֹאֵי הַשָּׁמֶשׁ. אִם לֹא הִתְגַּלָּה דָבָר זֶה, לֹא (שמענו ולא) יָדַעְנוּ מָה אָמַר. טוֹבָה חָכְמָה - זוֹהִי חָכְמָה שֶׁהִיא תַּחַת הַשֶּׁמֶשׁ, (לכסא) כִּסֵּא מְתֻקֶּנֶת לוֹ. טוֹבָה חָכְמָה עִם נַחֲלָה, יָפָה וְנָאָה כְּשֶׁהִיא שׁוֹרָה עִם יִשְׂרָאֵל, שֶׁהֵם נַחֲלָתָהּ וְחֶלְקָהּ לְהִתְקַשֵּׁר בָּהּ."],[6,"","אֲבָל שֶׁבַח יוֹתֵר לְרֹאֵי הַשָּׁמֶשׁ, לְאוֹתָם שֶׁזָּכוּ לְהִתְחַבֵּר בַּשֶּׁמֶשׁ וּלְהִתְקַשֵּׁר בּוֹ, שֶׁהֲרֵי אָחוּז בְּעֵץ הַחַיִּים, וּמִי שֶׁאוֹחֵז בּוֹ, אוֹחֵז בַּכֹּל, בְּחַיֵּי הָעוֹלָם הַזֶּה וּבְחַיֵּי הָעוֹלָם הַבָּא. וְזֶהוּ שֶׁכָּתוּב (שם) וְיִתְרוֹן דַּעַת הַחָכְמָה תְּחַיֶּה בְעָלֶיהָ. מַה זֶּה וְיִתְרוֹן דַּעַת? זֶה עֵץ הַחַיִּים. יִתְרוֹנוֹ מַהוּ? הַחָכְמָה וַדַּאי, שֶׁהֲרֵי תּוֹרָה יוֹצֵאת מֵחָכְמָה עֶלְיוֹנָה."],[7,"","עוֹד טוֹבָה חָכְמָה עִם נַחֲלָה - טוֹבָה חָכְמָה וַדַּאי עִם נַחֲלָה, זֶה צַדִּיק הָעוֹלָם שֶׁהוּא אוֹר הַשֶּׁמֶשׁ, שֶׁהֲרֵי שְׁתֵּי דְרָגוֹת אֵלּוּ יוֹשְׁבוֹת כְּאֶחָד, וְזֶהוּ יָפְיָן, אֲבָל וְיֹתֵר לְרֹאֵי הַשָּׁמֶשׁ, לְאוֹתָם שֶׁנֶּאֱחָזִים בַּשֶּׁמֶשׁ, חֹזֶק הַכֹּל, שֶׁבַח הַכֹּל."],[8,"","וְזְהִוּ דַּעַת, עֵץ הַחַיִּים, וַהֲרֵי פֵּרְשׁוּהוּ, (משלי יט) בְּלֹא דַעַת נֶפֶשׁ לֹא טוֹב. אֵיזוֹ נֶפֶשׁ? זוֹ נֶפֶשׁ טוֹבָה שֶׁל דָּוִד הַמֶּלֶךְ, וְזוֹ הַחָכְמָה שֶׁאָמַרְנוּ. וּמִשּׁוּם זֶה יִתְרוֹן דַּעַת הַחָכְמָה, שֶׁמִּשָּׁם נִשְׁרַשׁ עֵץ וְנִנְטַע לְכָל הַצְּדָדִים, וְכֵן לְכָל אֵלּוּ שֶׁאֲחוּזִים בָּעֵץ הַזֶּה. וְעַל זֶה שְׁלֹמֹה הַמֶּלֶךְ לֹא נִמְצָא אֶלָּא בְּאוֹתָהּ דַּרְגָּה שֶׁלּוֹ, וּמִשָּׁם יָדַע הַכֹּל, וְהָיָה אוֹמֵר: עוֹד רָאִיתִי תַּחַת הַשָּׁמֶשׁ, וְשַׁבְתִּי וְרָאִיתִי וְגוֹ'. וְכֵן כֻּלָּם. אַשְׁרֵי אוֹתָם צַדִּיקִים שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה וְיוֹדְעִים דַּרְכֵי הַמֶּלֶךְ הַקָּדוֹשׁ וְנִסְתָּרוֹת עֶלְיוֹנִים שֶׁגְּנוּזִים בַּתּוֹרָה, שֶׁכָּתוּב (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה' וְגוֹ'."],[9,"","יֵאָסֵף אַהֲרֹן אֶל עַמָּיו וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (קהלת ד) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ וְגוֹ'. פָּסוּק זֶה נֶאֱמַר וּפֵרְשׁוּהוּ. בֹּא וּרְאֵה, כָּל מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא בְּדִין וֶאֱמֶת, וְאֵין מִי שֶׁיַּקְשֶׁה כְּנֶגְדּוֹ וְיִמְחֶה בְיָדוֹ וְיֹאמַר לוֹ מָה אַתָּה עוֹשֶׂה, וְכִרְצוֹנוֹ עוֹשֶׂה הַכֹּל."]]],[["וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים. וְכִי שְׁלֹמֹה מַלְכָּא מְשַׁבַּח לְמֵתַיָּיא יַתִּיר מִן חַיָּיא, וְהָא לָא אִקְרֵי חַי אֶלָּא מַאן דְּאִיהוּ בְּאֹרַח קְשׁוֹט בְּהַאי עָלְמָא, כְּמָה דְּאַתְּ אָמֵר (שמואל ב כ״ג:כ׳) וּבְנָיָהוּ בֶן יְהוֹיָדָע בֶּן אִישׁ חַי, וְהָא (בראשית ו' ע\"א, קס\"ד ע\"א, ר\"ז ע\"ב) אוּקְמוּהָ חַבְרַיָּיא, וְרָשָׁע דְּלָא אָזִיל בְּאֹרַח קְשׁוֹט אִקְרֵי מֵת, וְאִיהוּ מְשַׁבֵּחַ לַמֵּתִים מִן הַחַיִּים.","אֶלָּא, וַדַּאי כָּל מִלּוֹי דִּשְׁלֹמֹה מַלְכָּא, בְּחָכְמְתָא אִתְּמָרוּ, וְהָא אִתְּמַר, וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים, אִילּוּ לָא כְּתִיב יַתִּיר, הֲוָה אֲמֵינָא הָכִי, אֲבָל כֵּיוָן דִּכְתִּיב שֶׁכְּבָר מֵתוּ, אִשְׁתְּכַח מִלָּה אַחֲרָא בְּחָכְמְתָא. שֶׁכְּבָר מֵתוּ: זִמְנָא אַחֲרָא אִסְתְּלָקוּ מִן עָלְמָא, וְאִתְתָּקַּן בְּעַפְרָא, (דאזדמנא די ממנא עליה ומית בחיי עלמא דבגין דיתתקן (ס\"א דאזדמנא עליה ותב בהאי עלמא בגין דיתתקן) (ס\"א דממנא עליה ומית בהאי עלמא ואתתקן בעפרא בגין דיתתקן באתר דישתלים זמניה מת הא ודאי דא הוא שבחא משאר מתי עלמא אי תימא אתדן זמנא אחרא בההוא עלמא הא כתיב לא תקום וגו') בתר דאשתלים זמניה מית ודאי הוא שבחא משאר מתי עלמא. אי תימא לא אתדן זמנא אחרא בההוא עלמא, דכתיב לא תקום פעמים צרה) כָּל שֶׁכֵּן דְּהָא קַבִּיל עוֹנְשָׁא זִמְנָא וּתְרֵין, וְדָא וַדַּאי, אַתְרֵיהּ אִתְתָּקַּן בִּשְׁבָחָא יַתִּיר מֵאִינּוּן חַיֵּי, דְּעַד לָא קַבִּילוּ עוֹנְשָׁא.","וְעַל דָּא כְּתִיב וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, דַּיְיקָא, אִלֵּין אִינּוּן חַיִּין, וְאִקְרוּן מֵתִים. מַאי טַעְמָא אִקְרוּן מֵתִים, בְּגִין דְּהָא טָעֲמוּ טַעֲמָא דְּמוֹתָא, וְאַף עַל גַּב דְּקַיְּימֵי בְּהַאי עָלְמָא, מֵתִים אִינּוּן, וּמִבֵּין מֵתַיָּיא אָהַדְרוּ. וְעוֹד עַל עוֹבָדִין קַדְמָאִין קַיְימִין לְאַתְקְנָא, וְאִקְרוּן מֵתִים. מִן הַחַיִּים אֲשֶׁר הֵמָּה חַיִּים, דְּעַד לָא טָעֲמוּ טַעֲמָא דְּמוֹתָא, וְלָא קַבִּילוּ עוֹנְשַׁיְיהוּ, וְלָא יַדְעֵי אִי זַכָּאן בְּהַהוּא עָלְמָא וְאִי לָאו.","תָּא חֲזֵי, זַכָּאִין דְּזַכָּאָן לְאִתְקַשְּׁרָא בִּצְרוֹרָא דְּחַיֵּי, אִינּוּן זַכָּאִין לְמֵחמֵי בִּיקָרָא דְּמַלְכָּא עִלָּאָה קַדִּישָׁא, כְּמָה דְּאַתְּ אָמֵר, (תהילים כ״ז:ד׳) לַחֲזוֹת בְּנֹעַם יְיָ וּלְבַקֵּר בְּהֵיכָלוֹ. וְאִינּוּן מָדוֹרֵהוֹן, יַתִּיר וְעִלָּאָה מִכָּל אִינּוּן מַלְאֲכִין קַדִּישִׁין, וְכָל דַּרְגִּין דִּלְהוֹן. דְּהָא הַהוּא אַתְרָא (ס\"א חדוה) עִלָּאָה, לָא זַכָּאִין עִלָּאִין וְתַתָּאִין לְמֵחמֵי לֵיהּ, הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ד:ג׳) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךָ וְגוֹ'.","וְאִינּוּן דְּלָא זַכָּאן לְסַלְּקָא כָּל כַּךְ כְּאִינּוּן, (ס\"א דוכתא, אית וכו') דּוּכְתָּיָיא אִית לוֹן לְתַתָּא כְּפוּם אוֹרְחַיְיהוּ, וְאִלֵּין לָא זַכָּאן לְהַהוּא אֲתָר, וּלְמֵחמֵי כְּמָה דְּחָמָאן אִינּוּן דִּלְעֵילָּא, וְאִלֵּין קַיְימֵי בְּקִיּוּמָא דְּעֵדֶן תַּתָּאָה וְלָא יַתִּיר. וְאִי תֵּימָא מַאן עֵדֶן תַּתָּאָה. אֶלָּא דָּא עֵדֶן דְּאִקְרֵי חָכְמָה תַּתָּאָה, וְדָא קַיְּימָא עַל גַּן דִּבְאַרְעָא, וְאַשְׁגָחוּתָא דְּהַאי עֵדֶן עָלֵיהּ (ולא יתיר), וְאִלֵּין קַיְימֵי בְּהַאי גַּן, וְאִתְהֲנוּן מֵעֵדֶן דָּא.","מַאי בֵּין עֵדֶן תַּתָּאָה לְעִלָּאָה. כִּיתְרוֹן הָאוֹר מִן הַחֹשֶׁךְ, עֵדֶן תַּתָּאָה, אִקְרֵי עֶדְנָא נוּקְבָּא. עֵדֶן עִלָּאָה, אִקְרֵי עֵדֶן דְּכַר, עָלֵיהּ כְּתִיב עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךָ. הַאי עֵדֶן תַּתָּאָה, אִקְרֵי גַּן לְעֵדֶן דִּלְעֵילָּא, וְהַאי גַּן אִקְרֵי עֵדֶן, לְגַן דִּלְתַּתָּא. וְאִלֵּין דְּמִשְׁתַּכְּחֵי בְּגַן תַּתָּאָה, אִתְהֲנוּן מֵהַאי עֵדֶן דְּעָלַיְיהוּ, בְּכָל שַׁבָּת וְשַׁבָּת, וּבְכָל יַרְחָא וְיַרְחָא, הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ו:כ״ג) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתוֹ.","וְעַל אִלֵּין אָמַר שְׁלֹמֹה, מִן הַחַיִּים אֲשֶׁר הֵמָּה חַיִּים עֲדֶנָּה, דְּהָא אִלֵּין בְּדַרְגָּא עִלָּאָה יַתִּיר מִנַּיְיהוּ. מַאן אִינּוּן. אִינּוּן שֶׁכְּבָר מֵתוּ, וְקַבִּילוּ עוֹנְשָׁא תְּרֵי זִמְנֵי, וְאִלֵּין אִקְרוּן כֶּסֶף מְזוּקָּק, דְּעָאל לְנוּרָא זִמְנִין וּתְרֵין, וְנָפִיק מִנֵּיהּ זוּהֲמָא, וְאִתְבָּרַר וְאִתְנָקֵי. (קהלת ד׳:ג׳) וְטוֹב מִשְּׁנֵיהֶם אֶת אֲשֶׁר עֲדֶן לֹא הָיָה. הַהוּא רוּחָא דְּקָאִים לְעֵילָּא, וְאִתְעַכָּב לְנַחְתָּא לְתַתָּא, דְּהַאי קָאִים בְּקִיּוּמֵיהּ, וְלֵית לֵיהּ לְקַבְּלָא עוֹנְשָׁא, וְאִית לֵיהּ מְזוֹנָא מֵהַהוּא מְזוֹנָא עִלָּאָה דִּלְעֵילָּא לְעֵילָּא."],[[0,"ושבח אני את המתים:","שואל, וכי שלמה המלך משבח את המתים יותר מן החיים, והרי לא נקרא חי, אלא מי שהוא בדרך אמת בעולם הזה. כש\"א, ובניהו בן יהודע בן איש חי. והעמידו החברים. והרשע, שאינו הולך בדרך אמת נקרא מת. ושלמה המלך משבח את המתים מן החיים."],[1,"אלא ודאי כל וכו':","אלא ודאי כל דבריו של שלמה המלך נאמרו בחכמה, והרי למדנו, ושבח אני את המתים, אילו לא היה כתוב יותר, הייתי אומר כך, שמשבח את המתים יותר מן החיים, אבל כיון שכתוב, \u0003שכבר מתו,\u0004 נמצא בזה דבר אחר בחכמה. שכבר מתו, פירושו, שכבר מתו בזמן אחר, שנסתלקו מן העולם ונתתקנו בעפר, דהיינו שחזרו ונתגלגלו ובאו לעולם הזה. כל שכן שקבלו עונש פעם ושתים, כי היו ב' פעמים בעולם הזה, וזה ודאי שנתתקן מקומו ביותר שבח מאלו החיים שעוד לא קבלו עונש הגלגול."],[2,"וע\"ד כתיב ושבח וגו':","וע\"כ כתוב, ושבח אני את המתים שכבר מתו, שכבר מתו הוא בדיוק, דהיינו אלו שהם חיים, ונקראים מתים. מהו הטעם שנקראים מתים. הוא משום שטעמו טעם המות, ואע\"פ שנמצאים בעולם הזה, הם מתים, ומבין המתים הוחזרו. ועוד, כי הם עומדים לתקן על מעשים הראשונים שעשו קודם מיתתם, ע\"כ נקראים מתים, להיותם מתקנים המעשים של מי שמת, \u0003מן החיים אשר המה חיים,\u0004 כי עוד לא טעמו טעם המות, ולא קבלו עונשם, ואינם יודעים אם המה זכאים בעולם ההוא או לא."],[3,"ת\"ח זכאין דזכאן וכו':","בוא וראה, צדיקים הזוכים להתקשר בצרור החיים, שהוא יסוד דז\"א, הם זוכים לראות בכבוד המלך העליון הקדוש, כמש\"א, לחזות בנעם ה' ולבקר בהיכלו, והם, המדור שלהם הוא יותר עליון מכל המלאכים הקדושים וכל מדרגותיהם, כי מקום עליון זה אין העליונים והתחתונים זוכים לראותו. ז\"ש עין לא ראתה אלקים זולתך וגו'. שה\"ס עדן העליון."],[4,"ואינון דלא זכאן וכו':","ואלו שאינם זוכים לעלות כל כך כמו אלו, מקום יש להם למטה כפי דרכיהם, ואלו אינם זוכים למקום ההוא, ולראות כמו שרואים אלו שלמעלה, אלא אלו עומדים במקום של עדן התחתון, ולא יותר. ואם תאמר מהו עדן התחתון. אלא זה הוא עדן שנקרא חכמה התחתונה, שהיא המלכות, והיא עומדת על הגן שבארץ. וההשגחה של עדן הזה עליו, על הגן. ואלו הצדיקים, עומדים בגן עדן זה שבארץ, ונהנים מערן הזה, שהיא חכמה תתאה."],[5,"מאי בין עדן וכו':","מהו בין עדן התחתון לעדן העליון, הוא כיתרון האור מן החשך, עדן התחתון נקרא עדנה. שהיא נקבה, עדן העליון נקרא עדן, שהוא זכר, (כנ\"ל שלח אות רמ\"ה) עליו כתוב, עין לא ראתה אלקים זולתך. עדן התחתון זה נקרא גן כלפי עדן שלמעלה, וגן הזה נקרא עדן כלפי הגן שלמטה. ואלו הנמצאים בגן שלמטה, שהוא ג\"ע הארץ, נהנים מאותו העדן שעליהם, שהוא חכמה תתאה, בכל שבת ושבת ובכל חדש וחדש, ז\"ש, והיה מדי חדש בחדשו ומדי שבת בשבתו וגו'."],[6,"ועל אלין אמר וכו':","ועל אלו אמר שלמה, מן החיים אשר המה חיים עדנה, כי אלו הם במדרגה עליונה יותר מהם, מי הם, אלו. היינו אלו שכבר מתו וקבלו עונשם שתי פעמים (כנ\"ל אות נ\"ה) ואלו נקראים כסף מזוקק, שנכנס לתנור פעם ושתים ויצא ממנו הזוהמא, ונתברר ונעשה נקי. וטוב משניהם את אשר עדן לא היה, היינו רוח ההוא העומד למעלה ונעכב מלרדת למטה, שזה עומד בקיומו, שעוד לא חטא, ואין לו לקבל עונש, ויש לו מזון ממזון ההוא העליון שלמעלה למעלה."]],[[0,"","וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים. וְכִי שְׁלֹמֹה הַמֶּלֶךְ מְשַׁבֵּחַ אֶת הַמֵּתִים יוֹתֵר מֵהַחַיִּים? וַהֲרֵי לֹא נִקְרָא חַי אֶלָּא מִי שֶׁהוּא בְּדֶרֶךְ אֱמֶת בָּעוֹלָם הַזֶּה, כְּמוֹ שֶׁנֶּאֱמַר (שמואל בכג) וּבְנָיָהוּ בֶן יְהוֹיָדָע בֶּן אִישׁ חַי, וַהֲרֵי פֵּרְשׁוּהוּ הַחֲבֵרִים, וְרָשָׁע שֶׁלֹּא הוֹלֵךְ בְּדֶרֶךְ אֱמֶת נִקְרָא מֵת, וְהוּא מְשַׁבֵּחַ אֶת הַמֵּתִים מֵהַחַיִּים?"],[1,"","אֶלָּא וַדַּאי כָּל דִּבְרֵי שְׁלֹמֹה הַמֶּלֶךְ בְּחָכְמָה נֶאֶמְרוּ, וַהֲרֵי נִתְבָּאֵר. וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים, אִלּוּ לֹא כָתוּב יוֹתֵר, הָיִיתִי אוֹמֵר כָּךְ. אֲבָל כֵּיוָן שֶׁכָּתוּב שֶׁכְּבָר מֵתוּ, נִמְצָא דָבָר אַחֵר בְּחָכְמָה. שֶׁכְּבָר מֵתוּ - זְמַן אַחֵר הִסְתַּלְּקוּ מֵהָעוֹלָם, וְהִתְתַּקְּנוּ בֶעָפָר, (שהזדמן הממנה עליו ומת בחיי עולם כדי שיתתקן (שהזדּמן עָלָיו ושָב בָּעולָם הזּה כּדי שיּתתּקּן) (הממנּה עָלָיו וּמת בָּעולָם הזּה ונתקן בּעָפָר כּדי שיּתתּקּן בּמָקום שיּשלם זמנּו מת הוּא ודּאי, זהוּ שבח משאָר מתי הָעולָם. אם תּאמר לא ידּון פּעם אחרת בּאותו עולָם, הרי כָּתוּב לא תָקוּם וגו') לאחר שנשלם זמנו מת, ודאי הוא שבח משאר מתי העולם. אם תאמר לא ידון פעם אחרת באותו עולם, שכתוב לא תקום פעמים צרה) כָּל שֶׁכֵּן שֶׁזֶּה קִבֵּל עֹנֶשׁ פַּעַם וּפַעֲמַיִם, וְזֶה וַדַּאי מְקוֹמוֹ נִתְקָן בְּשֶׁבַח יוֹתֵר מֵאוֹתָם חַיִּים שֶׁעֲדַיִן לֹא קִבְּלוּ עָנְשָׁם."],[2,"","וְעַל זֶה כָּתוּב וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, דַּוְקָא. אֵלֶּה אוֹתָם חַיִּים, וְנִקְרָאִים מֵתִים. מָה הַטַּעַם נִקְרָאִים מֵתִים? מִשּׁוּם שֶׁהֲרֵי טָעֲמוּ טַעַם הַמָּוֶת. וְאַף עַל גַּב שֶׁעוֹמְדִים בָּעוֹלָם הַזֶּה, הֵם מֵתִים, וּמִבֵּין הַמֵּתִים חָזְרוּ, וְעוֹד עַל מַעֲשִׂים רִאשׁוֹנִים עוֹמְדִים לְתִקּוּן, וְנִקְרָאִים מֵתִים. מִן הַחַיִּים אֲשֶׁר הֵמָּה חַיִּים - שֶׁעוֹד לֹא טָעֲמוּ טַעַם מָוֶת וְלֹא קִבְּלוּ עָנְשָׁם, וְלֹא יוֹדְעִים אִם זַכָּאִים בְּאוֹתוֹ הָעוֹלָם וְאִם לֹא."],[3,"","בֹּא וּרְאֵה, צַדִּיקִים שֶׁזּוֹכִים לְהִתְקַשֵּׁר בִּצְרוֹר הַחַיִּים, הֵם זַכָּאִים לִרְאוֹת בִּכְבוֹד הַמֶּלֶךְ הָעֶלְיוֹן הַקָּדוֹשׁ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים כז) לַחֲזוֹת בְּנֹעַם ה' וּלְבַקֵּר בְּהֵיכָלוֹ. וְאוֹתָם מְדוֹרֵיהֶם יוֹתֵר וְעֶלְיוֹן מִכָּל אוֹתָם מַלְאָכִים קְדוֹשִׁים וְכָל דַּרְגוֹתֵיהֶם. שֶׁהֲרֵי אוֹתוֹ מָקוֹם (חדוה) עֶלְיוֹן לֹא זוֹכִים עֶלְיוֹנִים וְתַחְתּוֹנִים לִרְאוֹתוֹ. זֶהוּ שֶׁכָּתוּב (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ וְגוֹ'."],[4,"","וְאוֹתָם שֶׁלֹּא זוֹכִים לַעֲלוֹת כָּל כָּךְ כְּאוֹתָם אֵלֶּה, (מקום יש וכו') מְקוֹמוֹת יֵשׁ לָהֶם לְמַטָּה כְּפִי דַרְכֵיהֶם, וְאֵלֶּה לֹא זוֹכִים לְאוֹתוֹ מָקוֹם וְלִרְאוֹת כְּפִי שֶׁרוֹאִים אֵלּוּ שֶׁלְּמַעְלָה, וְאֵלֶּה עוֹמְדִים בְּקִיּוּם שֶׁל עֵדֶן הַתַּחְתּוֹן וְלֹא יוֹתֵר. וְאִם תֹּאמַר, מַה זֶּה עֵדֶן תַּחְתּוֹן? אֶלָּא זֶה עֵדֶן שֶׁנִּקְרָא חָכְמָה תַחְתּוֹנָה, וְזֶה עוֹמֵד עַל גַּן שֶׁבָּאָרֶץ, וְהַשְׁגָּחַת עֵדֶן זֶה עָלָיו (ולא יותר), וְאֵלֶּה עוֹמְדִים בְּגַן זֶה וְנֶהֱנִים מֵעֵדֶן זֶה."],[5,"","מַה בֵּין עֵדֶן תַּחְתּוֹן לָעֶלְיוֹן? (קהלת ב) כִּיתְרוֹן הָאוֹר מִן הַחֹשֶׁךְ. עֵדֶן תַּחְתּוֹן נִקְרָא עֵדֶן נְקֵבָה, עֵדֶן עֶלְיוֹן נִקְרָא עֵדֶן זָכָר, עָלָיו כָּתוּב עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ. עֵדֶן תַּחְתּוֹן זֶה נִקְרָא גַּן לְעֵדֶן שֶׁלְּמַעְלָה, וְגַן זֶה נִקְרָא עֵדֶן לַגָּן שֶׁלְּמַטָּה. וְאֵלֶּה שֶׁנִּמְצָאִים בַּגָּן הַתַּחְתּוֹן נֶהֱנִים מֵהָעֵדֶן הַזֶּה שֶׁעֲלֵיהֶם בְּכָל שַׁבָּת וְשַׁבָּת וּבְכָל חֹדֶשׁ וְחֹדֶשׁ. זֶהוּ שֶׁכָּתוּב (ישעיה סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ."],[6,"","וְעַל אֵלֶּה אָמַר שְׁלֹמֹה, מִן הַחַיִּים אֲשֶׁר הֵמָּה חַיִּים עֲדֶנָה. שֶׁהֲרֵי אֵלֶּה בְּדַרְגָּה עֶלְיוֹנָה יוֹתֵר מֵהֶם. מִי אֵלּוּ? אֵלּוּ שֶׁכְּבָר מֵתוּ וְקִבְּלוּ עֹנֶשׁ פַּעֲמַיִם, וְאֵלֶּה נִקְרָאִים כֶּסֶף מְזֻקָּק, שֶׁנִּכְנָס לָאֵשׁ פַּעֲמַיִם וּשְׁנַיִם, וְיוֹצֵא מִמֶּנּוּ זֻהֲמָא, וְהִתְבָּרֵר וְהִתְנַקָּה. וְטוֹב מִשְּׁנֵיהֶם אֵת אֲשֶׁר עֲדֶן לֹא הָיָה - אוֹתָהּ רוּחַ שֶׁעוֹמֶדֶת לְמַעְלָה וְהִתְעַכְּבָה לָרֶדֶת לְמַטָּה, שֶׁהֲרֵי עוֹמֵד בְּעָמְדוֹ וְאֵין לוֹ לְקַבֵּל עֹנֶשׁ, וְיֵשׁ לוֹ מָזוֹן מֵאוֹתוֹ מָזוֹן עֶלְיוֹן שֶׁלְּמַעְלָה לְמַעְלָה."]]],[["טַב מְכֻּלְּהוּ, מַאן דְּלָא אִתְפְּרַשׁ, וְלָא אִתְגַּלְיָיא, וְכָל מִלּוֹי בִּסְתִּימָא אִינּוּן. דָּא הוּא זַכָּאָה חֲסִידָא, דְּנָטַר פִּקּוּדֵי אוֹרַיְיתָא, וְקִיֵּים לוֹן, וְאִשְׁתָּדַּל בְּאוֹרַיְיתָא יְמָמָא וְלֵילֵי. דָּא אִתְאֲחִיד וְאִתְהֲנֵי בְּדַרְגָּא עִלָּאָה עַל כָּל שְׁאַר בְּנֵי נָשָׁא, וְכֻלְּהוּ אִתְאַחֲדָן (ס\"א אתוקדן) מֵחוּפָּה דְּהַאי.","תָּא חֲזֵי, בְּשַׁעֲתָא דְּאָמַר קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה יֵאָסֵף אַהֲרֹן אֶל עַמָּיו, אִתְחֲלָשׁ חֵילָא דִּילֵיהּ, וְיָדַע דְּהָא אַתְּבַּר (תצוה קפ\"א ע\"א) דְּרוֹעָא יְמִינָא דִּילֵיהּ, וְאִזְדַּעְזְעָא כָּל גּוּפֵיהּ, כֵּיוָן דְּאָמַר קַח אֶת אַהֲרֹן וְאֶת אֶלְעָזָר בְּנוֹ, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, מֹשֶׁה, הָא דְּרוֹעָא אַחֲרָא אוֹזִיפְנָא לָךְ (זמינית לך), וְהַפְשֵׁט אֶת אַהֲרֹן וְגוֹ', וְאַהֲרֹן יֵאָסֵף, הֵא אֶלְעָזָר יְהֵא לְגַבָּךְ, זִמְנָא (נ\"א ימינא) דָא תֵּחוֹת אֲבוֹי. וְעִם כָּל דָּא לָא אַשְׁלִים אֲתָר בְּהַהוּא זִמְנָא כַּאֲבוֹי, דְּהָא עֲנָנֵי יְקָר אִסְתְּלָקוּ, וְלָא אָהַדְרוּ אֶלָּא בִּזְכוּתָא דְּמֹשֶׁה, וְלָא בִּזְכוּתָא דְּאֶלְעָזָר.","(במדבר כ׳:כ״ז) וַיַּעַשׂ מֹשֶׁה כַּאֲשֶׁר צִוָּה וְגוֹ'. אֲמַאי לְעֵינֵי כָּל הָעֵדָה. אֶלָּא, בְּגִין דְּאַהֲרֹן הֲוָה רְחִימָא דְּעַמָּא, יַתִּיר מִכֹּלָּא, וְלָא יֵימְרוּן דְּהָא אִתְנְגִיד עַל יְדָא דְּמֹשֶׁה. וּמֹשֶׁה מָשִׁיךְ לְאַהֲרֹן בְּמִלִּין, עַד דְּסָלִיקוּ לְטוּרָא, וְכָל יִשְׂרָאֵל הֲווֹ חָמָאן, בְּשַׁעֲתָא דְּאַפְשִׁיט מֹשֶׁה לְבוּשֵׁי דְּאַהֲרֹן, וְאַלְבִּישׁ לוֹן לְאֶלְעָזָר.","מַאי טַעֲמָא מֹשֶׁה (נ\"א ולאהרן). אֶלָּא מֹשֶׁה אַלְבִּשִׁינוּן לְאַהֲרֹן כַּד סָלִיק לְכַהֲנָא, הֲדָא הוּא דִכְתִיב וְיַלְבֵּשׁ מֹשֶׁה אֶת אַהֲרֹן אֶת בְּגָדָיו, וּכְתִיב (ויקרא ח׳:ז׳) וְיַלְבֵּשׁ אוֹתוֹ אֶת הַמְּעִיל. הַשְׁתָּא. מֹשֶׁה אַעְדֵּי מִנֵּיהּ, מַה דְּיָהַב לֵיהּ. וְקוּדְשָׁא בְּרִיךְ הוּא אַעְדֵּי מִנֵּיהּ, מַה דְּיָהַב לֵיהּ. וְתַרְוַויְיהוּ אַפְשִׁיטוּ לֵיהּ לְאַהֲרֹן מִכֹּלָּא, וּמֹשֶׁה אַעְדֵּי לְבַר, וְקוּדְשָׁא בְּרִיךְ הוּא לְגוֹ. וְעַד דְּאַעְדֵּי מֹשֶׁה, קוּדְשָׁא בְּרִיךְ הוּא לָא אַעְדֵּי, זַכָּאָה חוּלָקָא דְּמֹשֶׁה.","זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא, דְקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי בִּיקָרֵיהוֹן. אַתְקִין קוּדְשָׁא בְּרִיךְ הוּא לְאַהֲרֹן, עַרְסָא וּמְנַרְתָּא דְּדַהֲבָא דְּנַהֲרָא. וּמִדִּידֵיהּ נָטִיל, מֵהַהוּא מְנַרְתָּא דְּהֲוָה דָּלִיק בְּכָל יוֹמָא תְּרֵי זִמְנֵי וְאַסְתִּים פּוּם מְעַרְתָּא וְנַחְתּוּ.","רִבִּי יְהוּדָה אָמַר, פּוּם מְעַרְתָּא הֲוָה פְּתִיחָא, דְּכָל יִשְׂרָאֵל הֲווֹ חָמָאן לְאַהֲרֹן שָׁכִיב, וּבוּצִינָא דִּמְנַרְתָּא דָּלִיק קַמֵּיהּ, וְעַרְסֵיהּ נָפִיק וְעָיִיל, וַעֲנָנָא חַד קָאִים עָלֵיהּ. וּכְדֵין יָדְעוּ יִשְׂרָאֵל דְּהָא אַהֲרֹן מִית. וְחָמוּ דְּהָא אִסְתְּלָקוּ עֲנָנֵי כָּבוֹד, הֲדָא הוּא דִכְתִיב וַיִּרְאוּ כָּל הָעֵדָה כִּי גָוַע אַהֲרֹן וְגוֹ', וְהָא אוּקְמוּהָ. וְעַל דָּא בָּכוּ לְאַהֲרֹן כָּל בֵּית יִשְׂרָאֵל, גּוּבְרִין וְנָשִׁין וְטָף, דְּהָא רְחִימָא מְכֻּלְּהוּ הֲוָה.","רִבִּי שִׁמְעוֹן אָמַר, הָנֵי תְּלָתָא אָחִין עִלָּאִין קַדִּישִׁין, אֲמַאי לָא אִתְקָבָרוּ בְּאֲתָר חַד, וְשַׁיְיפִין אִתְבַּדְרוּ, חַד הָכָא, וְחַד הָכָא, וְחַד בְּאֲתָר אַחֲרָא. אֶלָּא אִית דְּאַמְרֵי, בַּאֲתָר דְּבָעָאן יִשְׂרָאֵל לְאִסְתַּכְּנָא בֵּיהּ, מִית כָּל חַד וְחַד, בְּגִין לְאַגָּנָא עָלַיְיהוּ, וְאִשְׁתֵּזְבוּן, אֲבָל כָּל חַד וְחַד מִית כַּדְּקָא חֲזֵי עָלַיְיהוּ. מִרְיָם בְּקָדֵשׁ, בֵּין צָפוֹן לְדָרוֹם. אַהֲרֹן לִסְטַר יְמִינָא. מֹשֶׁה כַּדְּקָא חֲזֵי לֵיהּ. אָחִיד הַהוּא טוּרָא לְטוּרָא דְּאַהֲרֹן, וְכָנִישׁ לִקְבוּרָתָא דְּמִרְיָם לְגַבֵּי הַהוּא טוּרָא, אָחִיד לִתְרֵי סִטְרֵי. וְעַל דָּא אִתְקְרֵי הַר הָעֲבָרִים, דִּתְרֵי סִטְרֵי טוּרָא דִּמְעַבְרֵי, וְאָחִיד לְסִטְרָא דָּא וּלְסִטְרָא דָּא.","זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי. וְאַף עַל גַּב דְּאִינּוּן בַּאֲתָר אַחֲרָא, בְּעָלְמָא אַחֲרָא עִלָּאָה, זְכוּתְהוֹן קַיְּימָא בְּעָלְמָא דָּא, לְדָרֵי דָּרִין. וּבְשַׁעֲתָא דְּיִשְׂרָאֵל תַּיְיבִין בְּתִיּוּבְתָּא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וּגְזֵירָה אִתְגְּזַר עָלַיְיהוּ, כְּדֵין קָארֵי קוּדְשָׁא בְּרִיךְ הוּא לְצַדִּיקַיָּיא דְּקַיְימֵי קַמֵּיהּ לְעֵילָּא, וְאוֹדַע לוֹן, וְאִינּוּן מְבַטְּלֵי הַהִיא גְּזֵרָה, וְחָיֵיס קוּדְשָׁא בְּרִיךְ הוּא עָלַיְיהוּ דְּיִשְׂרָאֵל. זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּעָלַיְיהוּ כְּתִיב (ישעיהו נ״ח:י״א) וְנָחֲךָ יְיָ תָּמִיד וְגוֹ'.","(במדבר כ״א:ה׳) וַיְדַבֵּר הָעָם בֵּאלֹהִים וּבְמֹשֶׁה וְגוֹ'. פַּרְשְׁתָּא דָּא, בַּאֲתָר אַחֲרָא אִסְתָּלִיק, עִם אִינּוּן מֵי מְרִיבָה דְּמֹשֶׁה וְאַהֲרֹן."],[[0,"טב מכלהו מאן וכו':","טוב מכולם, הוא, מי שבא לעולם הזה, ולא נפרד מהקב\"ה, ואינו בגלוי, וכל דבריו הם בצנעה, זה הוא זכאי חסיד ששמר מצות התורה וקיים אותם ועסק בתורה יומם ולילה, זה מתאחד ונהנה במדרגה עליונה על כל שאר בני אדם, וכלם נשרפים מהסתכלות בחופה של זה."],[1,"ת\"ח בשעתא וכו':","בוא וראה, בשעה שאמר הקב\"ה למשה, יאסף אהרן אל עמיו, נחלש כחו, וידע שנשבר זרוע הימין שלו שהוא החסד, ונזדעזע כל גופו. כיון שאמר קח את אהרן ואת אלעזר בנו. אמר לו הקב\"ה, משה, הרי זרוע אחר השאלתי לך. והפשט את אהרן וגו'. ואהרן יאסף, הרי אלעזר יהיה אצלך ימין הזה, תחת אביו. ועם כל זה לא מילא מקום בזמן ההוא כאביו, שהרי ענני יקר נסתלקו, ולא הזרו אלא בזכותו של משה, ולא בזכות אלעזר."],[2,"ויעש משה כאשר צוה וגו':","שואל, למה לעיני כל העדה. ומשיב, משום שאהרן היה אהובו של העם יותר מהכל, ולא יאמרו שמת על ידי משה. ומשה משך את אהרן בדברים, עד שעלו אל ההר, וכל ישראל היו רואים בשעה שהפשיט משה לבושי אהרן והלבישם לאלעזר."],[3,"מאי טעמא משה וכו':","שואל, מהו הטעם שמשה פשט את בגדיו. ומשיב, אלא משה הלבישם את אהרן, בשעה שעלה לכהונה. ז\"ש וילבש משה את אהרן את בגדיו. וכתוב, וילבש אותו את המעיל. ע\"כ עתה, הסיר משה ממנו מה שנתן לו, והקב\"ה הסיר ממנו מה שנתן לו, דהיינו נשמתו. ושניהם הפשיטו את אהרן מכל, ומשה הסיר מה שבחוץ, והקב\"ה מה שבפנים. וכל עוד שלא הסיר משה, הקב\"ה לא הסיר. אשרי חלקו של משה."],[4,"זכאה חולקיהון דצדיקייא וכו':","אשרי חלקם של הצדיקים, שהקב\"ה רוצה בכבודם, כי התקין הקב\"ה לאהרן, מטה ומנורה של זהב המאירה, ומשל עצמו לקחה, ממנורה ההיא שהיה מדליק שתי פעמים בכל יום. ואחר זה הסתים פי המערה וירדו."],[5,"רבי יהודה אמר וכו':","רי\"א, פי המערה היה פתוח, וכל ישראל היו רואים את אהרן מת, ונר המנורה דולק לפניו, ומטתו יוצאת ונכנסת, כדי שיראו ישראל שהוא מת, וענן אחת עומד על המטה. ואז ידעו ישראל כי אהרן מת. וראו שנסתלקו ענני כבוד מישראל. ז\"ש ויראו כל העדה כי גוע אהרן וגו'. וכבר העמידוהו. וע\"כ בכו את אהרן כל בית ישראל גברים ונשים וטף, כי אהובם של כולם היה."],[6,"רבי שמעון אמר וכו':","רש\"א, אלו ג' אחים עליונים, קדושים, למה לא נקברו במקום אחד, והאברים נתפזרו אחד כאן ואחד כאן ואחד במקום אחר. אלא יש שאומרים, שבמקום שהיו עתידים ישראל להסתכן שם, מתו כל אחד ואחד, כדי להגן על ישראל. ונצלו. אבל, הפירוש הוא, כי כל אחד מת כראוי לו. מרים מתה בקדש. והיתה בין צפון לדרום. כי מרים היתה מרכבה למלכות, שהיא בין ימין ושמאל דז\"א המכונים דרום צפון. אהרן. שהיה מרכבה לחסד, שמת בהר ההר, היה לצד ימין. משה, שמת בהר העברים, היה באמצע כראוי לו, כי משה היה מרכבה לקו אמצעי, שהוא ת\"ת. אחז הר הזה של משה, בהר של אהרן, ואסף קברה של מרים להר ההוא של משה, שהיה אחוז מב צדדים מימין ומשמאל. כי קו האמצעי כולל ימין ושמאל. וע\"כ נקרא הר העברים, על שם המעבר שיש בין שני צדדי ההר, המעברים, והמעבר אחוז בצד זה ובצד זה, בימין ובשמאל."],[7,"זכאה חולקהון דצדיקייא וכו':","אשרי חלקם של הצדיקים בעולם הזה ובעולם הבא. ואע\"פ שהם במקום אחר בעולם אחר עליון, זכותם עומדת בעולם הזה לדורי דורות. ובשעה שישראה חוזרים בתשובה לפני הקב\"ה, וגזירה נגזר עליהם. אז קורא הקב\"ה את הצדיקים העומדים לפניו למעלה, ומודיע להם, והם מבטלים גזרה ההיא, והקב\"ה מרחם על ישראל. אשרי הם הצדיקים שעליהם כתוב, ונחך ה' תמיד וגו'."],[8,"וידבר העם באלקים ובמשה וגו':","פרשה זו נתבאר במקום אחר, עם אלו הכתובים של מי מריבה של משה ואהרן."]],[[0,"","טוֹב מִכֻּלָּם מִי שֶׁלֹּא הִתְפָּרֵשׁ וְלֹא הִתְגַּלָּה וְכָל דְּבָרָיו בְּנִסְתָּר הֵם, זֶהוּ זַכַּאי חָסִיד שֶׁשָּׁמַר מִצְווֹת הַתּוֹרָה וְקִיְּמָן, וְהִשְׁתַּדֵּל בַּתּוֹרָה יוֹמָם וָלַיְלָה. זֶה נֶאֱחָז וְנֶהֱנֶה בְּדַרְגָּה עֶלְיוֹנָה עַל כָּל שְׁאָר בְּנֵי אָדָם, וְכֻלָּם נֶאֱחָזִים (נכוים) מֵחֻפָּתוֹ."],[1,"","בֹּא וּרְאֵה, בְּשָׁעָה שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה יֵאָסֵף אַהֲרֹן אֶל עַמָּיו, נֶחֱלַשׁ כֹּחוֹ, וְיָדַע שֶׁנִּשְׁבְּרָה זְרוֹעוֹ הַיְמָנִית, וְהִזְדַּעֲזַע כָּל גּוּפוֹ. כֵּיוָן שֶׁאָמַר קַח אֶת אַהֲרֹן וְאֶת אֶלְעָזָר בְּנוֹ, אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: מֹשֶׁה, הֲרֵי זְרוֹעַ אַחֶרֶת הִלְוֵיתִי לְךְ (זמנתי לך), וְהַפְשֵׁט אֶת אַהֲרֹן וְגוֹ', וְאַהֲרֹן יֵאָסֵף, הֲרֵי אֶלְעָזָר יִהְיֶה אֶצְלְךְ בִּזְמַן (ימין) זֶה תַּחַת אָבִיו. וְעִם כָּל זֶה לֹא הִשְׁלִים מָקוֹם בְּאוֹתוֹ זְמַן כְּאָבִיו, שֶׁהֲרֵי עַנְנֵי הַכָּבוֹד הִסְתַּלְּקוּ, וְלֹא חָזְרוּ אֶלָּא בִּזְכוּת מֹשֶׁה, וְלֹא בִּזְכוּת אֶלְעָזָר."],[2,"","וַיַּעַשׂ מֹשֶׁה כַּאֲשֶׁר צִוָּה וְגוֹ'. לָמָּה לְעֵינֵי כָּל הָעֵדָה? אֶלָּא מִשּׁוּם שֶׁאַהֲרֹן הָיָה אֲהוּב הָעָם יוֹתֵר מֵהַכֹּל, וְלֹא יֹאמְרוּ שֶׁזֶּה נִמְשָׁךְ עַל יְדֵי מֹשֶׁה. וּמֹשֶׁה מָשַׁךְ לְאַהֲרֹן בִּדְבָרִים עַד שֶׁעָלוּ לָהָר, וְכָל יִשְׂרָאֵל הָיוּ רוֹאִים בְּשָׁעָה שֶׁהִפְשִׁיט מֹשֶׁה לְבוּשֵׁי אַהֲרֹן וְהִלְבִּישָׁם לְאֶלְעָזָר."],[3,"","מָה הַטַּעַם מֹשֶׁה (ולאהרן) ? אֶלָּא מֹשֶׁה הִלְבִּישָׁם אֶת אַהֲרֹן כְּשֶׁעָלָה לַכְּהֻנָּה, זֶהוּ שֶׁכָּתוּב וַיַּלְבֵּשׁ מֹשֶׁה אֶת אַהֲרֹן אֶת בְּגָדָיו, וְכָתוּב (ויקרא ח) וַיַּלְבֵּשׁ אֹתוֹ אֶת הַמְּעִיל. כָּעֵת מֹשֶׁה הוֹרִיד מִמֶּנּוּ מַה שֶּׁנָּתַן לוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הוֹרִיד מִמֶּנּוּ מַה שֶּׁנָּתַן לוֹ, וּשְׁנֵיהֶם הִפְשִׁיטוּ אֶת אַהֲרֹן מֵהַכֹּל, וּמֹשֶׁה הוֹרִיד מִבַּחוּץ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִבִּפְנִים. וְעַד שֶׁמֹּשֶׁה הוֹרִיד, הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא הוֹרִיד. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה."],[4,"","אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִּכְבוֹדָם. הִתְקִין הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַהֲרֹן מִטָּה וּמְנוֹרַת זָהָב שֶׁמְּאִירָה. וּמִשֶּׁלּוֹ לָקַח, מֵאוֹתָהּ מְנוֹרָה שֶׁהִדְלִיק בְּכָל יוֹם פַּעֲמַיִם, וְנִסְתַּם פִּי הַמְּעָרָה וְיָרְדוּ."],[5,"","רַבִּי יְהוּדָה אָמַר, פִּי הַמְּעָרָה הָיָה פָּתוּחַ, שֶׁכָּל יִשְׂרָאֵל רָאוּ אֶת אַהֲרֹן שׁוֹכֵב וְנֵר הַמְּנוֹרָה דּוֹלֵק לְפָנָיו, וּמִטָּתוֹ יוֹצֵאת וְנִכְנֶסֶת, וְעָנָן אֶחָד עוֹמֵד עָלָיו. וְאָז יָדְעוּ יִשְׂרָאֵל שֶׁהֲרֵי מֵת אַהֲרֹן, וְרָאוּ שֶׁהֲרֵי הִסְתַּלְּקוּ עַנְנֵי הַכָּבוֹד. זֶהוּ שֶׁכָּתוּב וַיִּרְאוּ כָּל הָעֵדָה כִּי גָוַע אַהֲרֹן וְגוֹ', וַהֲרֵי פֵּרְשׁוּהָ. וְעַל זֶה בָּכוּ לְאַהֲרֹן כָּל בֵּית יִשְׂרָאֵל, גְּבָרִים וְנָשִׁים וָטַף, שֶׁהֲרֵי אָהוּב מִכֻּלָּם הָיָה."],[6,"","רַבִּי שִׁמְעוֹן אָמַר, שְׁלֹשֶׁת אַחִים עֶלְיוֹנִים קְדוֹשִׁים אֵלּוּ לָמָּה לֹא נִקְבְּרוּ בְמָקוֹם אֶחָד, וְהָאֵיבָרִים הִתְפַּזְּרוּ, אֶחָד כָּאן וְאֶחָד כָּאן וְאֶחָד בְּמָקוֹם אַחֵר? אֶלָּא יֵשׁ אוֹמְרִים, בְּמָקוֹם שֶׁצְּרִיכִים יִשְׂרָאֵל לְהִסְתַּכֵּן בּוֹ, מֵת כָּל אֶחָד וְאֶחָד, בִּשְׁבִיל לְהָגֵן עֲלֵיהֶם, וְנִצְּלוּ. אֲבָל כָּל אֶחָד וְאֶחָד מֵת כָּרָאוּי עֲלֵיהֶם. מִרְיָם בְּקָדֵשׁ, בֵּין צָפוֹן לְדָרוֹם. אַהֲרֹן לְצַד יָמִין. מֹשֶׁה כָּרָאוּי לוֹ. אָחַז אוֹתוֹ הַר לְהַר אַהֲרֹן, וְכָנַס לִקְבוּרַת מִרְיָם לְגַבֵּי אוֹתוֹ הָהָר, אָחַז לִשְׁנֵי צְדָדִים. וְעַל זֶה נִקְרָא (דברים לב) הַר הָעֲבָרִים, שֶׁשְּׁנֵי צִדֵּי הָהָר שֶׁעוֹבְרִים, וְאָחַז לְצַד זֶה וּלְצַד זֶה."],[7,"","אַשְׁרֵי חֵלֶק הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. וְאַף עַל גַּב שֶׁהֵם בְּמָקוֹם אַחֵר, בְּעוֹלָם אַחֵר עֶלְיוֹן, זְכוּתָם עוֹמֶדֶת בָּעוֹלָם הַזֶּה לְדוֹרֵי דוֹרוֹת. וּבְשָׁעָה שֶׁיִּשְׂרָאֵל חוֹזְרִים בִּתְשׁוּבָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּגְזֵרָה נִגְזֶרֶת עֲלֵיהֶם, אָז קוֹרֵא הַקָּדוֹשׁ בָּרוּךְ הוּא לַצַּדִּיקִים שֶׁעוֹמְדִים לְפָנָיו לְמַעְלָה וּמוֹדִיעַ לָהֶם, וְהֵם מְבַטְּלִים אוֹתָהּ גְּזֵרָה, וְחָס הַקָּדוֹשׁ בָּרוּךְ הוּא עַל יִשְׂרָאֵל. אַשְׁרֵי הַצַּדִּיקִים, שֶׁעֲלֵיהֶם כָּתוּב (ישעיה נח) וְנָחֲךְ ה' תָּמִיד וְגוֹ'."],[8,"","וַיְדַבֵּר הָעָם בֵּאלֹהִים וּבְמֹשֶׁה וְגוֹ'. פָּרָשָׁה זוֹ בְּמָקוֹם אַחֵר עָלְתָה עִם אוֹתָם מֵי מְרִיבָה שֶׁל מֹשֶׁה וְאַהֲרֹן."]]],[["רִבִּי יִצְחָק פָּתַח, (אסתר ה׳:א׳) וַיְהִי בַּיוֹם הַשְּׁלִישִׁי וַתִּלְבַּשׁ אֶסְתֵּר מַלְכוּת וְגוֹ'. מְגִּלַת אֶסְתֵּר בְּרוּחַ הַקֹּדֶשׁ נֶאֶמְרָה, וּבְגִין כַּךְ כְּתוּבָה בֵּין הַכְּתוּבִים. וַיְהִי בַּיוֹם הַשְּׁלִישִׁי, דְּאִתְחֲלָשׁ חֵילָא דְּגוּפָא, וְהָא קַיְּימָא בְּרוּחָא בְּלָא גּוּפָא, כְּדֵין וַתִּלְבַּשׁ אֶסְתֵּר מַלְכוּת. מַאי (קפ\"ט ע\"ב) מַלְכוּת. אִי תֵּימָא בִּלְבוּשֵׁי יְקָר וְאַרְגְּוָונָא, הָא לָאו הָכִי אִקְרֵי. אֶלָּא וַתִּלְבַּשׁ אֶסְתֵּר מַלְכוּת, דְּאִתְלַבְּשַׁת בְּמַלְכוּת עִלָּאָה קַדִּישָׁא, וַדַּאי לָבְשָׁה רוּחַ הַקֹּדֶשׁ. מַאי טַעֲמָא זָכְתָה לְהַאי אֲתָר. בְּגִין דְּנַטְרָא פּוּמָה דְּלָא לְחַוָואָה מִדִי. הֲדָא הוּא דִכְתִיב, (אסתר ב׳:כ׳) אֵין אֶסְתֵּר מַגֶּדֶת מוֹלַדְתָּה. וְאוֹלִיפְנָא כָּל מַאן דְּנָטִיר פּוּמֵיהּ וְלִישָׁנֵיהּ, זָכֵי לְאִתְלַבְּשָׁא בְּרוּחַ דְּקוּדְשָׁא. וְכָל מַאן דְּסָטֵי פּוּמֵיהּ לְמִלָּה בִּישָׁא, הָא וַדַּאי הַהוּא מִלָּה בִּישָׁא עָלֵיהּ. (ס\"א ואי לאו), וְאִי תֵּימָא הָא נְגָעִים, אוֹ צָרַעַת, דְּמוֹקְדָן כְּחִוְיָא עָלֵיהּ, וְהָא אוּקְמוּהָ.","וַיְדַבֵּר הָעָם בֵּאלֹהִים וּבְמֹשֶׁה. דְּאָמְרוּ מִלָּה בִּישָׁא בְּקוּדְשָׁא בְּרִיךְ הוּא, וּכְתַרְגּוּמוֹ. וְעִם מֹשֶׁה נָצוּ. לָמָּה הֶעֱלִיתוּנוּ, שַׁווּ כָּל אַפַּיָיא שַׁוְּויָן בְּגִין כָּךְ אִזְדְּמַן לְגַבַּיְיהוּ חִוְויָין, דְּמוֹקְדָן לוֹן כְּאֶשָּׁא, וְעַיִּיל אֶשָּׁא לְמֵעַיְיהוּ וְנַפְלִין מֵתִין, כְּמָה דְאַתְּ אָמֵר וַיְשַׁלַח יְיָ בָּעָם אֵת הַנְחָשִׁים הַשְּׂרָפִים.","רִבִּי חִיָּיא אָמַר, חִוְויָן הֲווֹ אַתְיָין, מְלַחֲשָׁן בְּפוּמַיְיהוּ, וְנַשְׁכִין וּמֵתִין. מַאי מְלַחֲשָׁן. כְּמָה דְאַתְּ אָמֵר (קהלת י׳:י״א) אִם יִשּׁוֹךְ הַנָּחָשׁ בְּלֹא לָחַשׁ. אֶשָּׁא הֲווֹ מְלַהֲטָן בְּפוּמַיְיהוּ, וְנַשְׁכִן, וְשַׁדְיָין אֶשָּׁא בְּהוּ, וְאִתּוֹקְדָאן מֵעַיְיהוּ וּמֵתִין וְהָא מִלִּין אִלֵּין אִסְתְּלָקוּ לַאֲתָר אַחֲרָא.","(במדבר כ״א:ט״ז) וּמִשָׁם בְּאֵרָה הִוא הַבְּאֵר. מַאי שְׁנָא דְּהָכָא בְּאֵרָה, וּלְבָתַר בְּאֵר. אֶלָּא בְּאֵרָה, לְבָתַר דְּמִתְכַּנְשֵׁי מַיָּיא לְגוֹ יַמָּא, וְנַחְתֵּי לְתַתָּא. בְּאֵר, בְּשַׁעֲתָא דְּיִצְחָק מַלְּיָיא לֵיהּ. הִיא הַבְּאֵר, הוּא כְּתִיב וְרָזָא דָּא, כְּמָה דִּכְתִּיב, (במדבר י״ח:כ״ג) וְעָבַד הַלֵּוִי הוּא.","רִבִּי אַבָּא אָמַר, בְּכָל אֲתָר הוּא, וְקָרֵינָן הִיא, דְּכַר וְנוּקְבָּא כַּחֲדָא. וּכְלָלָא עִלָּאָה, ה' נוּקְבָּא, ו' (רפ\"ה ע\"ב, פקודי רל\"ה ע\"ב) דְּכַר, א' כְּלָלָא דְּכֹלָּא. דְּהָא א' בִּשְׁלִימוּ שַׁרְיָא. זַכָּאִין אִינּוּן יִשְׂרָאֵל, אַף עַל גַּב דְּאִינּוּן לְתַתָּא, אִינּוּן אֲחִידָן בִּכְלָלָא עִלָּאָה דְּכֹלָּא, וּבְגִין כָּךְ כְּתִיב (תהלים ק) הוּא עָשָׂנוּ וְלֹא אֲנָחְנוּ, בְּאָלֶף כְּתִיב. כְּלָלָא דְּו\"ה וְא' דְּכָלִיל כֹּלָּא.","רַבִּי שִׁמְעוֹן אָמַר, רוּחַ דְּמַיָּא, דָּא הוּא רוּחַ הַקֹּדֶשׁ, דְּנָשַׁב בְּקַדְמִיתָא. כְּמָה דְאַתְּ אָמֵר (שיר השירים ד׳:ט״ז) הָפִיחִי גַנִּי, לְבָתַר נַזְלִין מַיָּיא לְמַלְיָּא לָהּ, (כלא) הֲדָא הוּא דִכְתִיב, (תהילים קמ״ז:י״ח) יַשֵּׁב רוּחוֹ יִזְּלוּ מָיִם. יַשֵּׁב רוּחוֹ בְּקַדְמִיתָא, וּלְבָתַר יִזְּלוּ מָיִם. וְעַד לָא נָשִׁיב הַאי רוּחָא, לָא נַזְלִין מַיָּיא. מַאי קָא מַשְׁמַע לָן, מַשְׁמַע דְּבָעֵי בְּכֹלָּא לְאַתְּעָרָא מִלָּה, בְּעוֹבָדָא אוֹ בְּמִלָּה, אוֹ לְאִתְחֲזָאָה כְּחֵיזוּ דְּעוֹבָדָא. וְהָכָא, עַד דְּרוּחָא לָא נָשִׁיב, לָא נַזְלִין מַיָּיא לְגַבֵּיהּ דְּהַהוּא רוּחַ.","הוּא הַבְּאֵר, הִיא הַבְּאֵר קָרֵינָן, מַאי שְׁנָא בְּקַדְמִיתָא בְּאֵרָה, וְהַשְׁתָּא בְּאֵר, אֶלָּא בְּקַדְמִיתָא נוּקְבָּא בִּלְחוֹדָהָא, וְהַשְׁתָּא דְּקָאָמַר הוּא, כְּלָלָא דִּדְכַר וְנוּקְבָּא, אִקְרֵי בְּאֵר. וּבַאֲתָר דְּאִשְׁתְּכַח דְּכַר, אֲפִילּוּ מְאָה נוּקְבָּא, דְּכַר קָרֵינָן לְכֹלָּא.","אֲשֶׁר אָמַר יְיָ לְמֹשֶׁה אֱסוֹף אֶת הָעָם, בְּגִין דְּהַאי בְּאֵר לָא אַעְדֵּי (באר) מִנַּיְיהוּ. וְאִי תֵּימָא, הֵיךְ יַכְלִין לְשָׁאֲבָא מִנֵּיהּ כֹּלָּא, אֶלָּא אִיהוּ נָפִיק לִתְלֵיסַר נַחֲלִין, וּנְבִיעַ אִתְמְלֵּי וְנָפִיק לְכָל סִטְרִין, וּכְדֵין הֲווֹ יִשְׂרָאֵל בְּשַׁעֲתָא דְּשָׁארָן וּבַעְיָין מַיָּיא, קַיְימִין עָלֵיהּ, וְאַמְרֵי שִׁירָתָא. וּמַה אַמְרֵי, עֲלִי בְאֵר. סַלְקִי מֵימַיִךְ, לְאַנְפָּקָא מַיִין לְכֹלָּא, וּלְאִתְשָׁקָאָה מִנָךְ. וְכֵן אַמְרֵי תּוּשְׁבַּחְתָּא דְּהַאי בְּאֵר, בְּאֵר חֲפָרוּהָ שָׂרִים וְגוֹ'. מִלָּה קְשׁוֹט הֲווֹ אַמְרֵי, וְכַךְ הוּא.","מֵהָכָא אוֹלִיפְנָא (נ\"א תא חזי), כָּל מַאן דְּבָעֵי לְאַתְּעָרָא מִלִּין דִּלְעֵילָּא, בֵּין בְּעוֹבָדָא בֵּין בְּמִלָּה. אִי הַהוּא עוֹבָדָא, אוֹ הַהוּא מִלָּה, לָא אִתְעָבִיד כַּדְּקָא יָאוּת, לָא אִתְּעַר מִדִי. כָּל בְּנֵי עָלְמָא אַזְלִין לְבֵי כְּנִישְׁתָּא לְאַתְּעָרָא מִלָּה דִּלְעֵילָּא, אֲבָל זְעִירִין אִינּוּן דְּיַדְעִין לְאַתְּעָרָא, וְקוּדְשָׁא בְּרִיךְ הוּא קָרִיב לְכֹלָּא דְּיַדְעֵי לְמִקְרֵי לֵיהּ וּלְאַתְעֲרָא מִלָּה כַּדְּקָא יָאוּת, אֲבָל אִי לָא יַדְעֵי לְמִקְרֵי לֵיהּ, לָאו אִיהוּ קָרִיב, דִּכְתִּיב (תהילים קמ״ה:ט׳) קָרוֹב יְיָ לְכָל קוֹרְאָיו וְגוֹ'. מַאי בֶאֱמֶת. דְּיַדְעֵי לְאַתְּעָרָא מִלָּה דִּקְשׁוֹט כַּדְּקָא יָאוּת, וְכֵן בְּכֹלָּא."],[[0,"","[א] \u0003ר' יצחק פתח וכו':\u0004 רי\"פ, ויהי ביום השלישי ותלבש אסתר מלכות וגו'. מגלת אסתר נאמרה ברוח הקדש, וע\"כ כתובה בין הכתובים. ויהי ביום השלישי, שנחלש כח הגוף, מחמת התענית, ועמדה ברוח בלא גוף, אז ותלבש אסתר מלכות. מהו מלכות, אם תאמר בלבושי יקר וארגמן, אלו אינן נקראים כן. בשם מלכות. אלא ותלבש אסתר מלכות, פירושו, שנתלבשה במלכות העליונה הקדושה, ודאי שלבשה רוח הקודש, כי המלכות נקראת רוח הקודש."],[0,"","[ב] \u0003מאי טעמא זכתה וכו':\u0004 מהו הטעם שזכתה למקום זה, דהיינו למלכות, הוא משום ששמרה פיה שלא להגיד כלום. ז\"ש אין אסתר מגדת מולדתה. ולמדנו כל מי ששומר פיו ולשונו, זוכה להתלבש ברוח הקודש. וכל מי שמטה פיו לדבר רע, הרי ודאי, שדבר ההוא הרע עליו. כלומר אם מדבר לשון הרע כנחש הקדמוני הרי אותו הנחש שולט עליו. וע\"כ ישראל שדברו באלקים ומשה, שלח עליהם נחשים השרפים. ואם לא, הרי נגעים או צרעת שורפת כנחש, בא עליו. וכבר העמדנו."],[1,"וידבר העם באלקים ובמשה:","שאמרו דבר רע על הקב\"ה, וכתרגומו, שעל וידבר וגו', מתרגם ואתרעם וכו' ועם משה נצו. \u0003למה העליתנו,\u0004 עשו כל פנים שוים, שהשוו את אלקים ומשה, לומר להם \u0003למה העליתנו\u0004. משום זה נשלח עליהם נחשים השורפים אותם כאש, ונכנס האש למעיהם, ונפלו מתים. כש\"א, וישלח ה' בעם את הנחשים השרפים."],[2,"ר' חייא אמר וכו':","רח\"א נחשים היו באים ופיותיהם היו מלחשים, ונושכים ומתים. מהו מלחשים. הוא כש\"א, אם ישוך הנחש בלא לחש. אש היתה לוהטת בפיותיהם. ונשכו, ושלחו את האש בהם, ונשרפו מעיהם ומתים. והרי דברים אלו נתבארו במקום אחר."],[3,"ומשם בארה הוא הבאר:","שואל, מה השינוי שכאן כתוב בארה ואחר כך כתוב באר. ומשיב, אלא בארה נקראת המלכות אחר שכבר נאספו המים לתוך הים וירדו למטה, למקום המלכות. באר נקראת המלכות, בשעה שיצחק, שהוא קו השמאל דז\"א, ממלא אותו. וכיון שהבאר עוד נמצאת בפעולת ז\"א, ע\"כ נקראת באר בלא ה'. שהוא לשון זכר. וע\"כ, \u0003היא הבאר\u0004 הכתיב הוא, \u0003הוא\u0004 הבאר, עם \u0003ו',\u0004 שהוא לשון זכר. והסוד הוא כמ\"ש, ועבד הלוי \u0003הוא.\u0004 שהוא רומז על צד שמאל דז\"א (כנ\"ל קרח אות מ')."],[4,"רבי אבא אמר וכו':","רא\"א, בכל מקום שהכתיב הוא, \u0003הוא.\u0004 והקרי הוא, \u0003היא.\u0004 כמו כאן בבאר, יורה על דכד ונוקבא יחד, וג' אותיות הוא, הן כלל עליון, \u0003ה'\u0004 היא נוקבא, מלכות. \u0003ו'\u0004 היא דכר, ז\"א. \u0003א'\u0004 היא בינה, שהיא כלל הכל, כי ז\"א ונוקבא יוצאים ממנה. כי \u0003א',\u0004 שהיא בינה, היא שלמות הכל. שכל המוחין יוצאים ממנה. אשרי הם ישראל, אע\"פ שהם למטה, הם אחוזים בכלל עליון של הכל, דהיינו בג' אותיות ה' ו' א', ומשום זה כתוב, \u0003הוא\u0004 עשנו ולא אנחנו, ו \u0003לא,\u0004 כתוב ב \u0003א'\u0004 שמורה ול \u0003א'\u0004 אנחנו, שהיא כלל של \u0003ו\"ה\u0004 שהם זו\"נ, וה \u0003א'\u0004 היא כלל הכל."],[5,"ר\"ש אמר רוח וכו':","ר' שמעון אמר הרוח שבמים, זה הוא רוח הקדש, דהיינו הרוח שבמלכות הנקראת רוח הקדש, שהוא נושב בתחלה, כש\"א \u0003הפיחי גני,\u0004 דהיינו שמעלה מ\"ן, ואח\"כ \u0003יזלו מים,\u0004 שהם מים עליונים דכורין. למלאות אותה. ז\"ש, ישב רוחו יזלו מים, תחלה, ישב רוחו, ואח\"כ יזלו מים. וכל עוד שאינו נושב רוח הזה אין המים נוזלים. מה משמיענו בזה. מזה משמע, שצריכים בכל, לעורר דבר מלמטה, שהיא בבחינת מ\"ן, במעשה או בדבור, או להראות כעין מעשה, ואח\"כ בא ההתעוררות של מעלה. וע\"כ כאן, כל עוד שהרוח לא נשב אין המים שה\"ס השפע, נוזלים אל רוח הזה. שהוא המלכות."],[6,"הוא הבאר היא וכו':","הוא הבאר כתוב, היא הבאר אנו קוראים. וכן מהו השינוי שכתוב בתחלה בארה, ועתה באר. ומשיב, אלא בתחילה היתה הנוקבא, שהיא המלכות, בלבדה, וע\"כ נאמר בארה, לשון נקבה, ועתה שאומר \u0003הוא\u0004 שיורה כלל דכר ונוקבא (כבאות ע\"ד) היא נקראת באר. לשון זכר. ואע\"פ שכולל גם הנוקבא, כתוב בלשון זכר, כי במקום שנמצא זכר, אפילו יש עמו מאה נקבות, קוראים לכולם בלשון זכר."],[7,"אשר אמר ה' וגו':","כתוב הוא הבאר אשר אמר ה' למשה אסוף את העם. הוא משום שבאר הזו לא נעדר מהם. ואם תאמר, איך היו יכולים כולם לשאוב ממנו. אלא שהוא יצא לי\"ג נחלים, שהמלכות מתחלקת לי\"ג, בסוד י\"ב שמקבלת מי\"ב גבולים שבז\"א, ואחד כולל כולם. והנביע שבבאר מתמלא ויוצא לכל הצדדים. ואז בשעה ששרו ישראל ורצו מים, היו ישראל עומדים עליה, על הבאר, ואמרו שירה. ומה אמרו, \u0003עלי באר.\u0004 העלי מימך להוציא מים לכל, להשקות ממך. וכן אומרים השבח של באר הזו, דהיינו, באר חפרוה שרים וגו'. דבר אמת היו אומרים, וכך הוא."],[8,"מהכא אוליפנא כל וכו':","מכאן למדנו, שכל מי שרוצה לעורר דברים שלמעלה, בין במעשה בין בדבור, אם מעשה ההוא או דבור ההוא לא נעשה כראוי, אינו מתעורר כלום. כל בני העולם הולכים לבית הכנסת לעורר דבר שלמעלה, אבל מועטים הם שיודעים לעורר. והקב\"ה קרוב לכל אלו שיודעים לקראו, ולעורר דבר כראוי. אבל אם אינם יודעים לקראו, הוא אינו קרוב, שכתוב קרוב ה' לכל קוראיו לכל אשר יקראוהו באמת. מהו באמת, היינו שיודעים לעורר דבר אמת כראוי. וכן בכל דבר."]],[[0,"","רַבִּי יִצְחָק פָּתַח, (אסתרה) וַיְהִי בַּיּוֹם הַשְּׁלִישִׁי וַתִּלְבַּשׁ אֶסְתֵּר מַלְכוּת וְגוֹ'. מְגִלַּת אֶסְתֵּר בְּרוּחַ הַקֹּדֶשׁ נֶאֶמְרָה, וּמִשּׁוּם זֶה כְּתוּבָה בֵּין הַכְּתוּבִים. וַיְהִי בַּיּוֹם הַשְּׁלִישִׁי, שֶׁנֶּחֱלָשׁ כֹּחַ הַגּוּף, וַהֲרֵי קַיָּם בָּרוּחַ בְּלֹא גוּף, אָז - וַתִּלְבַּשׁ אֶסְתֵּר מַלְכוּת. אֵיזוֹ מַלְכוּת? אִם תֹּאמַר בִּלְבוּשׁ כָּבוֹד וְאַרְגָּמָן, הֲרֵי לֹא כָּךְ נִקְרָא. אֶלָּא וַתִּלְבַּשׁ אֶסְתֵּר מַלְכוּת, שֶׁהִתְלַבְּשָׁה בְמַלְכוּת עֶלְיוֹנָה קְדוֹשָׁה, וַדַּאי לָבְשָׁה רוּחַ הַקֹּדֶשׁ. מָה הַטַּעַם זָכְתָה לְמָקוֹם זֶה? מִשּׁוּם שֶׁשָּׁמְרָה פִיהָ שֶׁלֹּא לְהַרְאוֹת דָּבָר. זֶהוּ שֶׁכָּתוּב (אסתר ב) אֵין אֶסְתֵּר מַגֶּדֶת מוֹלַדְתָּהּ. וְלָמַדְנוּ, כָּל מִי שֶׁשּׁוֹמֵר פִּיו וּלְשׁוֹנוֹ, זוֹכֶה לְהִתְלַבֵּשׁ בְּרוּחַ הַקֹּדֶשׁ. וְכָל מִי שֶׁסּוֹטֶה פִיו לְדָבָר רָע, הֲרֵי וַדַּאי אתוֹ דָּבָר רָע עָלָיו. (ואם לא,) הֲרֵי נְגָעִים אוֹ צָרַעַת שֶׁשּׂוֹרְפִים כְּנָחָשׁ עָלָיו, וַהֲרֵי פֵּרְשׁוּהוּ."],[1,"","וַיְדַבֵּר הָעָם בֵּאלֹהִים וּבְמֹשֶׁה, שֶׁאָמְרוּ דָבָר רָע בַּקָּדוֹשׁ-בָּרוּךְ- הוּא, וּכְתַרְגּוּמוֹ - וְעִם מֹשֶׁה נְצוּ. לָמָּה הֶעֱלִיתֻנוּ, שָׂמוּ כָּל הַפָּנִים שָׁווֹת, בִּגְלַל זֶה הִזְדַּמְּנוּ לָהֶם נְחָשִׁים, שֶׁשּׂוֹרְפִים אוֹתָם כָּאֵשׁ וּמַכְנִיסִים אֵשׁ לִמְעֵיהֶם וְנוֹפְלִים מֵתִים, כְּמוֹ שֶׁנֶּאֱמַר וַיְשַׁלַּח ה' בָּעָם אֵת הַנְּחָשִׁים הַשְּׂרָפִים."],[2,"","רַבִּי חִיָּיא אָמַר, נְחָשִׁים הָיוּ בָאִים, מְלַחֲשִׁים בְּפִיהֶם, וְנוֹשְׁכִים וּמֵתִים. מַה מְלַחֲשִׁים? כְּמוֹ שֶׁנֶּאֱמַר (קהלת י) אִם יִשֹּׁךְ הַנָּחָשׁ בְּלוֹא לָחַשׁ. אֵשׁ הָיוּ מְלַהֲטִים בְּפִיהֶם, וְנוֹשְׁכִים וְזוֹרְקִים בָּהֶם אֵשׁ, וּמְעֵיהֶם יוֹקְדִים וּמֵתִים. וַהֲרֵי דְּבָרִים אֵלּוּ עָלוּ לְמָקוֹם אַחֵר."],[3,"","וּמִשָּׁם בְּאֵרָה הִוא הַבְּאֵר. מַה שּׁוֹנֶה שֶׁכָּאן בְּאֵרָה וְאַחַר כָּךְ בְּאֵר? אֶלָּא בְּאֵרָה, לְאַחַר שֶׁמִּתְכַּנְּסִים הַמַּיִם לְתוֹךְ הַיָּם וְיוֹרְדִים לְמַטָּה. בְּאֵר, בְּשָׁעָה שֶׁיִּצְחָק מְמַלֵּא אוֹתָם. הִוא הַבְּאֵר, הוּא כָּתוּב, וְסוֹד זֶה כְּמוֹ שֶׁכָּתוּב (במדבר יח) וְעָבַד הַלֵּוִי הוּא."],[4,"","רַבִּי אַבָּא אָמַר, בְּכָל מָקוֹם הוּא, וְקוֹרְאִים הִיא - זָכָר וּנְקֵבָה כְּאֶחָד. וּכְלָל עֶלְיוֹן - ה' נְקֵבָה, ו' זָכָר, א' כְּלַל הַכֹּל, שֶׁהֲרֵי א' בִּשְׁלֵמוּת שׁוֹרָה. אַשְׁרֵיהֶם יִשְׂרָאֵל. אַף עַל גַּב שֶׁהֵם לְמַטָּה, הֵם אֲחוּזִים בַּכְּלָל הָעֶלְיוֹן שֶׁל הַכֹּל, וּמִשּׁוּם זֶה כָּתוּב (תהלים ק) הוּא עָשָׂנוּ וְלֹא אֲנַחְנוּ, בְּאָלֶף כָּתוּב. כְּלַל שֶׁל ו\"ה, וְא' שֶׁכּוֹלֵל הַכֹּל."],[5,"","רַבִּי שִׁמְעוֹן אָמַר, רוּחַ הַמַּיִם זוֹהִי רוּחַ הַקֹּדֶשׁ שֶׁנָּשְׁבָה בַּהַתְחָלָה, כְּמוֹ שֶׁנֶּאֱמַר (שיר השירים ד) הָפִיחִי גַנִּי. אַחַר כָּךְ נוֹזְלִים מַיִם לְמַלֵּא אוֹתָהּ (כלה), זֶהוּ שֶׁכָּתוּב (תהלים קמז) יַשֵּׁב רוּחוֹ יִזְּלוּ מָיִם. יַשֵּׁב רוּחוֹ בַּהַתְחָלָה, וְאַחַר כָּךְ יִזְּלוּ מָיִם. וְעַד שֶׁלֹּא נוֹשֶׁבֶת רוּחַ זוֹ, לֹא נוֹזְלִים מַיִם. מַה בָּא לְהַשְׁמִיעֵנוּ? מַשְׁמִיעַ שֶׁצָּרִיךְ בַּכֹּל לְעוֹרֵר הַדָּבָר, בְּמַעֲשֶׂה אוֹ בְדָבָר, אוֹ לְהַרְאוֹת כְּמַרְאֵה הַמַּעֲשֶׂה. וְכָאן, עַד שֶׁרוּחַ לֹא נוֹשֶׁבֶת, לֹא נוֹזְלִים אֵלֶיהָ מַיִם לְגַבֵּי אוֹתָהּ הָרוּחַ."],[6,"","הוּא הַבְּאֵר, קוֹרְאִים הִיא הַבְּאֵר. מַה שּׁוֹנֶה שֶׁבַּהַתְחָלָה בְּאֵרָה וְכָאן בְּאֵר? אֶלָּא בַּהַתְחָלָה נְקֵבָה לְבַדָּהּ, וְכָעֵת שֶׁאָמַר הוּא - כְּלָל שֶׁל זָכָר וּנְקֵבָה - נִקְרָא בְּאֵר. וּבְמָקוֹם שֶׁנִּמְצָא זָכָר, אֲפִלּוּ (מאה) מִלָּה נְקֵבָה, נִקְרָא זָכָר לַכֹּל."],[7,"","אֲשֶׁר אָמַר ה' לְמֹשֶׁה אֱסֹף אֶת הָעָם, מִשּׁוּם שֶׁבְּאֵר זוֹ לֹא זָזָה (באר) מֵהֶם. וְאִם תֹּאמַר, אֵיךְ יָכְלוּ לִשְׁאֹב מִמֶּנָּה כֻּלָּם? אֶלָּא הוּא מוֹצִיא לִשְׁלֹשָׁה עָשָׂר נְחָלִים, וְהַמַּעְיָן מִתְמַלֵּא וְיוֹצֵא לְכָל הַצְּדָדִים, וְאָז הָיוּ יִשְׂרָאֵל בְּשָׁעָה שֶׁחוֹנִים וְרוֹצִים מַיִם, עוֹמְדִים עָלֶיהָ וְאוֹמְרִים שִׁירָה. וּמָה אוֹמְרִים? עֲלִי בְאֵר. הַעֲלִי מֵימַיִךְ לְהוֹצִיא מַיִם לַכֹּל וְלִהְיוֹת מֻשְׁקִים מִמֵּךְ. וְכֵן אוֹמְרִים שֶׁבַח שֶׁל בְּאֵר זֹּאת, בְּאֵר חֲפָרוּהָ שָׂרִים וְגוֹ'. דְּבַר אֱמֶת הָיוּ אוֹמְרִים, וְכָךְ הוּא."],[8,"","מִכָּאן לָמַדְנוּ (בא ראה), כָּל מִי שֶׁרוֹצֶה לְעוֹרֵר דְּבָרִים שֶׁל מַעְלָה, בֵּין בְּמַעֲשֶׂה בֵּין בְּדִבּוּר - אִם אוֹתוֹ מַעֲשֶׂה אוֹ אוֹתוֹ דִּבּוּר לֹא נַעֲשֶׂה כָּרָאוּי, לֹא מְעוֹרֵר דָּבָר. כָּל בְּנֵי הָעוֹלָם הוֹלְכִים לְעוֹרֵר בְּבֵית הַכְּנֶסֶת דָּבָר שֶׁלְּמַעְלָה, אֲבָל מְעַטִּים אֵלּוּ שֶׁיּוֹדְעִים לְעוֹרֵר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא קָרוֹב לְכָל הַיּוֹדְעִים לִקְרֹא לוֹ וּלְעוֹרֵר הַדָּבָר כָּרָאוּי. אֲבָל אִם לֹא יוֹדְעִים לִקְרֹא לוֹ, הוּא אֵינוֹ קָרוֹב, שֶׁכָּתוּב (שם קמה) קָרוֹב ה' לְכָל קֹרְאָיו וְגוֹ'. מַה זֶּה בֶּאֱמֶת? שֶׁיּוֹדְעִים לְעוֹרֵר דְּבַר אֱמֶת כָּרָאוּי, וְכֵן בַּכֹּל."]]],[["אוּף הָכָא, הֲווֹ אַמְרֵי יִשְׂרָאֵל הָנֵי מִלִּין, מִלִּין דִּקְשׁוֹט, בְּגִין לְאַתְּעָרָא לְהַאי בֵּירָא, וּלְאַשְׁקָאָה לוֹן לְיִשְׂרָאֵל, וְעַד דְּאַמְרֵי הָנֵי מִלֵּי לָא אִתְּעַר. וְכֵן אֲפִילּוּ בְּאִינּוּן חֲרָשֵׁי עָלְמָא, דְּמִשְׁתַּמְשֵׁי בְּזִינִין בִּישִׁין, עַד דְּעַבְדֵּי עוֹבָדוֹי דִּקְשׁוֹט לְגַבַּיְיהוּ, אִי לָא אָמְרוּ מִלֵּי דִּקְשׁוֹט, בְּגִין לְאַמְשָׁכָא לוֹן בְּהָנֵי גְּוָונָא דְּבַעְיָין, לָא מִתְעָרִין לְגַבַּיְיהוּ, וַאֲפִילּוּ דְּצַוְוחֵי כָּל יוֹמָא בְּמִלִּין אַחֲרָנִין, אוֹ בְּעוֹבָדָא אַחֲרָא, לָא מַשְׁכִין לוֹן לְגַבַּיְיהוּ לְעָלְמִין, וְלָא מִתְעָרִין לָקֳּבְלַיְיהוּ.","תָּא חֲזֵי, כְּתִיב, (מלכים א י״ח:כ״ו) וְיִקְרְאוּ בְשֵׁם הַבַּעַל וְגוֹ'. מַאי טַעֲמָא. חַד דְּלָאו רְשׁוּ בְּהַהוּא בַּעַל בְּהַאי. וְעוֹד דְּמִלִּין לָא מִתְכַּשְּׁרָן בֵּינַיְיהוּ, וְאַנְשֵׁי לוֹן קוּדְשָׁא בְּרִיךְ הוּא מִנְּהוֹן. הֲדָא הוּא דִכְתִיב, (מלכים א י״ח:ל״ז) וְאַתָּה הַסִבּוֹתָ אֶת לִבָּם אֲחוֹרַנִּית. זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּיַדְעֵי לְמִקְרֵי לְמָארֵיהוֹן כַּדְּקָא יָאוּת.","אָמַר רִבִּי שִׁמְעוֹן, הָכָא בָּעֵינָא לְגַלָּאָה מִלָּה. תָּא חֲזֵי, כָּל מַאן דְּיָדַע לְסַדְּרָא עוֹבָדָא כַּדְּקָא יָאוּת, וּלְסַדְּרָא מִלִּין כַּדְּקָא יָאוּת, הָא ודַּאי מַתְעָרֵי לְּקוּדְשָׁא בְּרִיךְ הוּא, לְאַמְשָׁכָא מִלִּין עִלָּאִין דְּמִתְכַּשְׁרָן. (ס\"א ואי לא, לא אתכשר לגבייהו). וְלָא אִכְשַׁר לְגַבַּיְיהוּ אִי הָכִי כָּל עָלְמָא יַדְעֵי לְסַדְּרָא עוֹבָדָא, וּלְסַדְּרָא מִלִּין, מַאי חָשִׁיבוּ דִּלְהוֹן דְּצַדִּיקַיָּיא, דְּיַדְעֵי עִקָּרָא דְּמִלָּה וְעוֹבָדָא, וְיַדְעֵי לְכַוְּונָא לִבָּא וּרְעוּתָא, יַתִּיר מֵאִלֵּין אַחֲרָנִין, דְּלָא יַדְעֵי כָּל כַּךְ.","אֶלָּא אִלֵּין דְּלָא יַדְעֵי עִקָּרָא דְּעוֹבָדָא כּוּלֵי הַאי, אֶלָּא סִדּוּרָא בְּעָלְמָא וְלָא יַתִּיר, מַשְׁכִין עָלַיְיהוּ מְשִׁיכוּ דְּבָתַר כַּתְפוֹי דְקוּדְשָׁא בְּרִיךְ הוּא, דְּלָא טָס בַּאֲוִירָא דִּשְׁגִּיחוּ אִקְרֵי.","וְאִלֵּין דְּיַדְעֵי וּמְכַוְּונֵי לִבָּא וּרְעוּתָא, מַפְּקֵי בִּרְכָאן מֵאֲתָר דְּמַחֲשָׁבָה, וְנָפְקֵי בְּכָל גִּזְעִין וְשָׁרָשִׁין בְּאֹרַח מֵישָׁר כַּדְּקָא יָאוּת, עַד דְּמִתְבָּרְכִן עִלָּאִין וְתַתָּאִין, וּשְׁמָא קַדִּישָׁא עִלָּאָה מִתְבָּרַךְ עַל יְדֵיהוֹן. זַכָּאָה חוּלָקֵיהוֹן. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא קָרִיב לְגַבֵּיהוֹן, וְזַמִּין לָקֳבְלֵיהוֹן, בְּשַׁעֲתָא דְּקָארוּן לֵיהּ, הוּא זַמִּין לוֹן. בְּשַׁעֲתָא דְּאִינּוּן בְּעָאקוּ, הוּא לְגַבַּיְיהוּ, הוּא אוֹקִיר לוֹן בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי, הֲדָא הוּא דִכְתִיב, (תהילים צ״א:י״ד) כִּי בִי חָשַׁק וַאֲפַלְּטֵהוּ אֲשַׂגְּבֵהוּ כִּי יָדַע שְׁמִי.","(במדבר כ״א:ל״ד) וַיֹּאמֶר יְיָ אֶל מֹשֶׁה אַל תִּירָא אוֹתוֹ וְגוֹ'. רִבִּי יְהוּדָה פָּתַח, (משלי ל״א:כ״א) לֹא תִירָא לְבֵיתָהּ מִשָּׁלֶג כִּי כָל בֵּיתָה לָבוּשׁ שָׁנִים. תָּא חֲזֵי, כְּנֶסֶת יִשְׂרָאֵל יַנְקָא מִתְּרֵי סִטְרֵי, הַשְׁתָּא בְּרַחֲמֵי, הַשְׁתָּא בְּדִינָא. כַּד בַּעְיָא לְיַנְקָא בְּרַחֲמֵי, אִשְׁתְּכַח אֲתָר לְאִתְיַשְּׁבָא בֵּיהּ. כַּד בָּעֵי לְיָנְקָא בְּדִינָא, אֲתָר אִשְׁתְּכַח לְאִתְיַשְּׁבָא בֵּיהּ, וּלְמִשְׁרֵי עָלוֹהִי, דְּהָכִי הוּא בְּכָל אֲתָר, לָא שָׁארֵי מִלָּה דִּלְעֵילָּא, עַד דְּאִשְׁתְּכַח אֲתָר לְמִשְׁרֵי עֲלוֹי. וְעַל דָּא, כְּנֶסֶת יִשְׂרָאֵל לֹא תִירָא לְבֵיתָא מִשָּׁלֶג, מַאי טַעְמָא, בְּגִין דְּכָל בֵּיתָא לָבוּשׁ שָׁנִים. לָא שַׁרְיָא הַאי, אֶלָּא בְּהַאי חִוָּור בְּסוּמָק, וְסוּמָק בְּחִוָּור. וְהָא אוֹקְמוּהָ.","וַיֹּאמֶר יְיָ אֶל מֹשֶׁה אַל תִּירָא אוֹתוֹ, תְּרֵין אוֹתוֹ אִינּוּן שְׁלֵימִין בְּאוֹרַיְיתָא בִּתְרֵין וָוִי\"ן, חַד דָּא, וְחַד, (דברים כ״ב:ב׳) עַד דְּרוֹשׁ אָחִיךָ אוֹתוֹ. מַאי טַעְמָא. בְּגִין דְּאִינּוּן אוֹת מַמָּשׁ. עַד דְּרוֹשׁ אָחִיךָ (אחיך ממש) אוֹתוֹ, דְּבָעֵי לְפָרְשָׁא הַהוּא אוֹת, דְּהַהוּא אֲבֵידָה.","אוּף הָכָא דֵּין אוֹתוֹ, דָּא עוֹג, דְּאִתְדַּבָּק בְּאַבְרָהָם, וּמֵאַנְשֵׁי בֵּיתֵיהּ הֲוָה, וְכַד אִתְגְּזַר אַבְרָהָם מַה כְּתִיב, וְכָל אַנְשֵׁי בֵיתוֹ וְגוֹ'. דָּא עוֹג דְּאִתְגְּזַר עִמֵּיהּ, וְקַבִּיל הַאי אָת קַדִּישָׁא, כֵּיוָן דְּחָמָא עוֹג דְּיִשְׂרָאֵל מְקָרְבִין גַּבֵּיהּ, אָמַר הָא ודַּאי אֲנָא אַקְדִּימְנָא זְכוּתָא דְּקָאִים לוֹן, וְדָא שַׁוִּי לְקָבְלֵיהּ.","בֵּיהּ שַׁעֲתָא דָּחִיל מֹשֶׁה, הֵיךְ יָכִיל לְאַעְקְרָא רְשִׁימָא דְּרָשִׁים אַבְרָהָם. אָמַר, וַדַּאי הָא יְמִינָא דִּילִי מִית, דְּהָא יְמִינָא בַּעְיָא לְהַאי. אִי נֵימָא הָא אֶלְעָזָר, יְמִינָא דְּסִיהֲרָא הוּא, וְלָא דִּילִי. וְהַאי אָת לִימִינָא הוּא, דְּאַבְרָהָם לִימִינָא הוּא.","מִיָּד אָמַר קוּדְשָׁא בְּרִיךְ הוּא, אַל תִּירָא אוֹתוֹ, לָא תִּדְּחַל לְהַהוּא אֹת דִּילֵיהּ, וַאֲפִילּוּ לִימִינָא לָא אִצְטְרִיךְ. כִּי בְיָדְךָ נָתַתִּי. שְׂמָאלָא דִּילָךְ יַעְקָר לֵיהּ מֵעָלְמָא, דְּהָא הוּא פָּגִים רְשִׁימָא דִּילֵיהּ, וּמַאן דְּפָגִים לְהַאי אָת, אִתְחֲזֵי לְאִתְעַקְּרָא מֵעָלְמָא, כָּל שֶׁכֵּן שְׂמָאלָא דִּילָךְ, דְּאִיהוּ יְדָךְ, יֶעְקָר לֵיהּ מֵעָלְמָא, בְּגִין כַּךְ אִתְּעֲקָר מֵעָלְמָא, וַאֲפִילּוּ דְּאִיהוּ תַּקִּיפָא מִבְּנֵי גַּבְרַיָּיא, וּבָעָא לְשֵׁיצָאָה לְהוּ לְיִשְׂרָאֵל, נָפַל בִּידֵיהּ דְּמֹשֶׁה וְאִשְׁתְּצֵי."],[[0,"אוף הכא הוו וכו':","אף כאן, על הבאר, אמרו ישראל דברים אלו שהם דברי אמת, כדי לעורר את הבאר הזה, שהיא המלכות, ולהשקות את ישראל. וכל עוד שלא אמרו דברים אלו, לא נתעוררה הבאר. וכן אפילו באלו מכשפי עולם, שמשתמשים במינים הרעים, עד שעושים אליהם מעשים של אמת, ואם לא היו אומרים דברי אמת כדי להמשיכם באותם אפנים שהם רוצים, לא היו מתעוררים אליהם. ואפילו היו צועקים כל היום בדברים אחרים או מעשים אחרים, לא היו מושכים אותם אליהם לעולם, ולא היו מתעוררים כנגדם."],[1,"ת\"ח כתיב ויקראו וגו':","בוא וראה, כתוב ויקראו בשם הבעל וגו'. מהו הטעם שלא נענו. ומשיב אחד, משום שלא היו רשות לבעל ההוא בזה, להוריד אש מן השמים. ועוד, משום שהדברים לא היו ישרים ביניהם, והקב\"ה השכיח אותם מהם. ז\"ש ואתה הסבות את לבם אחורנית. אשרי הם הצדיקים היודעים לקרוא את אדונם כראוי."],[2,"אמר רבי שמעון וכו':","אר\"ש, כאן אני רוצה לגלות דבר. בוא וראה כל מי שיודע לסדר מעשה כראוי, ולסדר דיבורים כראוי, הרי ודאי שמעוררים את הקב\"ה להמשיך דברים עליונים ישרים. ואם לא אינו מתרצה אליהם. ואם כן, הרי כל העולם יודעים לסדר המעשה ולסדר דיבורים, מהו החשיבות שלהם, של הצדיקים, היודעים שורש הדיבור והמעשה, ויודעים לכוון הלב והרצון יותר מאלו האחרים שאינם יודעים כל כך."],[3,"אלא אלין דלא וכו':","ומשיב, אלא אלו שאינם יודעים שורש המעשה כל כך, אלא רק סדור בלבד ולא יותר, מושכים עליהם משיכה שלאחר כתפיו של הקב\"ה, שאין תפלתם פורח באויר (כמ\"ש לעיל ויקהל אות ק\"ל ע\"ש) הנקרא השגחה. כלומר, שזה הוא השגחה של פנים, והם אינם ראויים אלא לבחינת מאחורי כתפים."],[4,"ואלין דידעי ומכווני וכו':","ואלו היודעים ומכוונים הלב והרצון, מוציאים ברכות ממקום המחשבה, שהיא חכמה, ויוצאים בכל הגזעים והשרשים של המדרגות בדרך ישר כראוי, עד שמתברכים העליונים ותחתונים, והשם הקדוש העליון מתברך על ידיהם. אשרי חלקם, כי הקב\"ה קרוב אליהם ומזומן כנגדם, ובשעה שקוראים אותו הוא מוכן אליהם, ובשעה שהם בצרה, הוא אצלם, הוא מכבדם בעולם הזה ובעולם הבא. ז\"ש, כי בי חשק ואפלטהו אשגבהו כי ידע שמי."],[5,"ויאמר","וגו' \u0003אל תירא אותו:\u0004 רבי יהודה פתח לא תירא לביתה משלג כי כל ביתה לבוש שנים. בוא וראה, כנסת ישראל יונקת מב' צדדים, פעם ברחמים ופעם בדין. כשרוצה לינק ברחמים, נמצא מקום שהרחמים יתישבו בו. כשרוצה לינק בדין, נמצא מקום, שהדין יתישב בו, ולשרות עליו. כי כך הוא בכל מקום, שאינו שורה דבר שלמעלה עד שנמצא מקום שישרה עליו. וע\"כ כנסת ישראל, לא תירא לביתה משלג. מהו הטעם, הוא משום שכל ביתה לבוש שנים. זה אינו שורה אלא בזה, לבן באדום, ואדום בלבן. והרי העמידוהו."],[5,"","פירוש. אין הימין, שהוא חסד, שלם בלי השמאל שהוא דין וכן להיפך. כי קו ימין ה\"ס נקודת החולם שבו אין ה \u0003י'\u0004 יוצאת מאויר, והוא ו\"ק חסר ג\"ר. וע\"כ הוא צריך לשמאל שממנו נמשך החכמה, ואז יש לו לימין ג\"ר. וקו השמאל, ה\"ס נקודת השורק, (עי' לעיל ב\"א ט\"ו ד\"ה ההיא) שבו יוצא ה \u0003י'\u0004 מאויר, ויש לו חכמה, אבל חכמה בלי חסדים הם דינים קשים, ואינה יכולה להאיר (כמ\"ש שם). ולפיכך אין המלכות מושכת חסדים שה\"ס ימין ורחמים, עד שיש לה מכבר הארת החכמה, שאז נעשה הארת החכמה מקום ובית קבול לאור הרחמים והחסדים, שהם נעשים בו בחינת ג\"ר. וכן אין המלכות מושכת החכמה משמאל, שהוא דין, אלא א\"כ יש לה חסדים ורחמים מכבר, ואז החכמה מתלבשת תוך החסדים ומאירה, וכל עוד שאין לה חסדים החכמה שמקבלת היא חשך ולא אור (כנ\"ל ב\"א דף מ\"ז ד\"ה נפק ע\"ש) הרי שהחסדים הם מקום ובית קבול אל החכמה."],[5,"","וז\"ש, \u0003כנ\"י ינקא מתרי סטרי\u0004 וכו' ברחמים מימין, ובחכמה משמאל, שהוא דין, כי אין החכמה מאירה אלא עם דינים (כנ\"ל פקודי אות שע\"ו). \u0003כד בעיא לינקא ברחמי,\u0004 דהיינו מקו ימין, שהוא חסד ורחמים. \u0003אשתכח אתר לאתיישבא ביה\u0004 דהיינו שנמצא בה מוכנת הארת השמאל שהיא החכמה שהיא מקום ששם מתישבת הארת הימין, ונשלמת בג\"ר על ידי זה כנ\"ל. \u0003כד בעי לינקא בדינא,\u0004 דהיינו הארת חכמה משמאל הבאה עם דינים קשים, \u0003אתר אשתכח לאתיישבא ביה ולמשרי עלוהי,\u0004 דהיינו החסד שמימין הנמצא בה שהוא מקום ששם מתישבת ומתלבשת הארת החכמה שבשמאל. \u0003לא שארי מלה דלעילא עד דאשתכח אתר לאתישבא ביה\u0004 וכו', דהיינו שלא יוכל לשרות שלמות מלמעלה מטרם שיש לה מקום לכלול ולהתלבש בו, אם הוא שפע הימין צריך למקום משמאל, ואם הוא שפע השמאל צריך למקום מימין, כנ\"ל."],[5,"","ונודע, שאם החכמה מאירה לבדה במלכות בלי התישבות בחסדים, אז המלכות נקפאת (כנ\"ל ב\"א דף רמ\"ז ד\"ה ימא דקאפו ע\"ש) וז\"ש, \u0003וע\"ד כנסת ישראל לא תירא לביתה משלג,\u0004 דהיינו שאינה יראה מקפאון \u0003מאי טעמא, בגין דכל ביתה לבוש שנים,\u0004 אל תקרי שנים, אלא שנים, שהשין שואית והנון פתוחה, דהיינו שני אורות, חכמה וחסדים יחדיו אשר אז אין האורות נקפאים (כמ\"ש שם). וז\"ש \u0003לא שריא האי אלא בהאי, חוור בסומק,\u0004 חסד שמימין שה\"ס לבן, שורה בחכמה שבשמאל שה\"ס אדום. וכן, סומק \u0003בחוור,\u0004 שחכמה שבשמאל שה\"ס אדום, שורה בחסדים שבימין שה\"ס לבן."],[6,"ויאמר","וגו' \u0003אל תירא אותו:\u0004 ב' פעמים בתורה נמצאות \u0003אותו\u0004 שהן שלמות בב' ווין. (כך היה בס\"ת שלהם). אחד כאן. ואחד עד דרוש אחיך \u0003אותו.\u0004 מהו הטעם. הוא משום שפירושם אות ממש, ואינן נגזרות מהמלה, את. \u0003עד דרוש אחיך אותו,\u0004 פירושו שצריך לפרש סימן ואות של אבידה ההיא."],[7,"אוף הכא דין אותו וכו':","אף כאן אותו זה, הוא עוג שנתדבק באברהם, ומאנשי ביתו היה, וכשנמול אברהם, מה כתוב, וכל אנשי ביתו וגו'. שזה עוג שנמול עמו וקבל אות קדוש הזה. כיון שראה עוג, שישראל מתקרבים אליו, אמר הרי ודאי אני הקדמתי המצוה העומדת להם, כי הקדים להמול לפני יצחק אבינו. וזה שם כנגדו. לבטוח בו."],[8,"ביה שעתא דחיל וכו':","בו בשעה ירא משה, איך הוא יכול לעקור הרושם שרשם אברהם. אמר ודאי הרי הימין שלי, שהוא אהרן, מת. כי צריכים ימין לנצח את זה. ואם נאמר שיש אלעזר. הוא הימין של הלבנה, דהיינו של המלכות, ולא שלי, שאינו ימין דז\"א שה\"ס משה, כמו אהרן. ואות הזה, של עוג, הוא לימין דז\"א, כי אברהם הוא ימין דז\"א."],[9,"מיד אמר קב\"ה וכו':","מיד אמר הקב\"ה, אל תירא \u0003אותו.\u0004 אל תירא מפני אות שלו, ואפילו לימין אינו צריך. \u0003כי בידך נתתי,\u0004 השמאל שלך יעקר אותו מן העולם. כי הוא, עוג, פגם את רושם \u0003הברית\u0004 שלו, ומי שפגם אות הזה ראוי להתעקר מן העולם מעצמו. כל שכן השמאל שלך, שהוא \u0003ידך,\u0004 יעקר אותו מן העולם. ומשום זה נתעקר מן העולם. ואע\"פ שהוא גבור מבני הגבורים ומשום שרצה להשמיד את ישראל נפל בידי משה ונשמד."]],[[0,"","גַּם כָּאן הָיוּ יִשְׂרָאֵל אוֹמְרִים דִּבּוּרִים אֵלֶּה, דִּבְרֵי אֱמֶת, כְּדֵי לְעוֹרֵר בְּאֵר הַזֹּאת וּלְהַשְׁקוֹתָם לְיִשְׂרָאֵל, וְעַד שֶׁאוֹמְרִים מִלִּים אֵלּוּ, לֹא מִתְעוֹרֶרֶת. וְכֵן אֲפִלּוּ בְּאוֹתָם מְכַשְּׁפֵי הָעוֹלָם שֶׁמִּשְׁתַּמְּשִׁים בְּמִינִים רָעִים, עַד שֶׁעוֹשִׂים מַעֲשֵׂיהֶם שֶׁל אֱמֶת אֲלֵיהֶם - אִם לֹא אוֹמְרִים דִּבְרֵי אֱמֶת בִּשְׁבִיל לְהַמְשִׁיךְ אוֹתָם בִּגְוָנִים אֵלּוּ שֶׁרוֹצִים, לֹא מִתְעוֹרְרִים לְגַבֵּיהֶם. וַאֲפִלּוּ שֶׁצּוֹוְחִים כָּל הַיּוֹם בִּדְבָרִים אֲחֵרִים אוֹ בְּמַעֲשֶׂה אַחֵר, לֹא מוֹשְׁכִים אוֹתָם אֲלֵיהֶם לְעוֹלָמִים וְלֹא מִתְעוֹרְרִים אֲלֵיהֶם."],[1,"","בֹּא וּרְאֵה, כָּתוּב (מלכים א יח) וַיִּקְרְאוּ בְשֵׁם הַבַּעַל וְגוֹ'. מָה הַטַּעַם? אֶחָד, שֶׁאֵין רְשׁוּת בְּאוֹתוֹ בַּעַל בָּזֶה. וְעוֹד, שֶׁהַדְּבָרִים לֹא מֻכְשָׁרִים בֵּינֵיהֶם, וְהִשְׁכִּיחָם הַקָּדוֹשׁ בָּרוּךְ הוּא מֵהֶם. זֶהוּ שֶׁכָּתוּב (שם) וְאַתָּה הֲסִבּתָ אֶת לִבָּם אֲחֹרַנִּית. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁיּוֹדְעִים לִקְרֹא לְרִבּוֹנָם כָּרָאוּי."],[2,"","אָמַר רַבִּי שִׁמְעוֹן, כָּאן צָרִיךְ לְגַלּוֹת דָּבָר. בֹּא וּרְאֵה, כָּל מִי שֶׁיּוֹדֵעַ לְסַדֵּר מַעֲשֶׂה כָּרָאוּי וּלְסַדֵּר דְּבָרִים כָּרָאוּי, זֶה בְּוַדַּאי מְעוֹרֵר אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַמְשִׁיךְ דְּבָרִים עֶלְיוֹנִים שֶׁמֻּכְשָׁרִים. (ואם לא, לא יכשר להם). וְלֹא הֻכְשַׁר לָהֶם. אִם כָּךְ, כָּל הָעוֹלָם יוֹדְעִים לְסַדֵּר מַעֲשֶׂה וּלְסַדֵּר דְּבָרִים, מַה חֲשִׁיבוּת הַצַּדִּיקִים שֶׁיּוֹדְעִים עִקַּר הַדָּבָר וְהַמַּעֲשֶׂה, וְיוֹדְעִים לְכַוֵּן לֵב וְרָצוֹן יוֹתֵר מֵאֵלּוּ הָאֲחֵרִים שֶׁלֹּא יוֹדְעִים כָּל כָּךְ?"],[3,"","אֶלָּא אֵלֶּה שֶׁלֹּא יוֹדְעִים עִקַּר הַמַּעֲשֶׂה כָּל זֶה, אֶלָּא סִדּוּר בְּעָלְמָא וְלֹא יוֹתֵר, מוֹשְׁכִים עֲלֵיהֶם מְשִׁיכוּת שֶׁאַחַר כִּתְפֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא טָס בָּאֲוִיר, שֶׁהַשְׁגָּחָה נִקְרָא."],[4,"","וְאֵלֶּה שֶׁיּוֹדְעִים וּמְכַוְּנִים לֵב וְרָצוֹן, מוֹצִיאִים בְּרָכוֹת מִמְּקוֹם הַמַּחֲשָׁבָה, וְיוֹצְאִים בְּכָל הַגְּזָעִים וְהַשָּׁרָשִׁים בְּדֶרֶךְ יָשָׁר כָּרָאוּי, עַד שֶׁמִּתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים, וְשֵׁם הַקָּדוֹשׁ מִתְבָּרֵךְ עַל יָדָם. אַשְׁרֵי חֶלְקָם, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא קָרוֹב אֲלֵיהֶם וּמְזֻמָּן כְּנֶגְדָּם. בְּשָׁעָה שֶׁקּוֹרְאִים לוֹ הוּא מְזֻמָּן אֲלֵיהֶם. בְּשָׁעָה שֶׁהֵם בְּצָרָה הוּא אֶצְלָם. הוּא מְכַבֵּד אוֹתָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. זֶהוּ שֶׁכָּתוּב (תהלים צא) כִּי בִי חָשַׁק וַאֲפַלְּטֵהוּ אֲשַׂגְּבֵהוּ כִּי יָדַע שְׁמִי."],[5,"","וַיֹּאמֶר ה' אֶל מֹשֶׁה אַל תִּירָא אֹתוֹ וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (משלי לא) לֹא תִירָא לְבֵיתָהּ מִשָּׁלֶג כִּי כָל בֵּיתָהּ לָבֻשׁ שָׁנִים. בֹּא וּרְאֵה, כְּנֶסֶת יִשְׂרָאֵל יוֹנֶקֶת מִשְּׁנֵי צְדָדִים, כָּעֵת בְּרַחֲמִים, כָּעֵת בְּדִין. כְּשֶׁרוֹצָה לִינֹק בְּרַחֲמִים, נִמְצָא מָקוֹם לְהִתְיַשֵּׁב בּוֹ. כְּשֶׁרוֹצֶה לִינֹק בְּדִין, מָקוֹם נִמְצָא לְהִתְיַשֵּׁב בּוֹ וְלִשְׁרוֹת עָלָיו, שֶׁכָּךְ הוּא בְּכָל מָקוֹם - לֹא שׁוֹרֶה דָבָר שֶׁלְּמַעְלָה עַד שֶׁנִּמְצָא מָקוֹם לִשְׁרוֹת עָלָיו. וְעַל כָּךְ כְּנֶסֶת יִשְׂרָאֵל לֹא תִירָא לְבֵיתָהּ מִשָּׁלֶג, מָה הַטַּעַם? מִשּׁוּם שֶׁכָּל בֵּיתָהּ לָבֻשׁ שָׁנִים, לֹא שׁוֹרֶה זֶה אֶלָּא בָּזֶה, לָבָן בְּאָדם וְאָדם בְּלָבָן, וַהֲרֵי פֵּרְשׁוּהָ. (בא ראה, כתוב)"],[6,"","וַיֹּאמֶר ה' אֶל מֹשֶׁה אַל תִּירָא אֹתוֹ (אותו). שְׁנֵי אוֹתוֹ הֵם שְׁלֵמִים בַּתּוֹרָה בִּשְׁנֵי וָוִי\"ם, אֶחָד זֶה, וְאֶחָד - (דברים כב) עַד דְּרֹשׁ אָחִיךְ אֹתוֹ (אותו). מָה הַטַּעַם? מִשּׁוּם שֶׁהֵם אוֹת מַמָּשׁ. עַד דְּרשׁ אָחִיךְ (אחיך ממש) אֹתוֹ (אותו), שֶׁצָּרִיךְ לְפָרֵשׁ אֶת אוֹתוֹ הָאוֹת שֶׁל אוֹתָהּ אֲבֵדָה."],[7,"","גַּם כָּךְ אוֹתוֹ הַזֶּה, זֶה עוֹג שֶׁנִּדְבַּק בְאַבְרָהָם, וּמֵאַנְשֵׁי בֵיתוֹ הָיָה, וּכְשֶׁנִּמּוֹל אַבְרָהָם מַה כָּתוּב? (בראשית יז) וְכָל אַנְשֵׁי בֵיתוֹ וְגוֹ'. זֶה עוֹג שֶׁנִּמּוֹל עִמּוֹ וְקִבֵּל אוֹת הַקָּדוֹשׁ הַזֶּה. כֵּיוָן שֶׁרָאָה עוֹג שֶׁיִּשְׂרָאֵל מִתְקָרְבִים אֵלָיו, אָמַר: הֲרֵי וַדַּאי אֲנִי הִקְדַּמְתִּי זְכוּת שֶׁעוֹמֶדֶת לָהֶם, וְזֶה שָׂם לְמוּלוֹ."],[8,"","בְּאוֹתָהּ שָׁעָה פָּחַד מֹשֶׁה, אֵיךְ יָכוֹל לַעֲקֹר רשֶׁם שֶׁרָשַׁם אַבְרָהָם? אָמַר, בְּוַדַּאי הַיָּמִין שֶׁלִּי מֵת, שֶׁהֲרֵי הַיָּמִין צָרִיךְ לָזֶה. אִם נֹאמַר הֲרֵי אֶלְעָזָר - יְמִין הַלְּבָנָה הוּא וְלֹא יְמִינִי. וְהָאוֹת הַזֶּה לְיָמִין הוּא, שֶׁאַבְרָהָם הוּא לְיָמִין."],[9,"","מִיָּד אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אַל תִּירָא אֹתוֹ. אַל תִּירָא אֶת אוֹתוֹ הָאוֹת שֶׁלּוֹ, וַאֲפִלּוּ לַיָּמִין לֹא צָרִיךְ. כִּי בְיָדְךְ נָתַתִּי. שְׂמֹאלְךְ תַּעֲקֹר אוֹתוֹ מֵהָעוֹלָם, שֶׁהֲרֵי הוּא פָּגַם הָרֹשֶׁם שֶׁלּוֹ, וּמִי שֶׁפּוֹגֵם אוֹת זוֹ רָאוּי לְהֵעָקֵר מֵהָעוֹלָם, כָּל שֶׁכֵּן שְׂמֹאל שֶׁלְּךְ, שֶׁהִיא יָדְךְ, יַעֲקֹר אוֹתוֹ מֵהָעוֹלָם, בִּגְלַל זֶה נֶעֱקַר מֵהָעוֹלָם. וַאֲפִלּוּ שֶׁהוּא תַּקִּיף מִבְּנֵי הַגִּבּוֹרִים וְרָצָה לְהַשְׁמִיד אֶת יִשְׂרָאֵל, נָפַל בִּידֵי מֹשֶׁה וְהֻשְׁמַד."]]],[["בְּגִין כַּךְ כֹּלָּא שֵׁצִיאוּ יִשְׂרָאֵל בְּנוֹי וְכָל עַמֵּיהּ, וְכָל דִּילֵיהּ. כְּמָה דִּכְתִּיב, וַיַּכּוּ אוֹתוֹ וְאֶת בָּנָיו וְאֶת כָּל עַמּוֹ וּכְתִיב, (דברים ב׳:ל״ג) וַנַּךְ אוֹתוֹ וְאֶת בָּנָו. בְּנוֹ כְּתִיב חָסֵר יוֹ\"ד, וְקָרֵינָן בָּנָיו, וְהָא אוּקְמוּהָ חַבְרַיָּיא.","זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּמֹשֶׁה נְבִיאָה הֲוָה בֵּינַיְיהוּ, דִּבְגִינֵיהּ עָבִיד לוֹן קוּדְשָׁא בְּרִיךְ הוּא כָּל הָנֵי אַתְוָון, וְאוֹקְמוּהָ. וְקוּדְשָׁא בְּרִיךְ הוּא לָא גָּזַר קַיָּימֵיהּ עִם שְׁאַר עַמִּין לְאִתְקַשְּׁרָא בֵּיהּ, אֶלָּא עִם יִשְׂרָאֵל, דְּאִינּוּן בְּנוֹי דְּאַבְרָהָם, דִּכְתִּיב בּוֹ (בראשית י״ז:ז׳) וּבֵין זַרְעֲךָ אַחֲרֶיךָ לְדֹרֹתָם בְּרִית עוֹלָם. וּכְתִיב (ישעיהו נ״ט:כ״א) וַאֲנִי זֹאת בְּרִיתִי אוֹתָם אָמַר יְיָ רוּחִי אֲשֶׁר עָלֶיךָ וְגוֹ'. לֹא יָמוּשׁוּ מִפִּיךָ וְגוֹ'. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן"],[[0,"בגין כך כלא וכו':","משום זה השמידו ישראל הכל, בניו וכל עמו וכל אשר לו. כמי שכתוב ויכו אותו ואת בניו ואת כל עמו. וכתוב ונך אותו ואת בנו. בנו כתוב, חסר \u0003י'\u0004 של סימן הרבים, וקוראים בניו. וכבר העמידוהו החברים (תנחומא סוף חוקת)."],[1,"זכאין אינון ישראל וכו':","אשרי הם ישראל שמשה הנביא היה ביניהם, שבשבילו עשה הקב\"ה כל אלו האותות. והעמידוהו. והקב\"ה לא כרת בריתו עם שאר העמים להתקשר בהם, אלא עם ישראל, שהם בניו של אברהם, שכתוב בו, ובין זרעך אחריך לדרתם ברית עולם. וכתוב, ואני זאת בריתי אותם אמר ה' רוחי אשר עליך וגו', לא ימושו מפיך וגו'."],[1,"","ברוך ה' לעולם אמן ואמן."]],[[0,"","בִּגְלַל זֶה הַכֹּל הִשְׁמִידוּ יִשְׂרָאֵל, בָּנָיו וְכָל עַמּוֹ וְכָל אֲשֶׁר לוֹ, כְּמוֹ שֶׁכָּתוּב וַיַּכּוּ אֹתוֹ וְאֶת בָּנָיו וְאֶת כָּל עַמּוֹ, וְכָתוּב (דברים ב) וַנַּךְ אֹתוֹ וְאֶת בָּנָו. בְּנוֹ כָּתוּב, חָסֵר יוֹ\"ד, וְקוֹרְאִים בָּנָיו, וַהֲרֵי פֵּרְשׁוּהוּ הַחֲבֵרִים."],[1,"","אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁמֹּשֶׁה הַנָּבִיא הָיָה בֵּינֵיהֶם, שֶׁבִּגְלָלוֹ עָשָׂה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא כָּל הָאוֹתוֹ הַלָּלוּ, וּפֵרְשׁוּהָ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא גָזַר בְּרִיתוֹ עִם שְׁאָר הָעַמִּים לְהִתְקַשֵּׁר בּוֹ, אֶלָּא עִם יִשְׂרָאֵל, שֶׁהֵם בְּנֵי אַבְרָהָם, שֶׁכָּתוּב בּוֹ (בראשית יז) וּבֵין זַרְעֲךְ אַחֲרֶיךְ לְדרֹתָם לִבְרִית עוֹלָם. וְכָתוּב (ישעיה נט) וַאֲנִי זֹּאת בְּרִיתִי אוֹתָם אָמַר ה' רוּחִי אֲשֶׁר עָלֶיךְ וְגוֹ', לֹא יָמוּשׁוּ מִפִּיךְ וְגוֹ'. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן."]]]]};
